INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(901, 26, 'In an ER diagram, what does a rectangle represent?', 'An entity set', 'An attribute', 'A relationship set', 'A key constraint', 'A', 'A rectangle in the Chen ER notation represents an entity set, a collection of similar entities.', 'BEGINNER', 1, 'MCQ', 1),
(902, 26, 'What symbol is used to represent an attribute in a standard Chen ER diagram?', 'An ellipse', 'A rectangle', 'A diamond', 'A triangle', 'A', 'Attributes are drawn as ellipses that connect to their entity via lines in Chen notation.', 'BEGINNER', 1, 'MCQ', 1),
(903, 26, 'Which symbol in an ER diagram represents a relationship between entity sets?', 'A diamond', 'A circle', 'A square', 'A hexagon', 'A', 'A diamond shape is used to denote a relationship set connecting two or more entity sets.', 'BEGINNER', 1, 'MCQ', 1),
(904, 26, 'An entity in an ER model is best described as:', 'A distinguishable object or thing about which data is stored', 'A row inside a database table', 'A constraint between two tables', 'A query that returns data', 'A', 'An entity is a distinct real-world object or concept that the database stores information about.', 'BEGINNER', 1, 'MCQ', 1),
(905, 26, 'Which of the following is a valid example of an entity set in a library database?', 'Books', 'Borrow dates', 'Author names as text', 'ISBN validation rules', 'A', 'Books is an entity set, while borrow dates and author names are attributes and validation rules are constraints.', 'BEGINNER', 1, 'MCQ', 1),
(906, 26, 'An attribute that can be divided into smaller meaningful parts is called:', 'A composite attribute', 'A derived attribute', 'A key attribute', 'A multivalued attribute', 'A', 'A composite attribute such as full address can be split into street, city and zip sub-parts.', 'BEGINNER', 1, 'MCQ', 1),
(907, 26, 'What type of attribute can take on more than one value for a single entity?', 'A multivalued attribute', 'A derived attribute', 'A composite attribute', 'A single-valued attribute', 'A', 'A multivalued attribute such as phone_numbers holds a collection of values for one entity.', 'BEGINNER', 1, 'MCQ', 1),
(908, 26, 'In an ER diagram, a double-bordered rectangle represents:', 'A weak entity set', 'A strong entity set', 'A derived entity set', 'A composite entity set', 'A', 'Weak entity sets are drawn with double borders because they cannot be identified without their owner.', 'BEGINNER', 1, 'MCQ', 1),
(909, 26, 'The cardinality ratio for the relationship ''a student enrolls in many courses and a course has many students'' is:', 'Many-to-many', 'One-to-many', 'One-to-one', 'Many-to-one', 'A', 'Multiple students can enroll in multiple courses, giving a many-to-many relationship.', 'BEGINNER', 1, 'MCQ', 1),
(910, 26, 'Which of the following is an example of a derived attribute?', 'A person''s age', 'A person''s date of birth', 'A person''s social security number', 'A person''s name', 'A', 'Age is derived from the date of birth, so it is computed rather than stored directly.', 'BEGINNER', 1, 'MCQ', 1),
(911, 26, 'An employee works in exactly one department, but a department has many employees. What is the cardinality of this relationship from department to employee?', 'One-to-many', 'Many-to-many', 'One-to-one', 'Zero-to-many', 'A', 'Since one department has many employees but an employee belongs to one department, the ratio is one-to-many.', 'INTERMEDIATE', 2, 'MCQ', 1),
(912, 26, 'Which situation requires modeling an entity as a weak entity set?', 'A room whose identity depends on the hotel it belongs to', 'A customer who has a globally unique customer ID', 'A product with a unique SKU', 'A country with a primary key', 'A', 'A weak entity like a hotel room has no sufficient attributes of its own and depends on its identifying owner.', 'INTERMEDIATE', 2, 'MCQ', 1),
(913, 26, 'The double diamond symbol in an ER diagram is used to indicate:', 'An identifying relationship for a weak entity set', 'A many-to-many relationship', 'A derived relationship', 'A ternary relationship', 'A', 'A double diamond denotes the identifying relationship that links a weak entity set to its strong owner.', 'INTERMEDIATE', 2, 'MCQ', 1),
(914, 26, 'A professor teaches many sections, but each section is taught by exactly one professor. The participation of section in ''teaches'' is best described as:', 'Total participation', 'Partial participation', 'No participation', 'Conditional participation', 'A', 'Every section must have a professor, so the section side has total participation in the relationship.', 'INTERMEDIATE', 2, 'MCQ', 1),
(915, 26, 'An entity set with no sufficient attributes to form a primary key is called:', 'A weak entity set', 'A composite entity set', 'A derived entity set', 'An attribute-only set', 'A', 'A weak entity set lacks enough attributes to form its own primary key and relies on its owner.', 'INTERMEDIATE', 2, 'MCQ', 1),
(916, 26, 'In ER design, a multivalued attribute is best handled in a relational schema by:', 'Creating a separate relation for the attribute', 'Storing all values in a single comma-separated column', 'Making the attribute the primary key', 'Deleting the attribute entirely', 'A', 'Multivalued attributes are stored in their own relation whose key combines the entity key with the attribute value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(917, 26, 'A relationship that connects three entity sets is known as:', 'A ternary relationship', 'A binary relationship', 'A recursive relationship', 'A composite relationship', 'A', 'A ternary relationship involves three participating entity sets, such as Supplier-Part-Warehouse.', 'INTERMEDIATE', 2, 'MCQ', 1),
(918, 26, 'A ''subclass'' in an EER model, such as Salaried vs. Hourly employees, is captured using:', 'Specialization and generalization', 'Weak entity sets only', 'Multivalued attributes only', 'Ternary relationships only', 'A', 'Specialization/generalization hierarchies model subclasses that share attributes of a superclass.', 'INTERMEDIATE', 2, 'MCQ', 1),
(919, 26, 'Which of these is a good reason to prefer a weak entity set over a multivalued attribute for storing a list?', 'When each list item has its own attributes, such as a room with a capacity and floor', 'When the list must always be short', 'When the list values are never queried', 'When the list has only one value', 'A', 'When each item carries its own descriptive attributes, modeling it as a weak entity set is appropriate.', 'INTERMEDIATE', 2, 'MCQ', 1),
(920, 26, 'In mapping an ER diagram to relations, a one-to-many relationship is best represented by:', 'Adding the primary key of the ''one'' side as a foreign key in the ''many'' side', 'Creating a separate relation with only the two keys', 'Merging both entities into one relation', 'Ignoring the relationship', 'A', 'Placing the primary key of the one side into the many side relation as a foreign key captures one-to-many semantics.', 'INTERMEDIATE', 2, 'MCQ', 1),
(921, 26, 'In an ER design for a hospital, each patient has a record number that only makes sense within their doctor''s practice. This suggests modeling Patient as:', 'A weak entity set identified by the doctor', 'A strong entity set with an independent key', 'A derived entity set', 'An attribute of Doctor', 'A', 'Because the record number is only meaningful per practice, Patient depends on Doctor and is a weak entity set.', 'ADVANCED', 3, 'MCQ', 1),
(922, 26, 'You are mapping a many-to-many relationship with a descriptive attribute called since_date. The correct relational mapping is:', 'A separate relation with both entity keys plus since_date', 'Add since_date to either entity relation', 'Discard since_date to preserve normal form', 'Store since_date only in the application layer', 'A', 'A relationship relation containing both primary keys and the descriptive attribute since_date preserves the association.', 'ADVANCED', 3, 'MCQ', 1),
(923, 26, 'A student entity has attributes student_id and email, and email can be used to look up the student. If email is chosen as the primary key, student_id becomes:', 'A candidate key that was not chosen', 'A superkey', 'A foreign key', 'A composite attribute', 'A', 'student_id and email are both candidate keys; the one not selected as primary key remains a candidate key.', 'ADVANCED', 3, 'MCQ', 1),
(924, 26, 'An ER schema uses a relationship between ''Course'' and ''Prerequisite-Course'' where a course references itself. This is an example of:', 'A recursive relationship', 'A weak relationship', 'A ternary relationship', 'A derived relationship', 'A', 'A course being a prerequisite for another course of the same type is a recursive relationship on one entity set.', 'ADVANCED', 3, 'MCQ', 1),
(925, 26, 'In ER-to-relational mapping, how should a one-to-one relationship between Entity A and Entity B with total participation on both sides be mapped?', 'Merge A and B into a single relation', 'Keep two relations and ignore the relationship', 'Always create a third relation for the relationship', 'Store the relationship in both relations redundantly', 'A', 'With total participation on both sides, merging into one relation is valid and avoids extra joins.', 'ADVANCED', 3, 'MCQ', 1),
(926, 26, 'A superclass ''Vehicle'' has subclasses ''Car'' and ''Truck'', and a vehicle can belong to both subclasses. This is best modeled using:', 'Overlapping specialization', 'Disjoint specialization', 'A weak entity set', 'A multivalued attribute', 'A', 'Overlapping specialization permits an entity to be a member of more than one subclass simultaneously.', 'ADVANCED', 3, 'MCQ', 1),
(927, 26, 'When a weak entity set''s owner is deleted, the weak entity should also be deleted. This requirement maps to which constraint on the relationship?', 'The identifying relationship must enforce on-delete cascade', 'The relationship must be many-to-many', 'The weak entity must have a global key', 'No constraint is needed', 'A', 'Cascading deletion through the identifying relationship preserves the dependency of the weak entity on its owner.', 'ADVANCED', 3, 'MCQ', 1),
(928, 26, 'You have an ER model with a multivalued attribute ''skill_level'' per employee. Which design fully normalizes this into relational tables?', 'A Skill table with (employee_id, skill_level) as a composite key', 'A single Employee table storing skill_level in one column', 'A skill_level column repeated for each employee row', 'Storing skill_level in an XML column', 'A', 'A separate Skill relation keyed by both employee_id and skill_level removes the multivalued attribute cleanly.', 'ADVANCED', 3, 'MCQ', 1),
(929, 26, 'In an EER design, every Cashier is an Employee and every Employee is either Cashier or Manager, but never both. This is:', 'A disjoint, total specialization', 'An overlapping, partial specialization', 'A weak entity hierarchy', 'A ternary relationship', 'A', 'Each employee must be in exactly one subclass, which describes disjoint and total specialization.', 'ADVANCED', 3, 'MCQ', 1),
(930, 26, 'Which normal form violation is prevented when a relationship with a multivalued attribute is split into a separate relation during ER mapping?', 'Violation of the atomicity (1NF) rule for attribute values', 'Violation of the key uniqueness rule', 'Violation of the referential rule', 'Violation of the domain rule', 'A', 'Storing multiple values in one column violates 1NF atomicity, which the separate relation avoids.', 'ADVANCED', 3, 'MCQ', 1),
(931, 27, 'In the relational model, a table is formally called a:', 'Relation', 'File', 'Record', 'Graph', 'A', 'The relational model calls a table a relation, made up of tuples and attributes.', 'BEGINNER', 1, 'MCQ', 1),
(932, 27, 'A row of a relation is formally referred to as a:', 'Tuple', 'Field', 'Attribute', 'Domain', 'A', 'Each row is a tuple, an ordered collection of attribute values.', 'BEGINNER', 1, 'MCQ', 1),
(933, 27, 'A column in a relational table represents a(n):', 'Attribute', 'Tuple', 'Relation', 'Index', 'A', 'A column corresponds to an attribute that describes one property of the entities in the relation.', 'BEGINNER', 1, 'MCQ', 1),
(934, 27, 'Which key uniquely identifies each tuple in a relation?', 'Primary key', 'Foreign key', 'Candidate key is the only unique key', 'Superkey is never unique', 'A', 'The primary key is a chosen key whose value uniquely identifies each tuple in a relation.', 'BEGINNER', 1, 'MCQ', 1),
(935, 27, 'A foreign key in table R references the primary key of table S to enforce:', 'Referential integrity', 'Entity integrity', 'Domain integrity', 'Normalization', 'A', 'Referential integrity ensures every foreign key value matches an existing primary key value in the referenced table.', 'BEGINNER', 1, 'MCQ', 1),
(936, 27, 'Which constraint ensures that the primary key value is never NULL?', 'Entity integrity', 'Referential integrity', 'Domain integrity', 'Check integrity', 'A', 'Entity integrity requires that no part of a primary key can be NULL.', 'BEGINNER', 1, 'MCQ', 1),
(937, 27, 'The set of all possible values that an attribute may take is called its:', 'Domain', 'Tuple', 'Relation', 'Schema', 'A', 'A domain is the pool of permissible values for an attribute, such as integers between 1 and 100.', 'BEGINNER', 1, 'MCQ', 1),
(938, 27, 'The degree of a relation refers to:', 'The number of attributes', 'The number of tuples', 'The number of tables', 'The number of foreign keys', 'A', 'The degree of a relation is the count of its attributes (columns).', 'BEGINNER', 1, 'MCQ', 1),
(939, 27, 'The cardinality of a relation refers to:', 'The number of tuples', 'The number of attributes', 'The number of candidate keys', 'The number of relations', 'A', 'Cardinality counts the tuples (rows) currently present in a relation.', 'BEGINNER', 1, 'MCQ', 1),
(940, 27, 'Which statement about a superkey is correct?', 'A superkey is any set of attributes that uniquely identifies a tuple', 'A superkey must have exactly one attribute', 'A superkey cannot contain a primary key', 'A superkey is always minimal', 'A', 'A superkey is any attribute set whose values uniquely distinguish tuples; it may contain extra attributes.', 'BEGINNER', 1, 'MCQ', 1),
(941, 27, 'A relation EMP(emp_id, dept_id) has emp_id as primary key and dept_id referencing DEPT. If a dept row is deleted while employees still reference it, inserting would be impossible. Which constraint was violated?', 'Referential integrity', 'Entity integrity', 'Domain integrity', 'Tuple uniqueness', 'A', 'Deleting the referenced department leaves dangling dept_id values, which violates referential integrity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(942, 27, 'Which of the following sets could be a valid superkey for a relation whose primary key is A, B?', 'A, B, C', 'C', 'B only is never a superkey here', 'A and C', 'A', 'A superkey must contain the primary key; A, B, C contains A and B and is therefore a superkey.', 'INTERMEDIATE', 2, 'MCQ', 1),
(943, 27, 'A relation has candidate keys K1 and K2. Which statement is true?', 'Both K1 and K2 are superkeys', 'Neither K1 nor K2 is a superkey', 'Only the chosen primary key is a superkey', 'K1 and K2 cannot coexist', 'A', 'Every candidate key is a minimal superkey, so both K1 and K2 are superkeys.', 'INTERMEDIATE', 2, 'MCQ', 1),
(944, 27, 'Which action may legally be performed on the relation that holds the referenced primary key when foreign key references exist?', 'Updating the referenced key with ON UPDATE CASCADE', 'Deleting the referenced row while child rows remain', 'Making the referenced key NULL', 'Duplicating the referenced key value', 'A', 'ON UPDATE CASCADE propagates key changes to dependent rows, preserving referential integrity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(945, 27, 'A primary key was chosen from among several candidate keys. The other candidate keys are known as:', 'Alternate keys', 'Foreign keys', 'Surrogate keys', 'Composite keys', 'A', 'Candidate keys not selected as the primary key are alternate keys.', 'INTERMEDIATE', 2, 'MCQ', 1),
(946, 27, 'A relation STUDENT(student_id, course_id, grade) with (student_id, course_id) as the primary key has a primary key that is:', 'Composite', 'Simple', 'Surrogate', 'Foreign', 'A', 'A composite key uses two or more attributes; here student_id and course_id together form it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(947, 27, 'What does ON DELETE CASCADE on a foreign key accomplish?', 'Deleting a parent row automatically deletes referencing child rows', 'Preventing deletion of any parent row', 'Setting child keys to NULL on parent deletion', 'Backing up the parent row before deletion', 'A', 'CASCADE propagates the parent deletion to child rows that reference the deleted key.', 'INTERMEDIATE', 2, 'MCQ', 1),
(948, 27, 'Referential integrity is violated when:', 'A foreign key value has no matching primary key value in the referenced table', 'A foreign key value appears twice', 'A primary key value is updated', 'A relation has more than one foreign key', 'A', 'A dangling foreign key with no matching referenced key breaks referential integrity.', 'INTERMEDIATE', 2, 'MCQ', 1),
(949, 27, 'Which of these is a legal NOT NULL enforcement under entity integrity?', 'A primary key attribute must never contain NULL', 'A foreign key may contain NULL', 'A primary key may be NULL if unique', 'Only one column of a primary key may be NULL', 'A', 'Entity integrity forbids NULL in any attribute that is part of the primary key.', 'INTERMEDIATE', 2, 'MCQ', 1),
(950, 27, 'The term ''relation schema'' describes:', 'The structure of a relation including its attribute names and domains', 'The current rows stored in the relation', 'The physical disk layout of the table', 'The query plan used to scan the table', 'A', 'A relation schema names the relation, its attributes and their domains; it is the intension, not the extension.', 'INTERMEDIATE', 2, 'MCQ', 1),
(951, 27, 'Relation R has attributes A, B, C where AB is the primary key. Which functional dependency must hold?', 'A and B together determine C, but neither alone determines C necessarily', 'A alone determines C', 'B alone determines C', 'C determines A', 'A', 'With AB as the key, every other attribute is functionally determined by the pair AB.', 'ADVANCED', 3, 'MCQ', 1),
(952, 27, 'You design a table with a composite primary key (order_id, item_no). A supplier key that depends only on item_no would cause:', 'A partial dependency, violating 2NF', 'A transitive dependency, violating 3NF', 'A multivalued dependency', 'No normalization problem', 'A', 'A non-key attribute depending on part of the composite key is a partial dependency, the 2NF violation.', 'ADVANCED', 3, 'MCQ', 1),
(953, 27, 'To convert a recursive many-to-many relationship into tables, you must:', 'Create a relationship table with two foreign keys pointing to the same relation', 'Create two identical copies of the relation', 'Drop the relationship entirely', 'Use a single self-referencing column', 'A', 'A junction table holding two foreign keys both referencing the same table models the recursive association.', 'ADVANCED', 3, 'MCQ', 1),
(954, 27, 'In a table Orders(customer_id, region), the foreign key customer_id references Customers. Adding a new order for a non-existent customer should be prevented by:', 'Referential integrity enforcement', 'Entity integrity enforcement', 'Domain enforcement', 'Functional dependency enforcement', 'A', 'Referential integrity rejects the insert because the customer_id has no matching Customers row.', 'ADVANCED', 3, 'MCQ', 1),
(955, 27, 'Surrogate keys are often preferred over natural keys because:', 'They avoid key changes when natural business values are edited', 'They always improve query speed', 'They store less data than every natural key', 'They remove the need for foreign keys', 'A', 'Surrogate keys are stable and independent of changing business data, so references are not broken on edits.', 'ADVANCED', 3, 'MCQ', 1),
(956, 27, 'A weak entity needs its owner''s primary key to be fully identified. This principle appears in relational modeling as:', 'Propagating the owner''s key into the weak entity''s primary key as a foreign key', 'Using a global surrogate key only', 'Making the weak entity a view', 'Storing the owner as an attribute of a different table', 'A', 'The weak entity''s key includes the owner''s key, making the foreign key part of its primary key.', 'ADVANCED', 3, 'MCQ', 1),
(957, 27, 'Given R(A, B, C) with FD A -> C and primary key AB, which normalization issue exists?', 'Partial dependency A -> C, so R is not in 2NF', 'Transitive dependency, so R violates 3NF', 'R is already in BCNF', 'R violates 1NF', 'A', 'C depends on A, only part of the key AB, which is a partial dependency violating 2NF.', 'ADVANCED', 3, 'MCQ', 1),
(958, 27, 'Which technique preserves referential integrity when the referenced key is renamed?', 'ON UPDATE CASCADE propagates the new value to all foreign keys', 'ON DELETE SET NULL only', 'Restricting all updates to the referenced table', 'Dropping all foreign key constraints', 'A', 'ON UPDATE CASCADE automatically updates referencing rows when the parent key changes.', 'ADVANCED', 3, 'MCQ', 1),
(959, 27, 'A relation must store ''employee depends on (spouse or children)'' with potentially many values per employee. The cleanest relational design is:', 'A separate Dependents relation keyed by employee_id plus a dependant attribute', 'A repeated column family inside the Employee row', 'Storing dependants in a single delimited text column', 'A multivalued attribute kept as-is', 'A', 'Separating dependants into their own relation keeps values atomic and satisfies first normal form.', 'ADVANCED', 3, 'MCQ', 1),
(960, 27, 'Which combination correctly describes key hierarchy in the relational model?', 'Every candidate key is a superkey, and the primary key is one candidate key', 'Every superkey is a candidate key', 'A primary key can never be a superkey', 'Candidate keys are always foreign keys', 'A', 'Candidate keys are minimal superkeys, and the chosen primary key is one of the candidate keys.', 'ADVANCED', 3, 'MCQ', 1),
(961, 28, 'Normalization is the process of:', 'Organizing data to minimize redundancy and avoid update anomalies', 'Encrypting all sensitive table columns', 'Increasing the number of tables in a schema', 'Denormalizing data for faster reads', 'A', 'Normalization structures relations to reduce redundancy and eliminate insertion, update and deletion anomalies.', 'BEGINNER', 1, 'MCQ', 1),
(962, 28, 'Which normal form requires that every attribute value be atomic?', 'First normal form', 'Second normal form', 'Third normal form', 'Boyce-Codd normal form', 'A', '1NF demands that each attribute holds a single atomic value with no repeating groups.', 'BEGINNER', 1, 'MCQ', 1),
(963, 28, 'A functional dependency A -> B means:', 'Each value of A determines exactly one value of B', 'B determines A', 'A and B must be equal', 'A must be unique in the relation', 'A', 'A -> B states that any two tuples with the same A value must have the same B value.', 'BEGINNER', 1, 'MCQ', 1),
(964, 28, 'Which of these is NOT a typical problem avoided by normalization?', 'Slower disk reads', 'Insertion anomalies', 'Update anomalies', 'Deletion anomalies', 'A', 'Normalization removes redundancy-driven anomalies; it does not directly speed up disk I/O.', 'BEGINNER', 1, 'MCQ', 1),
(965, 28, 'A table violates 1NF if it contains:', 'A column storing multiple values such as ''red, blue''', 'A primary key', 'Two foreign keys', 'An integer column', 'A', 'Storing multiple values in a single column creates a repeating group that violates 1NF atomicity.', 'BEGINNER', 1, 'MCQ', 1),
(966, 28, 'Second normal form (2NF) requires:', '1NF plus no partial dependency of non-key attributes on a composite key', 'No transitive dependencies', 'Every determinant to be a candidate key', 'All attributes to be foreign keys', 'A', '2NF removes partial dependencies where a non-key attribute depends on only part of a composite key.', 'BEGINNER', 1, 'MCQ', 1),
(967, 28, 'Third normal form (3NF) removes:', 'Transitive dependencies on non-key attributes', 'All foreign keys', 'All composite keys', 'All functional dependencies', 'A', '3NF eliminates transitive dependencies where a non-key attribute depends on another non-key attribute.', 'BEGINNER', 1, 'MCQ', 1),
(968, 28, 'Which normal form states that for every functional dependency X -> Y, X must be a superkey?', 'Boyce-Codd normal form', 'First normal form', 'Second normal form', 'Denormalized form', 'A', 'BCNF requires every determinant to be a superkey, a stricter condition than 3NF.', 'BEGINNER', 1, 'MCQ', 1),
(969, 28, 'An insertion anomaly is characterized by:', 'Being unable to add data because required fields are missing', 'Deleting too many rows accidentally', 'Updates taking a long time', 'Queries returning duplicate rows', 'A', 'Insertion anomalies occur when needed facts cannot be recorded without first adding unrelated data.', 'BEGINNER', 1, 'MCQ', 1),
(970, 28, 'The primary purpose of using functional dependencies in normalization is to:', 'Understand which attributes determine others so relations can be decomposed safely', 'Enforce access control on attributes', 'Encrypt attribute values', 'Index every attribute', 'A', 'Functional dependencies guide decomposition by showing how attributes depend on keys.', 'BEGINNER', 1, 'MCQ', 1),
(971, 28, 'Relation R(A, B, C, D) with key AB and FD B -> D. Which normal form does R violate?', 'Second normal form', 'First normal form', 'Third normal form', 'BCNF is satisfied', 'A', 'D depends on B, which is part of the composite key AB, so the partial dependency violates 2NF.', 'INTERMEDIATE', 2, 'MCQ', 1),
(972, 28, 'Relation R(A, B, C) with key A and FD B -> C. Which normal form does R violate?', 'Third normal form', 'Second normal form', 'First normal form', 'No violation occurs', 'A', 'C depends on B rather than on the key A, a transitive dependency that violates 3NF.', 'INTERMEDIATE', 2, 'MCQ', 1),
(973, 28, 'A relation is in BCNF. Which statement must be true?', 'Every determinant is a superkey', 'The relation has no candidate keys', 'All attributes are atomic', 'The relation has at most two columns', 'A', 'BCNF requires each functional dependency determinant to be a superkey.', 'INTERMEDIATE', 2, 'MCQ', 1),
(974, 28, 'To fix the relation R(A, B, C) with key AB and FD B -> C, the correct decomposition is:', 'R1(A, B) and R2(B, C)', 'R1(A, C) and R2(B, C)', 'R1(A, B, C) unchanged', 'R1(A, B) only', 'A', 'R1 holds the key AB and R2 captures the dependency B -> C, removing the partial dependency.', 'INTERMEDIATE', 2, 'MCQ', 1),
(975, 28, 'Which of these schemas is in 2NF but NOT in 3NF?', 'R(A, B, C) with key A and FD B -> C', 'R(A, B) with key AB', 'R(A, B, C) with key A and FDs A -> B, A -> C', 'R(A) with key A', 'A', 'With key A and transitive FD B -> C, the relation satisfies 2NF but fails 3NF.', 'INTERMEDIATE', 2, 'MCQ', 1),
(976, 28, 'A relation in 3NF can still violate BCNF when:', 'A candidate key''s proper subset determines another attribute', 'A non-key attribute depends on the full key', 'All attributes are part of candidate keys', 'The relation has no functional dependencies', 'A', '3NF tolerates dependencies whose left side is a subset of a key; BCNF does not, so such relations can fail BCNF.', 'INTERMEDIATE', 2, 'MCQ', 1),
(977, 28, 'Decomposing a relation into 3NF must always be:', 'Lossless-join and dependency preserving if the synthesis algorithm is used', 'Only lossless-join with dependencies possibly lost', 'Lossy unless BCNF is used', 'Impossible without dropping keys', 'A', 'The 3NF synthesis algorithm guarantees both lossless joins and dependency preservation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(978, 28, 'Which schema is already in BCNF?', 'R(A, B, C) with key A and FDs A -> B and A -> C', 'R(A, B, C) with key A and FD B -> C', 'R(A, B, C) with key AB and FD B -> C', 'R(A, B) with FD A -> B', 'A', 'Every dependency in the first schema has A (the key) as its determinant, so BCNF holds.', 'INTERMEDIATE', 2, 'MCQ', 1),
(979, 28, 'An update anomaly is best described as:', 'A change to one fact requiring many rows to be changed consistently', 'A query returning an error', 'A constraint rejecting a NULL value', 'An index becoming fragmented', 'A', 'Redundant data forces a single logical fact to be updated in many places, risking inconsistency.', 'INTERMEDIATE', 2, 'MCQ', 1),
(980, 28, 'Given FDs AB -> C and C -> D with key AB, the relation is in:', '2NF but not 3NF', '3NF but not BCNF', 'BCNF', 'Only 1NF', 'A', 'Both A -> C and B -> C are absent, so no partial dependency; C -> D is transitive, violating 3NF.', 'INTERMEDIATE', 2, 'MCQ', 1),
(981, 28, 'Relation R(A, B, C, D) has FDs AB -> C and C -> D and key AB. Which dependency causes the 3NF violation and how is R decomposed?', 'C -> D is transitive, so split into R1(A, B, C) and R2(C, D)', 'AB -> C is partial, so split into R1(A, B) and R2(B, C)', 'No decomposition is needed', 'Split into R1(A, D) and R2(B, C)', 'A', 'C -> D is transitive because C is not a key; separating (C, D) removes the dependency.', 'ADVANCED', 3, 'MCQ', 1),
(982, 28, 'Which relation satisfies BCNF despite having a non-trivial functional dependency?', 'R(A, B, C) with FDs A -> B and A -> C, key A', 'R(A, B, C) with FD B -> C, key A', 'R(A, B, C) with key AB and FD B -> C', 'R(A, B, C) with FD C -> A and key B', 'A', 'Every dependency has A as a superkey, so BCNF is satisfied by the first schema.', 'ADVANCED', 3, 'MCQ', 1),
(983, 28, 'A relation R(A, B, C) has FDs A -> B and B -> C and key A. Which normal form does it violate?', '3NF, because of the transitive dependency B -> C', '2NF, because of a partial dependency', 'BCNF only, and 3NF holds', 'It violates no normal form', 'A', 'C depends transitively on A through B, so 3NF is violated.', 'ADVANCED', 3, 'MCQ', 1),
(984, 28, 'Given FDs A -> B and B -> A on relation R(A, B), which statement is correct?', 'Both A and B are candidate keys and R is in BCNF', 'Only A is a key, so R is in 1NF', 'R cannot be in any normal form', 'R must be decomposed into two relations', 'A', 'A -> B makes A a key and B -> A makes B a key; each determinant is a key, so BCNF holds.', 'ADVANCED', 3, 'MCQ', 1),
(985, 28, 'A lossless-join decomposition requires that the common attributes of the two schemas:', 'Form a superkey of at least one of the schemas', 'Form a key of neither schema', 'Be empty', 'Be a foreign key in both', 'A', 'Lossless joins need the intersecting attribute set to be a superkey of one side to rejoin tuples correctly.', 'ADVANCED', 3, 'MCQ', 1),
(986, 28, 'Which statement distinguishes 3NF from BCNF accurately?', '3NF allows a dependency whose left side is a proper subset of a candidate key; BCNF does not', 'BCNF allows partial dependencies while 3NF removes them', '3NF requires every determinant to be a key', 'BCNF only applies to relations with one key', 'A', '3NF is more lenient, permitting key-subset determinants, while BCNF requires all determinants to be superkeys.', 'ADVANCED', 3, 'MCQ', 1),
(987, 28, 'Relation R(A, B, C) has key AB and FD B -> C. What is the correct BCNF decomposition?', 'R1(A, B) and R2(B, C)', 'R1(A, C) and R2(B, C)', 'R1(A, B) and R2(A, C)', 'R1(A, B, C) cannot be decomposed', 'A', 'R1 keeps the key AB, and R2 captures the dependency B -> C so B is a key there.', 'ADVANCED', 3, 'MCQ', 1),
(988, 28, 'In a university schema, Student has FDs student_id -> name and dept_code -> dept_name. Where is the transitive dependency?', 'dept_name depends on dept_code, not on student_id directly', 'name depends on dept_code', 'student_id depends on dept_name', 'There is no transitive dependency', 'A', 'dept_name depends on dept_code, which is not a key, so student_id -> dept_name is transitive.', 'ADVANCED', 3, 'MCQ', 1),
(989, 28, 'A lossy decomposition occurs when rejoining the decomposed relations:', 'Produces tuples that were not present in the original relation', 'Produces exactly the original tuples', 'Fails because of NULL keys', 'Needs a sort that is too slow', 'A', 'If the join yields extra spurious tuples, the decomposition is lossy rather than lossless.', 'ADVANCED', 3, 'MCQ', 1),
(990, 28, 'Which FDs guarantee a relation R(A, B, C) is in BCNF with key A?', 'A -> B and A -> C only', 'B -> C and C -> B', 'A -> C and C -> A', 'AB -> C', 'A', 'With key A, only dependencies whose determinant is A keep the relation in BCNF.', 'ADVANCED', 3, 'MCQ', 1),
(991, 29, 'The ACID property that ensures a transaction is an indivisible all-or-nothing unit is:', 'Atomicity', 'Consistency', 'Isolation', 'Durability', 'A', 'Atomicity guarantees that either all transaction operations commit or none take effect.', 'BEGINNER', 1, 'MCQ', 1),
(992, 29, 'Which ACID property ensures that committed data survives system crashes?', 'Durability', 'Atomicity', 'Isolation', 'Consistency', 'A', 'Durability guarantees committed changes persist even after a crash or power loss.', 'BEGINNER', 1, 'MCQ', 1),
(993, 29, 'The isolation property of ACID means that:', 'Concurrent transactions should not interfere with each other''s intermediate states', 'Transactions must run one at a time', 'Transactions can read uncommitted data freely', 'All transactions must update the same data', 'A', 'Isolation keeps each transaction''s intermediate state hidden from other concurrent transactions.', 'BEGINNER', 1, 'MCQ', 1),
(994, 29, 'Which ACID property ensures a transaction leaves the database in a valid state?', 'Consistency', 'Atomicity', 'Isolation', 'Durability', 'A', 'Consistency guarantees that a transaction moves the database from one valid state to another.', 'BEGINNER', 1, 'MCQ', 1),
(995, 29, 'The process of temporarily halting a transaction to wait for another transaction to release a resource is handled by:', 'Locking', 'Normalization', 'Indexing', 'Compaction', 'A', 'Locking mechanisms let a transaction wait for a resource held by another transaction.', 'BEGINNER', 1, 'MCQ', 1),
(996, 29, 'A transaction that completes all its steps and writes results to the database is said to:', 'Commit', 'Abort', 'Rollback', 'Serialize', 'A', 'Committing finalizes the transaction so its changes become durable.', 'BEGINNER', 1, 'MCQ', 1),
(997, 29, 'Which isolation level allows a transaction to read data written by an uncommitted transaction?', 'READ UNCOMMITTED', 'READ COMMITTED', 'REPEATABLE READ', 'SERIALIZABLE', 'A', 'READ UNCOMMITTED permits dirty reads because it does not check for other transactions'' uncommitted writes.', 'BEGINNER', 1, 'MCQ', 1),
(998, 29, 'A dirty read occurs when a transaction reads:', 'Data written by a transaction that later aborts', 'Only committed data', 'Data that is NULL', 'Data from an index scan', 'A', 'Reading a value written by a still-uncommitted transaction that later rolls back is a dirty read.', 'BEGINNER', 1, 'MCQ', 1),
(999, 29, 'The phenomenon where a transaction reads a value, and then the value is changed by another committed transaction before a re-read, is called a:', 'Non-repeatable read', 'Dirty read', 'Phantom read', 'Lost update', 'A', 'A non-repeatable read sees different values in two reads because another transaction committed in between.', 'BEGINNER', 1, 'MCQ', 1),
(1000, 29, 'Serializability means that the outcome of concurrent transactions is:', 'Equivalent to some serial execution of those transactions', 'Always ordered by timestamps', 'Independent of the schedule', 'Determined by the database size', 'A', 'A serializable schedule produces the same result as running the transactions one after another.', 'BEGINNER', 1, 'MCQ', 1),
(1001, 29, 'Two transactions both read balance=100, each adds 50 and writes 200 instead of 150. This anomaly is:', 'Lost update', 'Dirty read', 'Phantom read', 'Non-repeatable read', 'A', 'Each transaction overwrites the other''s write, so one committed update is lost.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1002, 29, 'Which isolation level prevents dirty reads but still allows non-repeatable reads?', 'READ COMMITTED', 'READ UNCOMMITTED', 'SERIALIZABLE', 'REPEATABLE READ', 'A', 'READ COMMITTED avoids dirty reads yet permits another committed transaction to change a row between two reads.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1003, 29, 'REPEATABLE READ prevents which anomaly but not phantom reads?', 'Non-repeatable reads', 'Dirty reads only', 'Lost updates', 'Dirty writes', 'A', 'REPEATABLE READ keeps re-reads stable but does not prevent new rows from appearing in a result set.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1004, 29, 'A phantom read occurs when a transaction:', 'Runs the same query twice and sees new rows inserted by another committed transaction', 'Reads a row twice and sees a changed value', 'Reads an aborted transaction''s data', 'Overwrites another transaction''s committed write', 'A', 'Phantom reads involve new tuples appearing between two executions of the same query.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1005, 29, 'Which statement about two-phase locking (2PL) is true?', 'It has a growing phase for acquiring locks and a shrinking phase for releasing them', 'It requires all locks to be released before any is acquired', 'It only uses shared locks', 'It prevents all deadlocks automatically', 'A', '2PL divides a transaction into a growing phase of lock acquisition and a shrinking phase of release.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1006, 29, 'A deadlock between two transactions is resolved by the DBMS by:', 'Aborting and rolling back one of the transactions', 'Ignoring the locked resources', 'Increasing the transaction timeout only', 'Dropping the table that holds the lock', 'A', 'The DBMS picks a victim transaction, aborts it and rolls back to break the deadlock cycle.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1007, 29, 'Which isolation level provides the strongest guarantee and eliminates dirty, non-repeatable and phantom reads?', 'SERIALIZABLE', 'READ COMMITTED', 'REPEATABLE READ', 'READ UNCOMMITTED', 'A', 'SERIALIZABLE behaves like a serial execution and prevents all three read anomalies.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1008, 29, 'Under strict two-phase locking, locks are released:', 'Only after the transaction commits or aborts', 'Immediately after each operation', 'Before any new lock is acquired', 'Only when the buffer pool fills', 'A', 'Strict 2PL holds all locks until commit or abort, preventing cascading aborts.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1009, 29, 'If transaction T1 updates row R and T2 waits for R, then T1 waits for a resource held by T2, the system is in:', 'Deadlock', 'Normal execution', 'Commit', 'Recovery', 'A', 'Each transaction waits for a resource the other holds, forming a deadlock cycle.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1010, 29, 'Under the SERIALIZABLE isolation level, the DBMS typically uses which locking scheme?', 'Strict two-phase locking', 'No locking at all', 'Optimistic versioning with no checks', 'Shared locks only', 'A', 'Strict two-phase locking with shared/exclusive locks yields serializable schedules.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1011, 29, 'In a banking system, T1 reads account A and T2 reads the same A, then both add 100 and write back. Which isolation level alone fully prevents the lost update?', 'SERIALIZABLE with proper lock durations', 'READ UNCOMMITTED', 'READ COMMITTED without locking writes', 'REPEATABLE READ without update locks', 'A', 'SERIALIZABLE serializes the read-modify-write cycle, preventing both lost updates.', 'ADVANCED', 3, 'MCQ', 1),
(1012, 29, 'A schedule S is conflict-serializable if:', 'Its conflicting operations can be reordered by swapping non-conflicting ones into a serial schedule', 'It uses only shared locks', 'All transactions commit at the same time', 'It has no deadlocks', 'A', 'Conflict serializability reorders non-conflicting operations to reach an equivalent serial schedule.', 'ADVANCED', 3, 'MCQ', 1),
(1013, 29, 'With snapshot isolation, a transaction''s reads come from:', 'A versioned snapshot taken when the transaction began', 'The live committed rows at read time', 'The uncommitted buffer pool', 'The redo log only', 'A', 'Snapshot isolation reads a consistent historical version of the data from transaction start.', 'ADVANCED', 3, 'MCQ', 1),
(1014, 29, 'Under READ COMMITTED, a non-repeatable read can still happen because:', 'Another transaction may commit a change between the two reads', 'The isolation level blocks all writes', 'The transaction locks every row it touches', 'The transaction reads only its own writes', 'A', 'READ COMMITTED does not hold read locks, so a concurrent commit can change a value between reads.', 'ADVANCED', 3, 'MCQ', 1),
(1015, 29, 'A system detects a cycle in its wait-for graph. The appropriate immediate response is:', 'Abort a victim transaction and roll back its changes', 'Upgrade all shared locks to exclusive locks', 'Increase the isolation level to SERIALIZABLE', 'Force a full database restart', 'A', 'A cycle in the wait-for graph signals deadlock; choosing and aborting a victim resolves it.', 'ADVANCED', 3, 'MCQ', 1),
(1016, 29, 'Which scenario is the classic phantom-read failure under REPEATABLE READ?', 'The same SELECT range query returns more rows after another transaction inserts a matching row', 'A committed row value changes between two reads', 'A transaction reads an uncommitted aborting value', 'Two transactions overwrite the same balance', 'A', 'REPEATABLE READ locks existing rows but not gaps, so new rows can appear as phantoms.', 'ADVANCED', 3, 'MCQ', 1),
(1017, 29, 'In the write-ahead logging protocol, the log record must be written:', 'Before the corresponding data page is flushed to disk', 'After the data page is written', 'Only at checkpoint time', 'Only during commit', 'A', 'Write-ahead logging forces the log to disk before data pages so recovery can redo or undo changes.', 'ADVANCED', 3, 'MCQ', 1),
(1018, 29, 'Cascading aborts are avoided under which locking discipline?', 'Strict two-phase locking', 'Basic two-phase locking', 'Optimistic concurrency without validation', 'READ UNCOMMITTED', 'A', 'Strict 2PL releases locks only at commit, so no transaction reads uncommitted data and cascades aborts.', 'ADVANCED', 3, 'MCQ', 1),
(1019, 29, 'Given a wait-for graph with edges T1 -> T2 and T2 -> T1, the correct conclusion is:', 'A deadlock exists and one transaction must be aborted', 'Both transactions will commit normally', 'The schedule is serial', 'The isolation level must be lowered', 'A', 'A cycle in the wait-for graph means each waits on the other, so the DBMS must break the cycle.', 'ADVANCED', 3, 'MCQ', 1),
(1020, 29, 'Which of these pairs can occur in READ COMMITTED but never in SERIALIZABLE?', 'Non-repeatable read followed by a phantom read', 'A dirty read of uncommitted data', 'Reading a committed row', 'A transaction that only performs SELECTs', 'A', 'READ COMMITTED permits non-repeatable and phantom reads, while SERIALIZABLE prevents both.', 'ADVANCED', 3, 'MCQ', 1),
(1021, 30, 'Which data structure is commonly used by databases to speed up point lookups by key value?', 'A B+ tree index', 'A linked list', 'A hash table is never used', 'A binary tree is the only option', 'A', 'B+ trees are the standard balanced index structure used for fast equality and range lookups.', 'BEGINNER', 1, 'MCQ', 1),
(1022, 30, 'A clustered index determines:', 'The physical order of rows on disk', 'The logical order of rows in queries only', 'The order of the redo log', 'The number of secondary indexes', 'A', 'A clustered index stores rows physically in key order, so there can be only one per table.', 'BEGINNER', 1, 'MCQ', 1),
(1023, 30, 'An index that does not affect the physical row order and references the clustered key is called:', 'A secondary index', 'A clustered index', 'A primary index', 'A heap index', 'A', 'Secondary (non-clustered) indexes store key-to-row pointers without reordering physical rows.', 'BEGINNER', 1, 'MCQ', 1),
(1024, 30, 'The purpose of a query plan (execution plan) is to:', 'Describe the steps the DBMS uses to execute a query', 'Store the query text for reuse', 'Encrypt the query result', 'Lock all accessed tables', 'A', 'An execution plan details access methods, join orders and operators the optimizer chose for a query.', 'BEGINNER', 1, 'MCQ', 1),
(1025, 30, 'Which part of the DBMS chooses how to execute a SQL query?', 'The query optimizer', 'The lock manager', 'The recovery manager', 'The buffer manager', 'A', 'The query optimizer selects access paths and join strategies that minimize estimated cost.', 'BEGINNER', 1, 'MCQ', 1),
(1026, 30, 'A full table scan is typically chosen when:', 'Most rows in the table must be read or the table is very small', 'The query filters on a highly selective indexed column', 'The table has a clustered index', 'The query uses an exact primary key lookup', 'A', 'When selectivity is low or the table is small, scanning all pages is cheaper than using an index.', 'BEGINNER', 1, 'MCQ', 1),
(1027, 30, 'Which index type is best suited for range queries such as age BETWEEN 20 AND 30?', 'A B+ tree index', 'A bitmap on a wide value', 'A hash index', 'No index helps range queries', 'A', 'B+ tree indexes keep keys in sorted order, enabling efficient ordered range scans.', 'BEGINNER', 1, 'MCQ', 1),
(1028, 30, 'A heap file organization stores rows:', 'In no particular order, appended as they arrive', 'In sorted key order', 'Grouped by index value', 'Encrypted on disk', 'A', 'Heap files append new tuples without ordering them by any key.', 'BEGINNER', 1, 'MCQ', 1),
(1029, 30, 'The cost of an index lookup usually depends most heavily on:', 'The height of the index tree and the number of matching rows', 'The size of the SELECT list only', 'The number of columns in the table', 'The disk rotation speed only', 'A', 'Tree height determines traversal cost and the matched row count determines how many pages are fetched.', 'BEGINNER', 1, 'MCQ', 1),
(1030, 30, 'What does an index on a table column NOT speed up?', 'Writing the same value to many rows that changes the indexed key', 'Equality lookups on the indexed column', 'Range scans on the indexed column', 'Sorted retrieval on the indexed column', 'A', 'Indexed key updates force index maintenance overhead, which can slow down writes.', 'BEGINNER', 1, 'MCQ', 1),
(1031, 30, 'A query filters WHERE dept_id = 7 and dept_id is indexed but very few rows match. The optimizer most likely chooses:', 'An index scan returning only the matching rows', 'A full table scan', 'A merge join with no filter', 'A hash index on every column', 'A', 'High selectivity makes the index seek cheaper than reading every page of the table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1032, 30, 'Why does a clustered index on a composite key (a, b) also help queries filtering only on a?', 'The key order groups rows with the same a together, enabling a prefix range scan', 'Because every secondary index is dropped', 'Because a is always unique', 'Because the table becomes a heap', 'A', 'The leading column of a clustered index orders data, so prefix-only predicates still use the index.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1033, 30, 'The optimizer compares two join plans and selects:', 'The one with the lower estimated total cost in I/O and CPU', 'The plan with more hash operations', 'The first plan generated', 'The plan with the fewest output columns', 'A', 'Cost-based optimization ranks plans by estimated resource usage and picks the cheapest.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1034, 30, 'A query scans all 100 pages of a table for every join probe. This is an example of:', 'A nested-loop join with repeated full scans', 'A merge join on sorted inputs', 'A hash join', 'An index-only join', 'A', 'Nested-loop join probes the inner relation for each outer row, which can require repeated page scans.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1035, 30, 'Hash joins are most efficient when:', 'Joining large, unsorted inputs on equality conditions', 'Joining inputs that are already sorted', 'Joining on non-equality conditions', 'Joining single-row inputs', 'A', 'Hash joins build and probe hash tables, excelling at large equi-joins without needing sorted data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1036, 30, 'An index-only scan (covering index) is possible when:', 'All columns needed by the query appear in the index', 'The index is clustered on the primary key', 'The table has no secondary indexes', 'The query uses SELECT *', 'A', 'A covering index holds every referenced column, so the query never reads the table pages.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1037, 30, 'Which action could turn an otherwise selective index use into a full table scan?', 'Wrapping the indexed column in a function such as YEAR(order_date)', 'Using an equality predicate on the column', 'Using the leading index column in WHERE', 'Keeping statistics up to date', 'A', 'Applying a function to the column can block the optimizer from using the index on that column.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1038, 30, 'Statistics about data distribution are used by the optimizer to:', 'Estimate selectivity and the number of matching rows', 'Compress the index pages', 'Decide the isolation level', 'Choose the redo log size', 'A', 'Histograms and cardinality estimates let the optimizer predict how many rows a filter returns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1039, 30, 'To speed up a query that filters on city and sorts by last_name, a useful index would be:', 'A composite B+ tree index on (city, last_name)', 'A separate index only on last_name', 'A hash index on city', 'No index at all', 'A', 'A composite index (city, last_name) satisfies the filter and provides sorted last_name order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1040, 30, 'Which of these is the correct B+ tree leaf behavior compared to a standard B-tree?', 'All leaves are linked together and contain actual data keys', 'Leaves point only to parent nodes', 'Data keys appear only in internal nodes', 'Leaves are never visited during lookups', 'A', 'B+ trees keep all actual keys in linked leaves, which simplifies ordered traversal.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1041, 30, 'A B+ tree with order 4 (max 4 pointers per node) stores 1,000,000 keys. Which factor most limits lookup cost?', 'The tree height, which grows as the log of the leaf count', 'The number of leaf keys, which is irrelevant to height', 'The total number of tables', 'The disk page size being unlimited', 'A', 'High fanout keeps B+ tree height small, so a lookup touches only a few levels.', 'ADVANCED', 3, 'MCQ', 1),
(1042, 30, 'Why are hash indexes unsuitable for the query WHERE salary >= 50000 ORDER BY salary?', 'Hash indexes preserve no ordering, so they cannot support range or sorted output', 'Hash indexes cannot store numbers', 'Hash indexes only support joins', 'Hash indexes are always clustered', 'A', 'Hash structures give O(1) equality lookups but no ordered access, so ranges and sorts need a B+ tree.', 'ADVANCED', 3, 'MCQ', 1),
(1043, 30, 'An optimizer sees WHERE a = 5 AND b = 7 on a two-column B+ tree index (a, b). It can:', 'Use the index to find exact matches without visiting the table', 'Only use the index for column b', 'Never use the composite index', 'Fall back to a merge join', 'A', 'Both equality predicates use the index''s full key prefix, enabling precise index seeks.', 'ADVANCED', 3, 'MCQ', 1),
(1044, 30, 'A query joins Orders (large) and Customers (small) on customer_id with an index on Orders.customer_id. The best join strategy is usually:', 'Index nested-loop join reading Orders through the index for each Customer', 'Hash join that builds on Orders', 'Sort-merge join with no indexes', 'Cartesian product followed by a filter', 'A', 'Probing the indexed Orders table for each small Customer row avoids scanning the large table.', 'ADVANCED', 3, 'MCQ', 1),
(1045, 30, 'Under which condition would the optimizer still choose a full scan over an existing index?', 'The indexed column has low cardinality such that most rows match the filter', 'The index has high selectivity', 'The predicate uses equality on the leading column', 'The table has a clustered primary key', 'A', 'If the filter matches nearly all rows, reading the whole table sequentially is cheaper than random index I/O.', 'ADVANCED', 3, 'MCQ', 1),
(1046, 30, 'A covering index on (product_id, price) helps the query SELECT price FROM products WHERE product_id = 5 because:', 'Both columns are in the index, so table pages are never accessed', 'The index is clustered on price', 'product_id is the table''s primary key only', 'The optimizer disables table reads entirely', 'A', 'With all required columns present, the index alone answers the query, avoiding heap lookups.', 'ADVANCED', 3, 'MCQ', 1),
(1047, 30, 'Two B+ tree indexes exist on (a, b) and on (b). A query filters WHERE b = 5 AND a = 10. Which is the best index choice?', '(a, b), because equality on the leading column a allows a precise seek and b is still checked', '(b) alone, because b is the only filter', 'Either index gives identical performance', 'No index can be used', 'A', 'The (a, b) index lets the optimizer seek on a = 10 and validate b = 5 within the matching range.', 'ADVANCED', 3, 'MCQ', 1),
(1048, 30, 'Bitmap indexes are most effective on columns that:', 'Have low cardinality such as gender or status', 'Have a distinct value per row', 'Store large text documents', 'Are always NULL', 'A', 'Bitmap indexes compress repetitive values well and support fast bitwise AND/OR for low-cardinality columns.', 'ADVANCED', 3, 'MCQ', 1),
(1049, 30, 'After heavy updates, the optimizer''s cost estimate for using an index may become wrong because:', 'Outdated statistics misreport the number of distinct values and row counts', 'The index files are always stored in memory', 'Updates never change index structure', 'The redo log prevents index reads', 'A', 'Stale statistics lead to poor selectivity estimates and therefore suboptimal plans.', 'ADVANCED', 3, 'MCQ', 1),
(1050, 30, 'To diagnose a query that ignores a helpful index, the best first step is:', 'Examine the execution plan to see the chosen access path and estimated rows', 'Rebuild the whole operating system', 'Disable all other indexes', 'Increase the buffer pool to infinite size', 'A', 'Reading the plan reveals why the index was not chosen, such as a function on the column or stale stats.', 'ADVANCED', 3, 'MCQ', 1),
(1051, 31, 'Which SQL command is used to create a new database table?', 'CREATE TABLE', 'INSERT INTO', 'ALTER TABLE', 'DROP TABLE', 'A', 'CREATE TABLE is the DDL statement that defines a new table and its columns in the database.', 'BEGINNER', 1, 'MCQ', 1),
(1052, 31, 'Which SQL command removes all rows from a table but keeps the table structure itself?', 'DROP TABLE', 'TRUNCATE', 'DELETE', 'REMOVE', 'B', 'TRUNCATE deletes every row while preserving the table definition, which is exactly what keeps the structure intact.', 'BEGINNER', 1, 'MCQ', 1),
(1053, 31, 'Which clause is used to filter rows in a SELECT query?', 'GROUP BY', 'ORDER BY', 'WHERE', 'HAVING', 'C', 'WHERE filters individual rows before any grouping or aggregation takes place.', 'BEGINNER', 1, 'MCQ', 1),
(1054, 31, 'What does the * symbol mean in a query such as SELECT * FROM employees?', 'The average value', 'A single column', 'The primary key', 'All columns', 'D', 'The asterisk is shorthand that selects all columns of the table in the order they were defined.', 'BEGINNER', 1, 'MCQ', 1),
(1055, 31, 'Which data type would you use to store a whole number such as an employee id?', 'INT', 'VARCHAR', 'DATE', 'TEXT', 'A', 'INT stores integer values, which is exactly what an employee id represents.', 'BEGINNER', 1, 'MCQ', 1),
(1056, 31, 'Which SQL command adds a new column to an existing table?', 'ADD TABLE', 'ALTER TABLE', 'MODIFY TABLE', 'UPDATE TABLE', 'B', 'ALTER TABLE is used to change the structure of a table, including adding new columns.', 'BEGINNER', 1, 'MCQ', 1),
(1057, 31, 'Which clause sorts the results of a SELECT query?', 'SORT BY', 'GROUP BY', 'ORDER BY', 'ARRANGE BY', 'C', 'ORDER BY sorts the result rows by one or more columns in ascending or descending order.', 'BEGINNER', 1, 'MCQ', 1),
(1058, 31, 'Which SQL command permanently removes a table along with its structure and all data?', 'DELETE', 'TRUNCATE', 'REMOVE', 'DROP TABLE', 'D', 'DROP TABLE deletes the entire table definition and all of its data, so it removes the structure permanently.', 'BEGINNER', 1, 'MCQ', 1),
(1059, 31, 'Which clause limits the number of rows returned by a query?', 'LIMIT', 'BOUND', 'STOP', 'RANGE', 'A', 'LIMIT (called TOP in some databases) restricts how many result rows are returned.', 'BEGINNER', 1, 'MCQ', 1),
(1060, 31, 'Which of the following is a Data Definition Language (DDL) command?', 'SELECT', 'CREATE', 'INSERT', 'UPDATE', 'B', 'CREATE defines or modifies database structure, so it is classified as a DDL command.', 'BEGINNER', 1, 'MCQ', 1),
(1061, 31, 'Which statement creates a table named departments with a primary key on the id column?', 'CREATE departments (id INT PRIMARY KEY, name VARCHAR(100));', 'MAKE TABLE departments (id INT, name VARCHAR(100));', 'CREATE TABLE departments (id INT PRIMARY KEY, name VARCHAR(100));', 'CREATE TABLE departments (id INT, name VARCHAR(100), PRIMARY FOREIGN KEY id);', 'C', 'CREATE TABLE followed by column definitions marks id with PRIMARY KEY so it uniquely identifies each row.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1062, 31, 'Which query returns only the distinct department ids from the employees table?', 'SELECT DISTINCT dept_id FROM employees;', 'SELECT dept_id DIFFERENT FROM employees;', 'SELECT DISTINCT dept_id FROM employees WHERE DISTINCT;', 'SELECT UNIQUE dept_id FROM employees;', 'A', 'DISTINCT removes duplicate values so each department id appears only once in the result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1063, 31, 'You need to add a column named email to the employees table. Which statement is correct?', 'ADD COLUMN email TO employees;', 'ALTER TABLE employees ADD COLUMN email VARCHAR(100);', 'UPDATE employees SET email = email;', 'CREATE COLUMN email IN employees;', 'B', 'ALTER TABLE employees ADD COLUMN adds the new column to the existing table definition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1064, 31, 'Which query selects all employees earning more than 50000 sorted by name in descending order?', 'SELECT * FROM employees WHERE salary > 50000 SORT BY name DESC;', 'SELECT * FROM employees WHERE salary > 50000 GROUP BY name;', 'SELECT * FROM employees WHERE salary < 50000 ORDER BY name DESC;', 'SELECT * FROM employees WHERE salary > 50000 ORDER BY name DESC;', 'D', 'WHERE filters on the salary, and ORDER BY name DESC sorts alphabetically in reverse order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1065, 31, 'What is the main purpose of a primary key constraint on a table?', 'To allow duplicate rows', 'To speed up SELECT * queries', 'To enforce that all columns are not null', 'To uniquely identify each row in the table', 'D', 'A primary key guarantees each row has a unique, non-null identifier, which is its main purpose.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1066, 31, 'Which query returns employees whose names start with the letter ''A''?', 'SELECT * FROM employees WHERE name = ''A'';', 'SELECT * FROM employees WHERE name LIKE ''A'';', 'SELECT * FROM employees WHERE name LIKE ''A%'';', 'SELECT * FROM employees WHERE name LIKE ''%A'';', 'C', 'The LIKE pattern ''A%'' matches any name that begins with ''A'' followed by any number of characters.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1067, 31, 'In a CREATE TABLE statement, what does the UNIQUE constraint guarantee?', 'The column is automatically sorted', 'The column must be numeric', 'All values in the column are distinct', 'The column cannot be indexed', 'C', 'UNIQUE ensures no two rows can have the same value in that column, though NULLs are still typically allowed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1068, 31, 'Which command removes the primary key constraint named pk_emp from the employees table?', 'ALTER TABLE employees DROP PRIMARY KEY pk_emp;', 'ALTER TABLE employees DROP CONSTRAINT pk_emp;', 'DROP CONSTRAINT pk_emp FROM employees;', 'DELETE CONSTRAINT pk_emp FROM employees;', 'B', 'ALTER TABLE ... DROP CONSTRAINT removes the named constraint from the table structure.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1069, 31, 'Which data type is most appropriate for storing a salary such as 52500.75?', 'INT', 'VARCHAR', 'BOOLEAN', 'DECIMAL(10,2)', 'D', 'DECIMAL(10,2) stores exact numbers with two decimal places, which is ideal for money values without rounding errors.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1070, 31, 'Which query correctly finds employees whose name column is NULL?', 'SELECT * FROM employees WHERE name = NULL;', 'SELECT * FROM employees WHERE name == NULL;', 'SELECT * FROM employees WHERE name IS NULL;', 'SELECT * FROM employees WHERE name IS EMPTY;', 'C', 'NULL cannot be compared with =, so the IS NULL operator is required to test for NULL values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1071, 31, 'Why can a TRUNCATE operation usually not be rolled back in many databases while a DELETE can?', 'TRUNCATE removes only rows matching a WHERE clause', 'TRUNCATE deallocates data pages and is not row-logged, so it usually cannot be rolled back while DELETE can', 'TRUNCATE cannot be used on a table with an index', 'DELETE never writes to the transaction log', 'B', 'TRUNCATE is a DDL-like operation that deallocates data pages and is not row-logged, whereas DELETE logs each row so it can be rolled back.', 'ADVANCED', 3, 'MCQ', 1),
(1072, 31, 'Which SQL statement correctly defines a composite primary key on (id, course_id) in a table named enrollments?', 'CREATE TABLE enrollments (PRIMARY KEY id AND course_id);', 'CREATE TABLE enrollments (id INT PRIMARY KEY, course_id INT PRIMARY KEY);', 'CREATE TABLE enrollments (id INT, course_id INT, grade CHAR, PRIMARY KEY (id, course_id));', 'CREATE TABLE enrollments (id, course_id) PRIMARY KEY;', 'C', 'A composite key is declared with PRIMARY KEY listing both columns, which uniquely identifies a row only by the pair together.', 'ADVANCED', 3, 'MCQ', 1),
(1073, 31, 'Which statement is TRUE about a NOT NULL constraint?', 'NOT NULL allows NULLs but blocks duplicates', 'NOT NULL creates a unique index automatically', 'NOT NULL requires a default value', 'NOT NULL only prevents NULL values but still allows duplicate entries', 'D', 'NOT NULL only forbids NULL entries; it does nothing about duplicate values, which is why NOT NULL and UNIQUE are combined for identifier columns.', 'ADVANCED', 3, 'MCQ', 1),
(1074, 31, 'Which of the following correctly classifies the SQL statements?', 'CREATE and ALTER are DDL; INSERT and DELETE are DML', 'SELECT and INSERT are DDL; CREATE and DROP are DML', 'TRUNCATE and UPDATE are DDL; SELECT is DML', 'All SQL statements are DDL', 'A', 'DDL covers CREATE, ALTER, and DROP (structure), while DML covers INSERT, UPDATE, and DELETE (data).', 'ADVANCED', 3, 'MCQ', 1),
(1075, 31, 'If table departments has a foreign key referencing employees, what happens by default when you drop the employees table?', 'Both tables are dropped automatically', 'The drop fails because departments depends on the employees table', 'Only departments is dropped', 'NULLs are inserted into departments', 'B', 'Dropping a parent table referenced by a foreign key violates referential integrity, so the database rejects the DROP.', 'ADVANCED', 3, 'MCQ', 1),
(1076, 31, 'Which statement correctly adds a foreign key to an existing table?', 'ALTER TABLE employees ADD COLUMN dept_id;', 'CREATE INDEX FOREIGN KEY dept_id;', 'ALTER TABLE employees ADD FOREIGN KEY (dept_id) REFERENCES departments(id);', 'ALTER TABLE departments ADD FOREIGN KEY dept_id;', 'C', 'ALTER TABLE ... ADD FOREIGN KEY links dept_id in employees to the primary key id in departments.', 'ADVANCED', 3, 'MCQ', 1),
(1077, 31, 'What is the effect of declaring a column with DEFAULT 0?', 'All existing rows are updated to 0', 'The column cannot store any other value', 'NULL is never allowed in the column', 'New rows get 0 when no value is supplied', 'D', 'A DEFAULT value is used only when an INSERT does not provide a value for that column, so missing values become 0.', 'ADVANCED', 3, 'MCQ', 1),
(1078, 31, 'Which approach lets you run the expression SELECT 2 * 3 AS result without any table?', 'Databases such as MySQL allow a SELECT with no FROM clause for literal expressions', 'It is only possible in PostgreSQL', 'You must first create a dummy table', 'It always raises a syntax error', 'A', 'Databases such as MySQL and PostgreSQL allow SELECT over expressions without a FROM clause for computing literal values.', 'ADVANCED', 3, 'MCQ', 1),
(1079, 31, 'Which difference between a CHECK constraint and a NOT NULL constraint is correct?', 'They are identical constraints', 'CHECK validates an arbitrary boolean condition while NOT NULL only bans NULLs', 'CHECK is used only on foreign keys', 'NOT NULL can enforce ranges of values', 'B', 'CHECK enforces an arbitrary boolean condition on column values, while NOT NULL only rejects NULL entries.', 'ADVANCED', 3, 'MCQ', 1),
(1080, 31, 'You want to remove the salary column from the employees table. Which statement achieves this?', 'DELETE COLUMN salary FROM employees;', 'UPDATE employees REMOVE salary;', 'DROP COLUMN salary ALTER employees;', 'ALTER TABLE employees DROP COLUMN salary;', 'D', 'ALTER TABLE ... DROP COLUMN removes the column definition and all of its data from the table.', 'ADVANCED', 3, 'MCQ', 1),
(1081, 32, 'Which SQL statement is used to insert new rows into a table?', 'INSERT', 'SELECT', 'UPDATE', 'DELETE', 'A', 'INSERT INTO is the DML statement that adds new rows to a table.', 'BEGINNER', 1, 'MCQ', 1),
(1082, 32, 'Which statement is used to change the values of existing data in a table?', 'INSERT', 'UPDATE', 'DELETE', 'CREATE', 'B', 'UPDATE modifies the values of existing rows in a table.', 'BEGINNER', 1, 'MCQ', 1),
(1083, 32, 'Which statement removes rows from a table?', 'INSERT', 'UPDATE', 'DELETE', 'ALTER', 'C', 'DELETE removes one or more rows from a table based on its WHERE condition.', 'BEGINNER', 1, 'MCQ', 1),
(1084, 32, 'What does the acronym CRUD stand for?', 'Copy, Read, Update, Delete', 'Create, Read, Unlock, Delete', 'Create, Remove, Update, Drop', 'Create, Read, Update, Delete', 'D', 'CRUD stands for Create, Read, Update, and Delete, the four basic operations on persistent data.', 'BEGINNER', 1, 'MCQ', 1),
(1085, 32, 'Which keyword in an UPDATE statement controls exactly which rows get changed?', 'WHERE', 'SET', 'HAVING', 'GROUP BY', 'A', 'WHERE restricts the UPDATE so only the rows matching the condition are modified.', 'BEGINNER', 1, 'MCQ', 1),
(1086, 32, 'What happens if you run DELETE FROM employees without a WHERE clause?', 'An error is raised', 'All rows in the table are deleted', 'Only the first row is deleted', 'The table structure is removed', 'B', 'Without a WHERE clause every row in the table is deleted, although the table structure remains.', 'BEGINNER', 1, 'MCQ', 1),
(1087, 32, 'Which statement correctly inserts the name ''Ann'' and a salary of 50000 into the employees table?', 'INSERT employees (name, salary) VALUES ''Ann'', 50000;', 'ADD INTO employees (name, salary) (Ann, 50000);', 'INSERT INTO employees (name, salary) VALUES (''Ann'', 50000);', 'UPDATE employees SET name = ''Ann'', salary = 50000;', 'C', 'INSERT INTO followed by column names and a VALUES list is the correct syntax for adding a new row.', 'BEGINNER', 1, 'MCQ', 1),
(1088, 32, 'When inserting into a table with an auto-increment primary key, which column is usually filled in automatically?', 'name', 'dept_id', 'salary', 'id', 'D', 'An auto-increment column such as id is generated by the database automatically during the INSERT.', 'BEGINNER', 1, 'MCQ', 1),
(1089, 32, 'Which statement changes Ann''s salary to 60000?', 'UPDATE employees SET salary = 60000 WHERE name = ''Ann'';', 'UPDATE employees SET name = ''Ann'' WHERE salary = 60000;', 'UPDATE employees VALUES salary = 60000 WHERE name = ''Ann'';', 'INSERT INTO employees (salary) VALUES (60000);', 'A', 'UPDATE employees SET salary = 60000 with a WHERE on name changes only Ann''s salary value.', 'BEGINNER', 1, 'MCQ', 1),
(1090, 32, 'Which is the correct syntax for inserting several rows in one statement?', 'INSERT INTO employees VALUES (1, ''Ann''); (2, ''Bob'');', 'INSERT INTO employees (id, name) VALUES (1, ''Ann''), (2, ''Bob'');', 'INSERT INTO employees (1, ''Ann'') AND (2, ''Bob'');', 'INSERT MULTIPLE INTO employees (id, name) VALUES (1, ''Ann''), (2, ''Bob'');', 'B', 'A multi-row insert lists each row''s values as a separate tuple separated by commas after VALUES.', 'BEGINNER', 1, 'MCQ', 1),
(1091, 32, 'INSERT INTO employees (dept_id, salary) VALUES (3, 45000); is run and name has no NOT NULL constraint. What is the value of the omitted name column?', 'An empty string', 'The previous row''s name', 'NULL (or its declared default value)', 'The statement fails', 'C', 'Columns not listed in the INSERT are set to NULL or to their declared default value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1092, 32, 'Which statement increases every employee''s salary by 10 percent?', 'UPDATE employees SET salary = salary * 1.10;', 'UPDATE employees SET salary = 10;', 'UPDATE employees ADD salary * 1.10;', 'UPDATE employees SET salary = salary + 10;', 'A', 'Multiplying salary by 1.10 adds ten percent to every current salary value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1093, 32, 'Which statement updates both the name and the salary of employee id 1 in one UPDATE?', 'UPDATE employees SET name = ''Ann'' AND salary = 60000 WHERE id = 1;', 'UPDATE employees SET name = ''Ann'', salary = 60000 WHERE id = 1;', 'UPDATE employees SET (name, salary) = (''Ann'', 60000);', 'UPDATE employees name = ''Ann'' salary = 60000 WHERE id = 1;', 'B', 'Multiple assignments in UPDATE are separated by commas in the SET clause.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1094, 32, 'Which query deletes employees whose names start with ''Temp''?', 'DELETE FROM employees WHERE name = ''Temp'';', 'DELETE FROM employees WHERE name IN ''Temp'';', 'DELETE FROM employees WHERE name LIKE ''Temp'';', 'DELETE FROM employees WHERE name LIKE ''Temp%'';', 'D', 'The LIKE pattern ''Temp%'' matches any name that begins with ''Temp'', so those rows are deleted.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1095, 32, 'Which statement copies all rows from old_employees into the existing employees table?', 'INSERT INTO employees SELECT * FROM old_employees;', 'INSERT INTO employees VALUES (SELECT * FROM old_employees);', 'COPY old_employees TO employees;', 'INSERT INTO employees FROM old_employees;', 'A', 'INSERT INTO ... SELECT reads rows from old_employees and adds them to employees in one statement.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1096, 32, 'What happens when you INSERT a row whose id already exists in a primary key column?', 'The new row silently replaces the old one', 'The new row is skipped', 'The insert fails with a duplicate key error', 'Both rows are stored', 'C', 'A primary key requires unique values, so inserting a duplicate id raises a duplicate key error.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1097, 32, 'Which statement deletes employees in department 5 whose salary is below 30000?', 'DELETE FROM employees WHERE dept_id = 5 OR salary < 30000;', 'DELETE FROM employees WHERE dept_id = 5 AND salary < 30000;', 'DELETE FROM employees WHERE dept_id = 5, salary < 30000;', 'DELETE FROM employees WHERE dept_id = 5 AND salary > 30000;', 'B', 'AND combines both conditions so only rows meeting both are deleted, matching the requirement.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1098, 32, 'You run UPDATE employees SET dept_id = NULL WHERE id = 4; on a row that exists. What is TRUE afterwards?', 'The whole row is deleted', 'The row is moved to another table', 'The database rejects the UPDATE', 'The row keeps existing with NULL in dept_id', 'D', 'UPDATE only changes the listed column, so the row remains with dept_id set to NULL.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1099, 32, 'Which statement deletes orders rows that have no matching employee in the employees table?', 'DELETE FROM orders WHERE emp_id NOT IN (SELECT id FROM employees);', 'DELETE FROM orders WHERE emp_id IN (SELECT id FROM employees);', 'DELETE FROM employees WHERE id NOT IN (SELECT emp_id FROM orders);', 'DELETE FROM orders JOIN employees ON orders.emp_id = employees.id;', 'A', 'NOT IN with a subquery selects orders whose emp_id does not appear among valid employee ids, deleting only those.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1100, 32, 'Which statement sets a NULL salary to 0 for all employees?', 'UPDATE employees SET salary = 0 WHERE salary IS NOT NULL;', 'UPDATE employees SET salary = NULL WHERE salary = 0;', 'UPDATE employees SET salary = 0 WHERE salary IS NULL;', 'UPDATE employees SET salary = 0 WHERE salary != 0;', 'C', 'WHERE salary IS NULL targets only the rows whose salary is NULL, and SET salary = 0 writes the new value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1101, 32, 'Which statement is TRUE about INSERT ... ON DUPLICATE KEY UPDATE in MySQL?', 'It always inserts a new row', 'It updates the existing row when a unique key collision occurs, otherwise inserts a new row', 'It is invalid syntax in MySQL', 'It deletes the colliding row and inserts a new one', 'B', 'ON DUPLICATE KEY UPDATE performs an UPDATE of the conflicting row on a unique-key collision and otherwise inserts.', 'ADVANCED', 3, 'MCQ', 1),
(1102, 32, 'What is a key difference between REPLACE INTO and INSERT ... ON DUPLICATE KEY UPDATE?', 'There is no difference between them', 'ON DUPLICATE KEY UPDATE deletes the old row first', 'REPLACE deletes the conflicting row and inserts a new one, while ON DUPLICATE KEY UPDATE changes only specified columns', 'REPLACE only works on MyISAM tables', 'C', 'REPLACE removes the conflicting row and inserts a fresh one, whereas ON DUPLICATE KEY UPDATE only modifies the listed columns.', 'ADVANCED', 3, 'MCQ', 1),
(1103, 32, 'Inside a transaction you run an UPDATE and then issue a ROLLBACK. What is the result?', 'The UPDATE is kept', 'Only half the rows keep the update', 'The statement fails at rollback time', 'The table returns to its state before the UPDATE', 'D', 'ROLLBACK undoes all uncommitted changes in the transaction, restoring the table to its prior state.', 'ADVANCED', 3, 'MCQ', 1),
(1104, 32, 'If a foreign key between orders and employees is defined with ON DELETE CASCADE, what happens when you delete an employee?', 'Deleting an employee automatically deletes their orders', 'Deleting an employee is blocked', 'Orders keep the deleted employee id', 'The database repairs the orders', 'A', 'ON DELETE CASCADE propagates the deletion so that referencing rows in orders are removed automatically.', 'ADVANCED', 3, 'MCQ', 1),
(1105, 32, 'Which UPDATE modifies only employees who have a matching record in the departments table?', 'UPDATE employees SET bonus = 100 WHERE dept_id = 1;', 'UPDATE employees SET bonus = 100 WHERE dept_id IN (SELECT id FROM departments);', 'UPDATE employees SET bonus = 100 FOR ALL ROWS;', 'UPDATE employees SET bonus = 100 WHERE dept_id NOT IN (SELECT id FROM departments);', 'B', 'The IN subquery restricts the UPDATE to dept_id values that actually exist in departments.', 'ADVANCED', 3, 'MCQ', 1),
(1106, 32, 'What does an upsert operation such as PostgreSQL INSERT ... ON CONFLICT achieve?', 'Deletes the conflicting row', 'Only inserts rows, never updates', 'Inserts a new row or updates the conflicting row in one statement', 'Is only valid inside stored procedures', 'C', 'An upsert inserts a new row when there is no conflict and updates the existing row when a conflict occurs, all in one statement.', 'ADVANCED', 3, 'MCQ', 1),
(1107, 32, 'Which approach cleanly deletes the employee with the highest salary?', 'DELETE FROM employees WHERE salary > ALL;', 'TRUNCATE employees;', 'DELETE TOP 1 FROM employees;', 'DELETE FROM employees WHERE salary = (SELECT MAX(salary) FROM employees);', 'D', 'The scalar subquery computes the maximum salary, and the DELETE removes exactly the row holding that value.', 'ADVANCED', 3, 'MCQ', 1),
(1108, 32, 'Which statement is TRUE about a multi-table DELETE in MySQL, such as DELETE t1 FROM t1 JOIN t2 ON ...?', 'MySQL supports deleting rows from one table using a multi-table DELETE with JOIN syntax', 'You can never use a join inside a DELETE statement', 'Joins are only allowed in SELECT statements', 'Multi-table DELETE is exclusive to Oracle', 'A', 'MySQL allows a multi-table DELETE where rows of one table are deleted based on a JOIN with another table.', 'ADVANCED', 3, 'MCQ', 1),
(1109, 32, 'After running UPDATE employees SET dept_id = dept_id + 1 WHERE dept_id < 3; twice in a row, which rows change in the second run?', 'The same rows are updated again', 'Only rows that still satisfy dept_id < 3 are updated again', 'All rows are updated again', 'The statement fails the second time', 'B', 'The second run only affects rows whose dept_id is still less than 3, since the first run shifted some rows out of range.', 'ADVANCED', 3, 'MCQ', 1),
(1110, 32, 'Which statement sets bonus to 500 only for employees in department 4 while leaving all other rows unchanged?', 'UPDATE employees SET bonus = 500 FOR dept_id = 4;', 'UPDATE employees SET bonus = 500 WHERE dept_id != 4;', 'INSERT INTO employees (bonus) VALUES (500);', 'UPDATE employees SET bonus = 500 WHERE dept_id = 4;', 'D', 'The WHERE dept_id = 4 condition restricts the bonus change to exactly the employees in department 4.', 'ADVANCED', 3, 'MCQ', 1),
(1111, 33, 'Which join returns only the rows that have matching values in both tables?', 'INNER JOIN', 'LEFT JOIN', 'FULL OUTER JOIN', 'CROSS JOIN', 'A', 'INNER JOIN keeps only the rows where the join condition matches in both tables.', 'BEGINNER', 1, 'MCQ', 1),
(1112, 33, 'Which join returns all rows from the left table and the matching rows from the right table?', 'RIGHT JOIN', 'LEFT JOIN', 'FULL OUTER JOIN', 'INNER JOIN', 'B', 'LEFT JOIN keeps every row of the left table and fills unmatched right-side columns with NULL.', 'BEGINNER', 1, 'MCQ', 1),
(1113, 33, 'Which join returns all rows from both tables, filling in NULLs for the sides without a match?', 'INNER JOIN', 'LEFT JOIN', 'FULL OUTER JOIN', 'SELF JOIN', 'C', 'FULL OUTER JOIN returns every row from both tables, using NULLs where no match exists on either side.', 'BEGINNER', 1, 'MCQ', 1),
(1114, 33, 'Which keyword specifies how two tables are related in a JOIN?', 'SET', 'USING IN', 'HAVING', 'ON', 'D', 'The ON clause supplies the join condition that describes how rows from the two tables correspond.', 'BEGINNER', 1, 'MCQ', 1),
(1115, 33, 'A CROSS JOIN between two tables produces what kind of result?', 'The Cartesian product of the two tables', 'Only the exact matching rows', 'A single summary row', 'An error', 'A', 'A CROSS JOIN pairs every row of the first table with every row of the second, forming the Cartesian product.', 'BEGINNER', 1, 'MCQ', 1),
(1116, 33, 'Which join returns all rows from the right table and the matching rows from the left table?', 'LEFT JOIN', 'RIGHT JOIN', 'INNER JOIN', 'OUTER LEFT', 'B', 'RIGHT JOIN keeps every row of the right table and uses NULLs for unmatched left-side columns.', 'BEGINNER', 1, 'MCQ', 1),
(1117, 33, 'What is a self join?', 'Joining two unrelated tables', 'Joining three tables at once', 'Joining a table to itself', 'Joining a table to its stored backup', 'C', 'A self join joins a table to itself, usually with different aliases, to compare rows within the same table.', 'BEGINNER', 1, 'MCQ', 1),
(1118, 33, 'employees(id, name, dept_id) is INNER JOINed to departments(id, name) on employees.dept_id = departments.id. How many rows result if 3 employees match and 1 employee has a department id that does not exist?', '1', '4', '2', '3', 'D', 'INNER JOIN keeps only matching rows, so the 3 employees whose department exists appear and the unmatched employee is dropped.', 'BEGINNER', 1, 'MCQ', 1),
(1119, 33, 'In a LEFT JOIN, what appears in the result for an employee whose department does not exist?', 'The department columns are NULL', 'The employee row is dropped', 'A new department is created', 'The query fails', 'A', 'LEFT JOIN preserves every employee row and fills the missing department columns with NULL when there is no match.', 'BEGINNER', 1, 'MCQ', 1),
(1120, 33, 'Which join would you use to list every department even if it has no employees?', 'INNER JOIN', 'A LEFT JOIN where departments is the left table', 'CROSS JOIN', 'A LEFT JOIN where employees is the left table', 'B', 'Putting departments on the left of a LEFT JOIN guarantees every department appears, with NULLs for empty ones.', 'BEGINNER', 1, 'MCQ', 1),
(1121, 33, 'employees(id, name, dept_id): rows (1,''Ann'',1),(2,''Bob'',1),(3,''Cid'',4). departments(id, name): (1,''Sales''),(2,''IT''),(3,''HR''). How many rows does an INNER JOIN on employees.dept_id = departments.id produce?', '3', '5', '2', '9', 'C', 'Ann and Bob match department 1, but Cid''s department 4 does not exist, so only 2 matching rows remain.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1122, 33, 'Using the same employees and departments tables, how many rows does a LEFT JOIN with employees as the left table produce?', '3', '4', '2', '5', 'A', 'LEFT JOIN returns all 3 employee rows, with Cid''s department columns filled as NULL because dept 4 is missing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1123, 33, 'Using the same tables, what department name does employee Ann get in the INNER JOIN result?', 'Sales', 'IT', 'HR', 'NULL', 'A', 'Ann has dept_id 1 which matches the department named ''Sales'', so her joined row shows Sales.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1124, 33, 'If employees has 3 rows and departments has 4 rows, how many rows does a CROSS JOIN produce?', '7', '4', '3', '12', 'D', 'A CROSS JOIN produces the Cartesian product, which is 3 multiplied by 4, giving 12 rows.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1125, 33, 'Which query lists each employee together with the name of their department?', 'SELECT e.name, d.name FROM employees e INNER JOIN departments d ON e.dept_id = d.id;', 'SELECT e.name, d.name FROM employees e, departments d WHERE e.id = d.id;', 'SELECT e.name, d.name FROM employees e FULL JOIN departments d ON e.dept_id = d.id;', 'SELECT e.name, d.name FROM employees e CROSS JOIN departments d;', 'A', 'The INNER JOIN on dept_id = id connects each employee to the correct department so both names can be listed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1126, 33, 'Which query finds the employees who work in the ''Sales'' department using a join?', 'SELECT e.* FROM employees e JOIN departments d ON e.dept_id = d.id;', 'SELECT e.* FROM employees e JOIN departments d ON e.dept_id = d.id WHERE d.id = 1;', 'SELECT e.* FROM employees e JOIN departments d ON e.dept_id = d.id WHERE d.name = ''Sales'';', 'SELECT e.* FROM employees e JOIN departments d ON e.name = d.name WHERE d.name = ''Sales'';', 'C', 'Joining on dept_id and filtering with WHERE d.name = ''Sales'' returns exactly the employees of that department.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1127, 33, 'A self join on employees using manager_id is most useful for finding what?', 'Employees in different departments', 'Employees together with their manager''s name from the same table', 'Department names for each employee', 'Only employees without managers', 'B', 'A self join pairs each employee row with the manager row from the same table, revealing the manager''s name.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1128, 33, 'Which join is equivalent to RIGHT JOIN departments d ON ... with employees as the other table?', 'INNER JOIN', 'CROSS JOIN', 'FULL OUTER JOIN', 'A LEFT JOIN with the tables swapped', 'D', 'Reversing the table order and using LEFT JOIN produces the same rows as a RIGHT JOIN on the original order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1129, 33, 'Which join shows every employee, and for employees in no department the department name appears as NULL?', 'LEFT JOIN employees.dept_id = departments.id', 'INNER JOIN', 'RIGHT JOIN', 'CROSS JOIN', 'A', 'LEFT JOIN keeps all employee rows and uses NULL for department columns of employees without a matching department.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1130, 33, 'Which query counts the number of employees in each department, including departments with zero employees?', 'SELECT d.name, COUNT(*) FROM employees e JOIN departments d GROUP BY e.dept_id;', 'SELECT d.name, COUNT(e.id) FROM departments d JOIN employees e ON d.id = e.dept_id ORDER BY d.name;', 'SELECT d.name, COUNT(e.id) FROM departments d LEFT JOIN employees e ON d.id = e.dept_id GROUP BY d.id, d.name;', 'SELECT COUNT(*) FROM employees JOIN departments;', 'C', 'The LEFT JOIN preserves all departments, and GROUP BY d.id, d.name lets COUNT(e.id) count employees per department including zeros.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1131, 33, 'MySQL does not natively support FULL OUTER JOIN. Which construct emulates it?', 'A single INNER JOIN', 'A UNION of a LEFT JOIN result and a RIGHT JOIN result', 'A CROSS JOIN', 'A self join', 'B', 'Combining a LEFT JOIN and a RIGHT JOIN with UNION yields every row from both tables, which is the effect of FULL OUTER JOIN.', 'ADVANCED', 3, 'MCQ', 1),
(1132, 33, 'In LEFT JOIN employees e LEFT JOIN departments d ON e.dept_id = d.id, what happens if you add WHERE d.name = ''Sales''?', 'It still returns all employees', 'It returns only the unmatched rows', 'The WHERE clause filters out rows with NULL department columns, so unmatched employees disappear', 'It raises an error', 'C', 'The WHERE filter runs after the join and removes rows where d.name is NULL, effectively turning the LEFT JOIN into an INNER JOIN.', 'ADVANCED', 3, 'MCQ', 1),
(1133, 33, 'What is a non-equi join?', 'A join on primary keys', 'A join without the ON clause', 'A join between unrelated tables', 'A join using a comparison operator other than equals, such as < or >', 'D', 'A non-equi join uses operators like <, >, BETWEEN, or <> in the join condition instead of a plain equality.', 'ADVANCED', 3, 'MCQ', 1),
(1134, 33, 'To make the join employees.dept_id = departments.id run as fast as possible, what should you index?', 'The dept_id column in employees and the id primary key in departments', 'Only the name columns', 'No index helps a join', 'The salary column', 'A', 'An index on the join columns, especially the foreign key dept_id and the referenced primary key id, lets the database find matches quickly.', 'ADVANCED', 3, 'MCQ', 1),
(1135, 33, 'Which query correctly joins employees to itself to pair each employee with their manager''s name?', 'SELECT e.name, m.name FROM employees e JOIN employees m ON e.manager_id = m.name;', 'SELECT e.name AS emp, m.name AS mgr FROM employees e LEFT JOIN employees m ON e.manager_id = m.id;', 'SELECT e.name FROM employees e INNER JOIN employees m ON e.id = m.id;', 'SELECT e.name, m.name FROM employees e, departments m;', 'B', 'The self join matches each employee''s manager_id to the manager''s id in the same table, and LEFT JOIN keeps employees without managers.', 'ADVANCED', 3, 'MCQ', 1),
(1136, 33, 'Which query returns the departments that have no employees at all?', 'SELECT d.name FROM departments d INNER JOIN employees e ON d.id = e.dept_id;', 'SELECT d.name FROM departments d LEFT JOIN employees e ON d.id = e.dept_id;', 'SELECT d.name FROM departments d LEFT JOIN employees e ON d.id = e.dept_id WHERE e.id IS NULL;', 'SELECT d.name FROM departments d CROSS JOIN employees e WHERE d.id IS NULL;', 'C', 'The LEFT JOIN keeps all departments, and WHERE e.id IS NULL isolates those departments where no employee matched.', 'ADVANCED', 3, 'MCQ', 1),
(1137, 33, 'What is the result of a CROSS JOIN between employees, which has 3 rows, and departments, which has 4 rows?', '7 rows', '4 rows', '3 rows', '12 rows', 'D', 'A CROSS JOIN multiplies the row counts, so 3 times 4 equals 12 rows in the result.', 'ADVANCED', 3, 'MCQ', 1),
(1138, 33, 'In which situation does a LEFT JOIN return MORE rows than an INNER JOIN on the same condition?', 'When the left table has rows with no match in the right table', 'When every row has a match', 'Never', 'When the right table has duplicate rows', 'A', 'LEFT JOIN keeps all left-table rows, so any left row without a right-side match adds a row that the INNER JOIN would drop.', 'ADVANCED', 3, 'MCQ', 1),
(1139, 33, 'Which query returns employees who work in departments whose name contains ''Tech''?', 'SELECT e.name FROM employees e JOIN departments d ON e.dept_id = d.id WHERE d.name = ''Tech'';', 'SELECT e.name FROM employees e JOIN departments d ON e.dept_id = d.id WHERE d.name LIKE ''%Tech%'';', 'SELECT e.name FROM employees e JOIN departments d ON e.dept_id = d.id WHERE e.name LIKE ''%Tech%'';', 'SELECT e.name FROM employees e LEFT JOIN departments d ON e.dept_id = d.id;', 'B', 'The LIKE ''%Tech%'' filter on the department name matches any department containing ''Tech'' after the join.', 'ADVANCED', 3, 'MCQ', 1),
(1140, 33, 'What distinguishes a join condition in the ON clause from one in the WHERE clause for an OUTER join?', 'There is no difference between them', 'ON is always faster than WHERE', 'WHERE can only use equality comparisons', 'ON controls which rows join and preserves unmatched rows; WHERE filters the joined result and removes unmatched rows', 'D', 'ON determines the join and preserves unmatched outer rows, while a WHERE condition filters the final result and can discard those rows.', 'ADVANCED', 3, 'MCQ', 1),
(1141, 34, 'What is a subquery?', 'A query nested inside another query', 'A query run after the main query', 'A table that is joined twice', 'A stored procedure', 'A', 'A subquery is a complete query written inside another query, such as in the WHERE or FROM clause.', 'BEGINNER', 1, 'MCQ', 1),
(1142, 34, 'Which operator checks whether a value appears in the result of a subquery?', 'BETWEEN', 'IN', 'LIKE', 'IS', 'B', 'The IN operator returns TRUE when the value matches any value in the subquery result list.', 'BEGINNER', 1, 'MCQ', 1),
(1143, 34, 'Which set operator combines two result sets and removes duplicate rows?', 'JOIN', 'MERGE', 'UNION', 'COMBINE', 'C', 'UNION combines two queries and removes duplicate rows from the final result.', 'BEGINNER', 1, 'MCQ', 1),
(1144, 34, 'Which set operator returns only the rows that are present in both result sets?', 'UNION', 'EXCEPT', 'MINUS', 'INTERSECT', 'D', 'INTERSECT returns the rows that appear in both of the combined queries.', 'BEGINNER', 1, 'MCQ', 1),
(1145, 34, 'A scalar subquery returns how many values?', 'Exactly one value', 'A list of many values', 'A whole table', 'No value', 'A', 'A scalar subquery returns a single row and a single column, i.e., exactly one value.', 'BEGINNER', 1, 'MCQ', 1),
(1146, 34, 'Which set operator returns the rows from the first result set that do NOT appear in the second?', 'INTERSECT', 'EXCEPT (or MINUS)', 'UNION', 'INNER JOIN', 'B', 'EXCEPT (called MINUS in Oracle) returns rows that are in the first query but not in the second.', 'BEGINNER', 1, 'MCQ', 1),
(1147, 34, 'What does UNION ALL do differently compared to UNION?', 'It removes all rows', 'It is slower than INTERSECT', 'It keeps all rows including duplicates', 'It sorts the output automatically', 'C', 'UNION ALL keeps every row from both queries, including duplicates, instead of removing them like UNION.', 'BEGINNER', 1, 'MCQ', 1),
(1148, 34, 'Where can a subquery be placed in a SQL statement?', 'Only in the WHERE clause', 'Only in the FROM clause', 'Only in the ORDER BY clause', 'In the WHERE, FROM, or SELECT clause', 'D', 'Subqueries are commonly used in WHERE, FROM (as a derived table), and SELECT clauses.', 'BEGINNER', 1, 'MCQ', 1),
(1149, 34, 'Which keyword tests whether a subquery returns at least one row?', 'EXISTS', 'ANY', 'ALL', 'IN', 'A', 'EXISTS returns TRUE if the subquery produces one or more rows, regardless of their values.', 'BEGINNER', 1, 'MCQ', 1),
(1150, 34, 'Which operator checks that a value is less than ALL values returned by a subquery?', 'ANY', 'ALL', 'SOME', 'EVERY', 'B', 'The ALL operator requires the comparison to hold for every value returned by the subquery.', 'BEGINNER', 1, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(1151, 34, 'Which query finds employees who earn more than the average salary of all employees?', 'SELECT * FROM employees WHERE salary > AVG(salary);', 'SELECT * FROM employees HAVING salary > AVG(salary);', 'SELECT * FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);', 'SELECT * FROM employees WHERE salary > (SELECT MAX(salary) FROM employees);', 'C', 'The scalar subquery computes the overall average, and the WHERE clause keeps employees above it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1152, 34, 'Which query returns employees who work in the ''Sales'' or ''IT'' departments using IN with a subquery?', 'SELECT * FROM employees WHERE dept_id IN (SELECT id FROM departments WHERE name IN (''Sales'', ''IT''));', 'SELECT * FROM employees WHERE dept_id = (SELECT id FROM departments WHERE name = ''Sales'');', 'SELECT * FROM employees WHERE dept_id IN (SELECT name FROM departments);', 'SELECT * FROM employees WHERE name IN (''Sales'', ''IT'');', 'A', 'The subquery returns the ids of the Sales and IT departments, and IN keeps employees whose dept_id matches one of them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1153, 34, 'Which query lists each employee''s name together with the overall maximum salary as a column?', 'SELECT name, MAX(salary) FROM employees;', 'SELECT name, (SELECT MAX(salary) FROM employees) AS max_sal FROM employees;', 'SELECT name, SUM(salary) FROM employees;', 'SELECT name FROM employees WHERE salary = MAX(salary);', 'B', 'A scalar subquery in the SELECT list adds the overall maximum salary to every row without grouping the result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1154, 34, 'Which query finds the second-highest salary in the employees table?', 'SELECT MAX(salary) FROM employees WHERE salary = MAX(salary);', 'SELECT salary FROM employees LIMIT 1, 1;', 'SELECT MAX(salary) FROM employees ORDER BY salary DESC;', 'SELECT MAX(salary) FROM employees WHERE salary < (SELECT MAX(salary) FROM employees);', 'D', 'The inner subquery gets the highest salary, and the outer MAX finds the largest salary below it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1155, 34, 'What is a correlated subquery?', 'A subquery that references columns of the outer query and runs once per outer row', 'A subquery that runs exactly once', 'A subquery that cannot use EXISTS', 'A subquery placed in the FROM clause', 'A', 'A correlated subquery refers to columns of the enclosing query, so it is evaluated once for each outer row.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1156, 34, 'A UNION combines the employees of department 1 (3 people) with the employees of department 2 (2 people), and no person belongs to both. How many rows does the UNION return?', '2', '6', '5', '3', 'C', 'Since the two sets do not overlap, UNION keeps all 3 plus all 2 rows for a total of 5.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1157, 34, 'What is a key difference between UNION ALL and UNION?', 'UNION ALL sorts the rows, UNION does not', 'UNION ALL keeps duplicate rows, UNION removes them', 'UNION ALL only works on numeric columns', 'UNION is faster than UNION ALL', 'B', 'UNION applies a distinct pass to remove duplicates, while UNION ALL returns every row as produced by the queries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1158, 34, 'Which query finds the departments that have at least one employee using EXISTS?', 'SELECT id FROM departments WHERE id IN (SELECT id FROM departments);', 'SELECT id FROM departments WHERE EXISTS (SELECT 1 FROM employees);', 'SELECT DISTINCT d.id FROM departments d, employees e;', 'SELECT id FROM departments d WHERE EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id);', 'D', 'The correlated EXISTS checks each department for at least one employee with that dept_id, returning only populated departments.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1159, 34, 'The employees table has dept_id values (1, 2, 3) and the departments table has ids (1, 2, 4). Which dept_id value appears in employees but is not a department id?', '3', '1', '2', '4', 'A', 'The value 3 exists in employees but is absent from the departments ids, so it is the difference of the two sets.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1160, 34, 'Which query finds employees who have the same salary as at least one other employee?', 'SELECT * FROM employees WHERE salary = salary;', 'SELECT * FROM employees e1 WHERE salary > (SELECT MAX(salary) FROM employees e2 WHERE e1.id = e2.id);', 'SELECT * FROM employees e1 WHERE EXISTS (SELECT 1 FROM employees e2 WHERE e1.salary = e2.salary AND e1.id != e2.id);', 'SELECT * FROM employees WHERE salary IN (SELECT dept_id FROM departments);', 'C', 'The correlated EXISTS finds another employee with the same salary but a different id, so only duplicated salaries qualify.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1161, 34, 'Which query lists employees who earn more than their own department''s average salary?', 'SELECT * FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);', 'SELECT * FROM employees e WHERE salary > (SELECT AVG(salary) FROM employees WHERE dept_id = e.dept_id);', 'SELECT * FROM employees WHERE salary > AVG(salary) OVER ();', 'SELECT * FROM employees WHERE salary > ALL (SELECT salary FROM employees);', 'B', 'The correlated subquery computes the average per the outer row''s dept_id, so each employee is compared to their own department average.', 'ADVANCED', 3, 'MCQ', 1),
(1162, 34, 'employees: (1,''Ann'',4000,d1),(2,''Bob'',8000,d1),(3,''Cid'',9000,d2),(4,''Dee'',9500,d2). How many employees earn more than their department average in a correlated subquery comparison?', '3', '1', '2', '0', 'C', 'Department d1 averages 6000 and Bob qualifies, while d2 averages 9250 and Dee qualifies, so exactly 2 employees qualify.', 'ADVANCED', 3, 'MCQ', 1),
(1163, 34, 'Which statement is TRUE about using NOT IN with a subquery that returns NULL values?', 'NOT IN ignores NULL values entirely', 'NOT IN is always faster than NOT EXISTS', 'NULL values make NOT IN return all rows', 'If the subquery result contains any NULL, NOT IN may return zero rows', 'D', 'Because NULL compares to UNKNOWN, NOT IN can produce no rows at all when the subquery contains any NULL, which is why NOT EXISTS is safer.', 'ADVANCED', 3, 'MCQ', 1),
(1164, 34, 'Which query uses a subquery in the FROM clause (derived table) to show departments with more than 2 employees?', 'SELECT dept_id, cnt FROM (SELECT dept_id, COUNT(*) AS cnt FROM employees GROUP BY dept_id) AS t WHERE cnt > 2;', 'SELECT dept_id, COUNT(*) FROM employees WHERE COUNT(*) > 2 GROUP BY dept_id;', 'SELECT dept_id FROM employees WHERE dept_id IN (SELECT 1);', 'SELECT dept_id, COUNT(*) FROM employees HAVING cnt > 2;', 'A', 'The derived table aggregates the counts, and the outer query filters on the cnt column to keep only groups above 2.', 'ADVANCED', 3, 'MCQ', 1),
(1165, 34, 'Which is a valid way to rank each employee''s salary within their own department using a correlated subquery?', 'SELECT name, COUNT(*) FROM employees;', 'SELECT e1.name, (SELECT COUNT(*) + 1 FROM employees e2 WHERE e2.dept_id = e1.dept_id AND e2.salary > e1.salary) AS rnk FROM employees e1;', 'SELECT name, RANK() FROM employees;', 'SELECT name, salary FROM employees WHERE salary > ALL (SELECT salary);', 'B', 'The correlated subquery counts how many colleagues in the same department earn more, and adding 1 produces a rank.', 'ADVANCED', 3, 'MCQ', 1),
(1166, 34, 'INTERSECT returns which rows from two queries A and B?', 'Rows in A but not B', 'All rows of A and B combined', 'Rows that appear in both A and B', 'Rows in B but not A', 'C', 'INTERSECT keeps only the rows that exist in both result sets of A and B.', 'ADVANCED', 3, 'MCQ', 1),
(1167, 34, 'Set operations like UNION require what about the two queries involved?', 'The same table name', 'Identical column names', 'At least one common key', 'The same number of columns with compatible data types', 'D', 'Set operations line up columns positionally, so both queries must return the same number of columns with compatible types.', 'ADVANCED', 3, 'MCQ', 1),
(1168, 34, 'Which query finds the employees in the Sales department who are NOT in the IT department using set operators on the employees table?', 'SELECT id FROM employees WHERE dept_id IN (SELECT id FROM departments WHERE name = ''Sales'') EXCEPT SELECT id FROM employees WHERE dept_id IN (SELECT id FROM departments WHERE name = ''IT'');', 'SELECT id FROM employees WHERE dept_id IN (''Sales'') UNION SELECT id FROM employees;', 'SELECT id FROM employees WHERE name = ''Sales'' INTERSECT SELECT id FROM employees WHERE name = ''IT'';', 'SELECT id FROM employees WHERE dept_id NOT IN (SELECT id FROM departments);', 'A', 'EXCEPT removes the IT employees from the Sales set, leaving exactly the employees in Sales but not in IT.', 'ADVANCED', 3, 'MCQ', 1),
(1169, 34, 'Which statement is TRUE about how a correlated subquery is executed?', 'It is evaluated once total', 'It is evaluated once for each row processed by the outer query', 'It can only be used in the SELECT list', 'It is always slower than a join', 'B', 'Because a correlated subquery depends on the current outer row, the database evaluates it once for each outer row.', 'ADVANCED', 3, 'MCQ', 1),
(1170, 34, 'Query A returns employee ids (1, 2) and query B returns employee ids (2, 3). How many rows does INTERSECT return?', '3', '2', '0', '1', 'D', 'Only id 2 appears in both result sets, so INTERSECT returns exactly 1 row.', 'ADVANCED', 3, 'MCQ', 1),
(1171, 35, 'Which aggregate function counts the number of rows in a result set?', 'COUNT', 'SUM', 'AVG', 'MAX', 'A', 'COUNT returns the number of rows that satisfy the query, which is what counting requires.', 'BEGINNER', 1, 'MCQ', 1),
(1172, 35, 'Which aggregate function returns the average value of a numeric column?', 'SUM', 'AVG', 'MIN', 'MEDIAN', 'B', 'AVG computes the arithmetic mean of the numeric values in a column.', 'BEGINNER', 1, 'MCQ', 1),
(1173, 35, 'Which aggregate function returns the largest value in a column?', 'MIN', 'COUNT', 'MAX', 'TOTAL', 'C', 'MAX returns the largest value found in the column being aggregated.', 'BEGINNER', 1, 'MCQ', 1),
(1174, 35, 'Which clause groups rows that share the same column values into summary rows?', 'ORDER BY', 'WHERE', 'HAVING', 'GROUP BY', 'D', 'GROUP BY collects rows with equal values in the listed columns so aggregates can be computed per group.', 'BEGINNER', 1, 'MCQ', 1),
(1175, 35, 'Which aggregate function adds up all the values in a numeric column?', 'SUM', 'AVG', 'COUNT', 'MAX', 'A', 'SUM totals the numeric values of the column across the grouped rows.', 'BEGINNER', 1, 'MCQ', 1),
(1176, 35, 'Which clause is used to filter groups after aggregation has taken place?', 'WHERE', 'HAVING', 'GROUP BY', 'ORDER BY', 'B', 'HAVING filters grouped results based on aggregate values, unlike WHERE which filters individual rows.', 'BEGINNER', 1, 'MCQ', 1),
(1177, 35, 'Which aggregate function returns the smallest value in a column?', 'MAX', 'AVG', 'MIN', 'COUNT', 'C', 'MIN returns the smallest value found in the column being aggregated.', 'BEGINNER', 1, 'MCQ', 1),
(1178, 35, 'What does COUNT(*) count?', 'Only rows with no NULLs', 'Only distinct values', 'Non-null columns only', 'Every row including rows with NULLs', 'D', 'COUNT(*) counts every row regardless of NULL values in any particular column.', 'BEGINNER', 1, 'MCQ', 1),
(1179, 35, 'Which aggregate functions typically IGNORE NULL values in their calculations?', 'SUM and AVG', 'COUNT(*)', 'MAX and MIN always ignore NULLs', 'None of the aggregate functions', 'A', 'SUM and AVG skip NULL entries during computation, while COUNT(*) includes all rows.', 'BEGINNER', 1, 'MCQ', 1),
(1180, 35, 'Which query counts the total number of employees in the employees table?', 'SELECT COUNT(name) FROM employees WHERE name = ''Ann'';', 'SELECT COUNT(*) FROM employees;', 'SELECT COUNT FROM employees;', 'SELECT * FROM employees GROUP BY COUNT;', 'B', 'COUNT(*) counts all rows in the employees table, giving the total number of employees.', 'BEGINNER', 1, 'MCQ', 1),
(1181, 35, 'Which query counts how many employees are in each department?', 'SELECT dept_id, COUNT(*) FROM employees;', 'SELECT dept_id FROM employees HAVING COUNT(*);', 'SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id;', 'SELECT dept_id, COUNT(*) FROM employees WHERE COUNT(*) > 1;', 'C', 'GROUP BY dept_id creates one group per department, and COUNT(*) tallies the employees in each group.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1182, 35, 'Which statement correctly describes WHERE versus HAVING?', 'WHERE filters rows before grouping; HAVING filters groups after aggregation', 'HAVING filters rows before grouping takes place', 'They are interchangeable in every query', 'WHERE cannot be used together with GROUP BY', 'A', 'WHERE removes individual rows first, while HAVING removes entire groups after the aggregates are computed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1183, 35, 'Which query finds the average salary in each department?', 'SELECT dept_id, salary FROM employees GROUP BY salary;', 'SELECT dept_id, AVG(salary) FROM employees GROUP BY dept_id;', 'SELECT AVG(dept_id) FROM employees GROUP BY salary;', 'SELECT dept_id, AVG(salary) FROM employees;', 'B', 'GROUP BY dept_id groups employees by department and AVG(salary) computes each group''s average salary.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1184, 35, 'Which query returns only the departments that have more than 5 employees?', 'SELECT dept_id FROM employees WHERE COUNT(*) > 5 GROUP BY dept_id;', 'SELECT dept_id, COUNT(*) FROM employees WHERE COUNT(*) > 5;', 'SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id WHERE COUNT(*) > 5;', 'SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id HAVING COUNT(*) > 5;', 'D', 'HAVING COUNT(*) > 5 filters the grouped departments, keeping only groups with more than 5 employees.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1185, 35, 'Which query sums the salaries of all employees?', 'SELECT SUM(salary) FROM employees;', 'SELECT salary FROM employees SUM;', 'SELECT SUM(salary) FROM employees GROUP BY name;', 'SELECT COUNT(salary) FROM employees;', 'A', 'SUM(salary) adds up the salary column across all rows in the employees table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1186, 35, 'Which query finds the highest salary in each department?', 'SELECT dept_id, salary FROM employees GROUP BY dept_id, salary;', 'SELECT dept_id, MAX(salary) FROM employees WHERE MAX(salary) GROUP BY dept_id;', 'SELECT dept_id, MAX(salary) FROM employees GROUP BY dept_id;', 'SELECT dept_id, salary FROM employees ORDER BY salary DESC;', 'C', 'GROUP BY dept_id creates per-department groups and MAX(salary) returns the top salary of each group.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1187, 35, 'Which query counts the number of distinct departments that appear in the employees table?', 'SELECT COUNT(dept_id) FROM employees;', 'SELECT COUNT(DISTINCT dept_id) FROM employees;', 'SELECT DISTINCT COUNT(dept_id) FROM employees;', 'SELECT COUNT(*) FROM departments;', 'B', 'COUNT(DISTINCT dept_id) counts each department id only once, giving the number of unique departments.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1188, 35, 'GROUP BY dept_id, grade produces summary rows for what combination?', 'Each distinct dept_id only', 'Each distinct grade only', 'One row per employee', 'Each distinct combination of dept_id and grade', 'D', 'Grouping by two columns forms one group for every distinct pair of dept_id and grade values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1189, 35, 'Which query returns departments sorted by the number of employees from most to least?', 'SELECT dept_id, COUNT(*) AS c FROM employees GROUP BY dept_id ORDER BY c DESC;', 'SELECT dept_id, COUNT(*) FROM employees ORDER BY COUNT(*) DESC GROUP BY dept_id;', 'SELECT dept_id, COUNT(*) AS c FROM employees GROUP BY dept_id ORDER BY COUNT;', 'SELECT dept_id FROM employees ORDER BY COUNT(*) DESC;', 'A', 'The COUNT(*) alias c is sorted with ORDER BY c DESC, listing the largest groups first.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1190, 35, 'Which query finds the average salary of the employees in department 2?', 'SELECT AVG(salary) FROM employees GROUP BY dept_id;', 'SELECT dept_id, AVG(salary) FROM employees HAVING dept_id = 2;', 'SELECT AVG(salary) FROM employees WHERE dept_id = 2;', 'SELECT AVG(dept_id) FROM employees WHERE salary = 2;', 'C', 'WHERE dept_id = 2 restricts the rows before the aggregation, so AVG(salary) covers only department 2.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1191, 35, 'Given employees: (1,''Ann'',5000,d1),(2,''Bob'',6000,d1),(3,''Cid'',7000,d2). What does ROW_NUMBER() OVER (ORDER BY salary DESC) assign to the three rows?', 'The same number to all rows', '1, 2, 3 based on the ordered position', 'The average of the salaries', 'NULL for the top row', 'B', 'ROW_NUMBER assigns sequential integers 1, 2, 3 according to the order established by ORDER BY salary DESC.', 'ADVANCED', 3, 'MCQ', 1),
(1192, 35, 'What is the difference between RANK() and DENSE_RANK() when ties occur?', 'RANK never produces ties', 'DENSE_RANK leaves gaps after ties', 'RANK leaves gaps after ties; DENSE_RANK does not', 'They are identical functions', 'C', 'RANK skips the next numbers after a tie, while DENSE_RANK assigns consecutive numbers without gaps.', 'ADVANCED', 3, 'MCQ', 1),
(1193, 35, 'Which query computes a running total of salary ordered by id?', 'SELECT id, salary, SUM(salary) AS rt FROM employees ORDER BY id;', 'SELECT id, salary, SUM(salary) OVER (PARTITION BY id) FROM employees;', 'SELECT id, salary, SUM(salary) FROM employees GROUP BY id;', 'SELECT id, salary, SUM(salary) OVER (ORDER BY id) AS running_total FROM employees;', 'D', 'The window function SUM(salary) OVER (ORDER BY id) cumulatively adds each row''s salary in id order.', 'ADVANCED', 3, 'MCQ', 1),
(1194, 35, 'employees: (1,''Ann'',5000,d1),(2,''Bob'',6000,d1),(3,''Cid'',7000,d2),(4,''Dee'',8000,d2). What value does SUM(salary) OVER (PARTITION BY dept_id) return for row 1?', '11000', '15000', '5000', '26000', 'A', 'The partition for d1 contains Ann and Bob with salaries 5000 and 6000, whose sum is 11000.', 'ADVANCED', 3, 'MCQ', 1),
(1195, 35, 'What is the key difference between an aggregate function and a window function?', 'Window functions collapse many rows into one', 'Aggregates collapse rows into one; window functions compute a value per row without collapsing', 'They are identical in behaviour', 'Aggregates cannot be used with GROUP BY', 'B', 'An aggregate like SUM reduces the group to one row, while a window function computes a value for each row while keeping all rows.', 'ADVANCED', 3, 'MCQ', 1),
(1196, 35, 'Which query returns the top 2 salaries in each department using ROW_NUMBER?', 'SELECT * FROM employees WHERE ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) <= 2;', 'SELECT TOP 2 FROM employees GROUP BY dept_id;', 'SELECT * FROM (SELECT e.*, ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rn FROM employees e) t WHERE rn <= 2;', 'SELECT * FROM employees ORDER BY salary DESC LIMIT 2;', 'C', 'The window function must be computed in a subquery because window functions cannot be referenced directly in WHERE.', 'ADVANCED', 3, 'MCQ', 1),
(1197, 35, 'Which query returns the departments whose total salary exceeds 100000?', 'SELECT dept_id FROM employees WHERE SUM(salary) > 100000 GROUP BY dept_id;', 'SELECT dept_id, SUM(salary) FROM employees WHERE SUM(salary) > 100000;', 'SELECT dept_id FROM employees GROUP BY dept_id WHERE SUM(salary) > 100000;', 'SELECT dept_id, SUM(salary) FROM employees GROUP BY dept_id HAVING SUM(salary) > 100000;', 'D', 'HAVING SUM(salary) > 100000 filters the grouped departments based on the computed total salary.', 'ADVANCED', 3, 'MCQ', 1),
(1198, 35, 'What does GROUP BY dept_id WITH ROLLUP add to the result set?', 'A grand-total row for the whole group', 'A row for every single employee', 'It deletes all NULL rows', 'It has no effect on the result', 'A', 'WITH ROLLUP appends extra summary rows, including a grand-total row that aggregates across all groups.', 'ADVANCED', 3, 'MCQ', 1),
(1199, 35, 'Which query computes a three-row moving average of salary ordered by id?', 'SELECT id, AVG(salary) OVER (ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) FROM employees;', 'SELECT id, AVG(salary) OVER (ORDER BY id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) AS mov_avg FROM employees;', 'SELECT id, AVG(salary) FROM employees GROUP BY id;', 'SELECT id, SUM(salary) OVER () FROM employees;', 'B', 'The frame from 1 PRECEDING to 1 FOLLOWING includes the current row plus one before and one after, averaging three rows.', 'ADVANCED', 3, 'MCQ', 1),
(1200, 35, 'Why must a window function in the SELECT list be placed inside a subquery if you want to filter on its result?', 'Window functions cannot be computed at all', 'Subqueries are always required for aggregation', 'GROUP BY must always be used first', 'Window functions are evaluated after WHERE, so you cannot reference them directly in WHERE', 'D', 'Since window functions are computed after WHERE filtering, their results can only be used in outer filters, requiring a subquery.', 'ADVANCED', 3, 'MCQ', 1),
(1201, 36, 'Which MySQL data type is used to store whole numbers?', 'INT', 'VARCHAR', 'DATETIME', 'DECIMAL', 'A', 'INT is the numeric data type that stores whole (integer) numbers, while VARCHAR, DATETIME and DECIMAL are not integer types.', 'BEGINNER', 1, 'MCQ', 1),
(1202, 36, 'Which data type stores variable-length character strings in MySQL?', 'CHAR', 'VARCHAR', 'TEXT FIXED', 'BLOB', 'B', 'VARCHAR stores variable-length character data and only uses as much storage as the string actually needs.', 'BEGINNER', 1, 'MCQ', 1),
(1203, 36, 'What is the default storage engine for MySQL tables in modern versions (5.5 and later)?', 'MyISAM', 'MEMORY', 'InnoDB', 'ARCHIVE', 'C', 'InnoDB became the default storage engine in MySQL 5.5 and offers transactions and row-level locking.', 'BEGINNER', 1, 'MCQ', 1),
(1204, 36, 'What does AUTO_INCREMENT do to a column?', 'It stores only dates', 'It compresses the column', 'It restricts values to even numbers', 'It automatically generates a unique integer for each new row', 'D', 'AUTO_INCREMENT assigns a sequential unique integer automatically when no explicit value is provided for the column.', 'BEGINNER', 1, 'MCQ', 1),
(1205, 36, 'Which data type is best for a fixed-length character field such as a 10-character code?', 'VARCHAR', 'CHAR', 'TEXT', 'ENUM', 'B', 'CHAR is a fixed-length type, so a CHAR(10) column always reserves 10 characters regardless of the stored value.', 'BEGINNER', 1, 'MCQ', 1),
(1206, 36, 'Which modifier prevents a numeric column from accepting negative values?', 'SIGNED', 'UNSIGNED', 'ZEROFILL', 'FIXED', 'B', 'UNSIGNED tells MySQL that the column may only hold non-negative numbers, which also doubles the upper positive range.', 'BEGINNER', 1, 'MCQ', 1),
(1207, 36, 'Which data type stores only the date portion with no time component?', 'DATETIME', 'TIME', 'DATE', 'TIMESTAMP', 'C', 'DATE stores values such as ''2026-08-07'' and contains neither a time-of-day nor a timezone component.', 'BEGINNER', 1, 'MCQ', 1),
(1208, 36, 'What does DECIMAL(10,2) represent in a column definition?', 'Ten integer digits and two decimal digits', 'Ten decimal digits and two integer digits', 'A 10-byte binary string', 'Ten characters with two leading spaces', 'A', 'DECIMAL(10,2) means the column can store up to 10 total digits with exactly 2 digits after the decimal point.', 'BEGINNER', 1, 'MCQ', 1),
(1209, 36, 'Which clause in a CREATE TABLE statement names the column that becomes the primary key?', 'CONSTRAINT', 'KEY', 'FOREIGN KEY', 'PRIMARY KEY', 'D', 'PRIMARY KEY is the clause that designates one or more columns as the unique identifier for each row.', 'BEGINNER', 1, 'MCQ', 1),
(1210, 36, 'Which data type stores both date and time values such as ''2026-08-07 14:30:00''?', 'DATETIME', 'DATE', 'TIME', 'YEAR', 'A', 'DATETIME holds both a calendar date and a time of day, making it suitable for event timestamps without timezone conversion.', 'BEGINNER', 1, 'MCQ', 1),
(1211, 36, 'What is the main difference between CHAR(10) and VARCHAR(10) in terms of storage?', 'VARCHAR stores data in binary format', 'CHAR pads values with spaces to a fixed length while VARCHAR stores only the actual length', 'CHAR can store up to 10 megabytes', 'VARCHAR cannot be part of an index', 'B', 'CHAR reserves the full declared width and pads shorter values with trailing spaces, while VARCHAR uses only the bytes actually needed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1212, 36, 'Which SQL statement would you use to add a new column to an existing table?', 'CREATE TABLE', 'MODIFY COLUMN', 'ALTER TABLE', 'CHANGE TABLE', 'C', 'ALTER TABLE is the statement that changes an existing table structure, for example adding, dropping or modifying columns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1213, 36, 'Why does INT UNSIGNED allow a larger maximum positive value than INT SIGNED?', 'It stores data in fewer bytes', 'It uses two bytes less overhead', 'It drops the sign bit, so the freed bit is available for a larger magnitude', 'It uses compressed arithmetic', 'C', 'Because the sign bit no longer has to encode a plus or minus, an unsigned integer can represent roughly twice the positive range of a signed one.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1214, 36, 'How does TIMESTAMP differ from DATETIME regarding time zones?', 'TIMESTAMP is converted from and to UTC based on the session time zone, while DATETIME stores the literal value', 'TIMESTAMP ignores time entirely', 'DATETIME is always stored in UTC', 'TIMESTAMP can only store years up to 1999', 'A', 'TIMESTAMP values are stored internally in UTC and converted to the session time zone on retrieval, whereas DATETIME keeps whatever value was inserted.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1215, 36, 'Which of these is a valid reason to use TEXT instead of VARCHAR?', 'TEXT columns are always faster', 'The content may exceed the VARCHAR limit of 65,535 bytes', 'VARCHAR cannot store letters', 'TEXT is the only type that supports indexing', 'B', 'VARCHAR values are limited to 65,535 bytes in total row context, while TEXT (TINYTEXT, TEXT, MEDIUMTEXT, LONGTEXT) supports larger payloads.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1216, 36, 'What does an ENUM column do in MySQL?', 'It stores binary large objects', 'It lets the column take only one of a predefined list of string values', 'It automatically encrypts data', 'It generates random numbers', 'B', 'ENUM restricts a column to a specific set of allowed string values, and any attempt to store an unlisted value is rejected or ignored depending on SQL mode.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1217, 36, 'How do you create a table whose primary key is composed of two columns?', 'Add a PRIMARY KEY constraint listing both column names', 'Use two AUTO_INCREMENT columns', 'Make the table use the MEMORY engine', 'Define a separate table for the key', 'A', 'A composite primary key is declared with a table-level constraint such as PRIMARY KEY (col1, col2) and requires that the combination of values is unique.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1218, 36, 'Which numeric type should you choose for accurate monetary calculations?', 'FLOAT', 'DOUBLE', 'DECIMAL', 'INT', 'C', 'DECIMAL is an exact fixed-point type, so it avoids the rounding errors that binary floating-point types such as FLOAT and DOUBLE introduce.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1219, 36, 'How do you set a DATETIME column to record the current time when a row is inserted?', 'Use DEFAULT CURRENT_TIMESTAMP', 'Declare it UNSIGNED', 'Give it a CHECK constraint', 'Set the storage engine to CSV', 'A', 'DEFAULT CURRENT_TIMESTAMP fills the column with the current timestamp at insert time automatically, and can be combined with ON UPDATE for changes.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1220, 36, 'What happens to an existing table when you run ALTER TABLE ... DROP COLUMN col_name?', 'The column and all of its data are removed from the table', 'Only the column definition is kept', 'The table is renamed', 'The column is moved to another table', 'A', 'DROP COLUMN permanently removes the column and its stored values from the table, so any data in that column is lost.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1221, 36, 'Which storage engine is appropriate for a table that needs ACID transactions and foreign key enforcement?', 'MyISAM', 'InnoDB', 'MEMORY', 'MERGE', 'B', 'InnoDB supports transactions, row-level locking and foreign keys, whereas MyISAM does not provide ACID guarantees or enforce referential integrity.', 'ADVANCED', 3, 'MCQ', 1),
(1222, 36, 'Why is MyISAM sometimes chosen over InnoDB for read-heavy analytics tables?', 'It enforces foreign keys better', 'It uses row-level locking for writes', 'It is generally faster for full-table scans and offers compressed read-only tables', 'It supports transactions', 'C', 'MyISAM''s table-level locking and compact storage can be faster for bulk reads and static data, at the cost of losing transactions and foreign keys.', 'ADVANCED', 3, 'MCQ', 1),
(1223, 36, 'What is the significance of the display width in INT(11) in older MySQL versions?', 'It limits the value to 11 digits', 'It is the number of bytes stored', 'It only affects display padding and does not restrict the stored value''s range', 'It selects the floating-point format', 'C', 'The (11) in INT(11) was only a display width hint used with ZEROFILL and never limited the numeric range, and it is deprecated in MySQL 8.0.', 'ADVANCED', 3, 'MCQ', 1),
(1224, 36, 'Why can using VARCHAR(200) instead of a smaller size help performance in a very wide table?', 'VARCHAR consumes no storage at all', 'Wide variable columns make rows larger and can push row size over limits or waste space in buffers', 'VARCHAR is a native binary type', 'Larger sizes enable compression automatically', 'B', 'Excessive VARCHAR lengths can inflate row size, consume more memory in the buffer pool and reduce how many rows fit in an index page.', 'ADVANCED', 3, 'MCQ', 1),
(1225, 36, 'What happens when you insert a value that exceeds an UNSIGNED INT maximum in strict SQL mode?', 'The value is silently truncated to the maximum', 'MySQL rounds to the nearest multiple of ten', 'An error is raised and the statement fails', 'The column is automatically changed to BIGINT', 'C', 'In strict mode, out-of-range numeric values cause an error rather than being clamped, preventing silent data corruption.', 'ADVANCED', 3, 'MCQ', 1),
(1226, 36, 'Which MySQL data type is designed to store and query JSON documents directly?', 'BLOB', 'JSON', 'XML', 'VARBINARY', 'B', 'The JSON type validates stored JSON, stores it in a binary format and supports JSON path queries and indexes on generated columns.', 'ADVANCED', 3, 'MCQ', 1),
(1227, 36, 'What is a generated (virtual) column in MySQL?', 'A column stored only on disk in a separate file', 'A column whose value is computed from an expression and may be indexed', 'A column that randomly changes on each read', 'A synonym for an ENUM column', 'B', 'Generated columns compute their value from a deterministic expression, and VIRTUAL generated columns can be indexed to speed up JSON and derived-value lookups.', 'ADVANCED', 3, 'MCQ', 1),
(1228, 36, 'Why should a VARCHAR column that stores text with emojis use the utf8mb4 character set?', 'utf8mb4 is the only character set that exists', 'It is faster than latin1 for numbers', 'utf8mb4 supports supplementary characters including emojis, which plain utf8 (utf8mb3) cannot represent', 'utf8mb4 halves the row size', 'C', 'Emoji characters lie outside the Basic Multilingual Plane, so they require the 4-byte utf8mb4 encoding instead of the 3-byte utf8mb3.', 'ADVANCED', 3, 'MCQ', 1),
(1229, 36, 'In InnoDB, what is the practical benefit of defining the primary key explicitly instead of relying on an implicit one?', 'Explicit primary keys give the clustered index a logical order, improving point lookups and range scans', 'Explicit primary keys disable the buffer pool', 'Explicit primary keys allow table-level locking', 'Explicit primary keys are required to use MyISAM', 'A', 'InnoDB clusters data by the primary key, so an explicit, small and stable primary key yields efficient B-tree access and avoids hidden overhead.', 'ADVANCED', 3, 'MCQ', 1),
(1230, 36, 'Why might a very long VARCHAR column exceed the maximum row size of a table?', 'VARCHAR always counts its full declared length against the 65,535-byte row limit', 'VARCHAR is stored in a separate table automatically', 'VARCHAR cannot exceed 100 bytes', 'VARCHAR requires two columns per value', 'A', 'The declared VARCHAR length contributes to the row size limit even if the actual stored strings are short, so declaring several huge VARCHAR columns can make the table uncreatable.', 'ADVANCED', 3, 'MCQ', 1),
(1231, 37, 'Which keyword retrieves every column from a table?', 'SELECT *', 'SHOW ALL', 'GET *', 'USE *', 'A', 'The asterisk in SELECT * is a wildcard that returns all columns of the selected table.', 'BEGINNER', 1, 'MCQ', 1),
(1232, 37, 'Which clause filters which rows a query returns?', 'GROUP BY', 'WHERE', 'ORDER BY', 'HAVING', 'B', 'WHERE evaluates a condition for each row and only rows matching the condition are included in the result.', 'BEGINNER', 1, 'MCQ', 1),
(1233, 37, 'Which constraint guarantees that a column value is both unique and never NULL?', 'DEFAULT', 'CHECK', 'PRIMARY KEY', 'INDEX', 'C', 'A PRIMARY KEY enforces uniqueness and implicitly disallows NULL values, uniquely identifying each row.', 'BEGINNER', 1, 'MCQ', 1),
(1234, 37, 'Which keyword sorts the rows of a result set?', 'SORT', 'ORDER BY', 'GROUP BY', 'SORT BY', 'B', 'ORDER BY sorts the returned rows by one or more columns, ascending by default.', 'BEGINNER', 1, 'MCQ', 1),
(1235, 37, 'What does the NOT NULL constraint on a column prevent?', 'Duplicate values', 'Values larger than 255', 'Inserting a row without a value for that column', 'Indexed access', 'C', 'NOT NULL rejects any insert or update that would leave the column without a value, so the column must always contain data.', 'BEGINNER', 1, 'MCQ', 1),
(1236, 37, 'What is a foreign key?', 'A key that encrypts the table', 'A column that links a row to a row in another table to enforce referential integrity', 'A key that compresses the data', 'A synonym for the primary key', 'B', 'A foreign key references the primary key of another table, ensuring that values in the column match an existing row in that table.', 'BEGINNER', 1, 'MCQ', 1),
(1237, 37, 'Which clause groups rows that share the same values of one or more columns?', 'GROUP BY', 'WHERE', 'LIMIT', 'JOIN', 'A', 'GROUP BY collapses rows with equal column values into groups, which is commonly used with aggregate functions such as COUNT.', 'BEGINNER', 1, 'MCQ', 1),
(1238, 37, 'What does LIMIT 5 do in a SELECT statement?', 'Returns at most 5 rows', 'Returns rows 5 through 10', 'Sorts 5 rows', 'Deletes 5 rows', 'A', 'LIMIT restricts the number of rows returned by the query to the specified count, here a maximum of 5.', 'BEGINNER', 1, 'MCQ', 1),
(1239, 37, 'Which operator lets you test whether a value is present in a given list?', 'BETWEEN', 'IN', 'LIKE', 'EXISTS', 'B', 'IN checks membership in a list, for example WHERE status IN (''active'',''pending'').', 'BEGINNER', 1, 'MCQ', 1),
(1240, 37, 'Which keyword removes a whole table including its structure from the database?', 'DELETE FROM', 'DROP TABLE', 'TRUNCATE TABLE', 'REMOVE TABLE', 'B', 'DROP TABLE deletes the table definition and all of its data, while DELETE and TRUNCATE only remove the rows.', 'BEGINNER', 1, 'MCQ', 1),
(1241, 37, 'When is a DEFAULT constraint applied to a column?', 'When the table is created only', 'When no explicit value is supplied for that column in an INSERT', 'When the column is indexed', 'When a NULL is explicitly inserted', 'B', 'The DEFAULT value is used automatically whenever an INSERT does not provide a value for the column.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1242, 37, 'What is the difference between WHERE and HAVING in a grouped query?', 'They are interchangeable', 'WHERE filters individual rows before grouping, while HAVING filters groups after grouping', 'HAVING runs before WHERE', 'WHERE only works with indexed columns', 'B', 'WHERE discards rows before GROUP BY runs, whereas HAVING filters the resulting groups, which is why it can reference aggregate results.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1243, 37, 'What does ON DELETE CASCADE do for a foreign key?', 'It prevents deletion of the parent row', 'It automatically deletes the referencing child rows when the parent row is deleted', 'It renames the parent table', 'It locks the parent table', 'B', 'ON DELETE CASCADE propagates a parent deletion to child rows, deleting them automatically so no orphaned references remain.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1244, 37, 'Which statement correctly creates a table with a two-column composite primary key?', 'CREATE TABLE t (a INT, b INT, PRIMARY KEY (a,b));', 'CREATE TABLE t (a INT, b INT) WITH TWO KEYS;', 'CREATE TABLE t (a INT PRIMARY KEY, b INT PRIMARY KEY);', 'CREATE TABLE t (a INT, b INT, KEY b);', 'A', 'A table-level PRIMARY KEY (a, b) constraint defines the pair of columns as the composite key, and only the whole pair must be unique.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1245, 37, 'What is the effect of a UNIQUE constraint on a column that also allows NULLs?', 'NULLs are not allowed at all', 'It rejects all values', 'Multiple rows may hold NULL, but every non-NULL value must be distinct', 'It turns the column into a primary key', 'C', 'A UNIQUE constraint permits several NULL values (in MySQL) while guaranteeing that all concrete non-NULL values are unique.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1246, 37, 'Which scenario would benefit from a CHECK constraint?', 'Restricting a rating column to values between 1 and 5', 'Speeding up a SELECT with ORDER BY', 'Auto-generating primary keys', 'Storing binary images', 'A', 'CHECK enforces a boolean condition on column values, such as rating BETWEEN 1 AND 5, and rejects inserts that violate it in MySQL 8.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1247, 37, 'How would you return the three highest-priced products from the products table?', 'SELECT * FROM products ORDER BY price DESC LIMIT 3;', 'SELECT * FROM products LIMIT 3 ORDER BY price;', 'SELECT * FROM products WHERE MAX(price);', 'SELECT * FROM products GROUP BY price LIMIT 3;', 'A', 'ORDER BY price DESC sorts by price from highest to lowest and LIMIT 3 keeps only the top three rows.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1248, 37, 'What is the difference between DELETE FROM t and TRUNCATE TABLE t?', 'DELETE removes the table structure, TRUNCATE keeps it', 'TRUNCATE cannot be used on tables', 'DELETE deletes rows one by one and fires triggers, while TRUNCATE quickly removes all rows and resets AUTO_INCREMENT', 'They are identical in every way', 'C', 'DELETE processes each row (running triggers) and can be rolled back, whereas TRUNCATE drops and recreates the storage quickly and resets the auto-increment counter.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1249, 37, 'Which query returns each department name together with the number of employees in it?', 'SELECT dept, COUNT(*) FROM emp GROUP BY dept;', 'SELECT dept, COUNT(*) FROM emp WHERE COUNT(*) > 0;', 'SELECT dept, SUM(emp) FROM emp;', 'SELECT COUNT(dept) FROM emp;', 'A', 'GROUP BY dept groups employees per department and COUNT(*) counts the rows in each group, giving the employee total per department.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1250, 37, 'Why is it a good idea to define an index on a foreign key column?', 'Indexes are required for every column', 'It speeds up the lookups and join operations that use the foreign key', 'It prevents NULLs in the column', 'It automatically enforces the constraint', 'B', 'The foreign key is used to look up matching rows in the parent table, and an index on it avoids full table scans during joins and constraint checks.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1251, 37, 'You run INSERT INTO t VALUES (1,2) and the primary key 1 already exists. Which statement updates the existing row instead of failing?', 'INSERT OR REPLACE', 'INSERT INTO t VALUES (1,2) ON DUPLICATE KEY UPDATE b = 2;', 'UPDATE ... INTO t', 'MERGE VALUES (1,2);', 'B', 'INSERT ... ON DUPLICATE KEY UPDATE detects the primary key or unique constraint conflict and performs the specified update instead of raising an error.', 'ADVANCED', 3, 'MCQ', 1),
(1252, 37, 'In MySQL 8, where does CHECK constraint validation actually occur for INSERT and UPDATE statements?', 'In the client application', 'In the storage engine only', 'In the MySQL server when the statement is executed', 'During index defragmentation', 'C', 'MySQL 8.0.16 and later enforce CHECK constraints in the server engine layer for both InnoDB and MyISAM, rejecting rows that fail the condition.', 'ADVANCED', 3, 'MCQ', 1),
(1253, 37, 'Which query lists departments having more than 50 employees?', 'SELECT dept, COUNT(*) FROM emp WHERE COUNT(*) > 50 GROUP BY dept;', 'SELECT dept FROM emp GROUP BY dept HAVING COUNT(*) > 50;', 'SELECT dept FROM emp HAVING dept > 50;', 'SELECT dept FROM emp WHERE SUM(*) > 50;', 'B', 'HAVING filters groups after aggregation, so COUNT(*) > 50 correctly selects departments whose employee count exceeds 50.', 'ADVANCED', 3, 'MCQ', 1),
(1254, 37, 'What is the effect of ON UPDATE CASCADE on a child table when a parent key value changes?', 'The child rows are deleted', 'The child foreign key values automatically change to match the new parent value', 'The update is rejected', 'The child table is locked forever', 'B', 'ON UPDATE CASCADE propagates the changed parent key value to every referencing child row, keeping referential integrity intact.', 'ADVANCED', 3, 'MCQ', 1),
(1255, 37, 'Which statement is valid for deleting rows from two related tables in a single DELETE statement?', 'DELETE a, b FROM a JOIN b ON a.id = b.aid WHERE a.date < ''2020-01-01'';', 'DELETE FROM a AND b WHERE date < ''2020-01-01'';', 'TRUNCATE a, b WHERE a.id = b.aid;', 'DELETE a.id, b.id FROM a;', 'A', 'MySQL supports multi-table DELETE with a join, letting one statement remove matching rows from both tables using the join condition.', 'ADVANCED', 3, 'MCQ', 1),
(1256, 37, 'A self-referencing foreign key is used to model which common scenario?', 'A table storing employee managers where the manager is also an employee in the same table', 'Encrypting passwords', 'Full-text search on documents', 'Storing temporal versioning', 'A', 'Self-referencing foreign keys point back at the same table''s primary key, which is the standard way to model hierarchical data such as employee-manager relations.', 'ADVANCED', 3, 'MCQ', 1),
(1257, 37, 'Why might an index that exactly matches the WHERE clause columns still not be used by the optimizer?', 'Indexes can never be used', 'Statistics may be outdated, or the optimizer estimates that a full scan is cheaper for the row count', 'WHERE clauses disable indexes entirely', 'Indexes only work on DATE columns', 'B', 'The optimizer relies on table statistics and cost estimates, so it may skip an index when a scan is projected to be cheaper or when stats are stale.', 'ADVANCED', 3, 'MCQ', 1),
(1258, 37, 'What problem can a foreign key constraint with NO ACTION (the default RESTRICT behavior) cause?', 'It allows orphaned rows', 'It blocks deleting a parent row that still has referencing children, which may require deleting children first', 'It drops the parent row silently', 'It changes column data types automatically', 'B', 'RESTRICT/NO ACTION rejects the parent deletion when referencing rows exist, so you must remove or update the child rows before deleting the parent.', 'ADVANCED', 3, 'MCQ', 1),
(1259, 37, 'Which query pattern correctly uses a correlated subquery to find employees earning more than their department average?', 'SELECT * FROM emp e WHERE salary > (SELECT AVG(salary) FROM emp d WHERE d.dept = e.dept);', 'SELECT * FROM emp WHERE salary > AVG(salary);', 'SELECT * FROM emp GROUP BY dept HAVING salary > AVG(salary);', 'SELECT dept FROM emp WHERE dept > AVG(salary);', 'A', 'The correlated subquery recomputes the average for each employee''s own department, so the outer WHERE compares against the right baseline.', 'ADVANCED', 3, 'MCQ', 1),
(1260, 37, 'You need a column that auto-fills with the string ''NEW'' until an explicit value arrives. Which definition achieves this?', 'status VARCHAR(10) DEFAULT ''NEW''', 'status VARCHAR(10) NOT NULL AUTO', 'status VARCHAR(10) WITH VALUE ''NEW''', 'status VARCHAR(10) CHECK status = ''NEW''', 'A', 'DEFAULT ''NEW'' supplies the value for rows that omit it, while an explicit insert value overrides the default.', 'ADVANCED', 3, 'MCQ', 1),
(1261, 38, 'Which statement is used to create a stored procedure in MySQL?', 'CREATE PROCEDURE', 'MAKE PROCEDURE', 'DEFINE FUNCTION', 'CREATE ROUTINE', 'A', 'CREATE PROCEDURE defines a new stored procedure with a name, optional parameters and a body.', 'BEGINNER', 1, 'MCQ', 1),
(1262, 38, 'Why is DELIMITER used when creating a stored procedure in the mysql client?', 'To change the statement delimiter so semicolons inside the procedure body are not treated as end-of-statement', 'To encrypt the procedure', 'To limit the number of parameters', 'To name the database', 'A', 'Because the procedure body contains semicolons, the client delimiter is temporarily changed so the whole body is sent as one statement.', 'BEGINNER', 1, 'MCQ', 1),
(1263, 38, 'Which parameter mode passes a value INTO a stored procedure but cannot change it for the caller?', 'IN', 'OUT', 'INOUT', 'VAR', 'A', 'IN parameters are read-only inside the procedure, and changes to them are not visible to the caller.', 'BEGINNER', 1, 'MCQ', 1),
(1264, 38, 'Which keyword makes a stored function return a value?', 'EXIT', 'RETURN', 'OUTPUT', 'SELECT', 'B', 'RETURN immediately returns a scalar value from a stored function and is required in every function.', 'BEGINNER', 1, 'MCQ', 1),
(1265, 38, 'How do you call (execute) a stored procedure named sp_demo?', 'RUN sp_demo', 'CALL sp_demo();', 'EXECUTE ONLY sp_demo', 'SELECT sp_demo();', 'B', 'CALL is the statement that invokes a stored procedure and runs its body.', 'BEGINNER', 1, 'MCQ', 1),
(1266, 38, 'What is the main difference between a stored procedure and a stored function?', 'Functions return a value and are used inside expressions, while procedures may not return a value and are called with CALL', 'Procedures are faster than functions', 'Functions cannot have a body', 'There is no difference', 'A', 'Stored functions return a single value and can appear in SELECT expressions, whereas procedures are invoked with CALL and need not return a value.', 'BEGINNER', 1, 'MCQ', 1),
(1267, 38, 'Which construct wraps the executable statements of a stored routine body?', 'BEGIN ... END', 'START ... STOP', 'IF ... FI', 'LOOP ... ENDLOOP', 'A', 'The body of a stored routine is a compound statement delimited by BEGIN and END.', 'BEGINNER', 1, 'MCQ', 1),
(1268, 38, 'What does the command DELIMITER $$ do in the mysql client?', 'It changes the delimiter used to end statements to $$', 'It doubles the precision of numbers', 'It stops the server', 'It creates two databases', 'A', 'DELIMITER $$ tells the client to treat $$ as the end of a statement, allowing semicolons inside a routine body.', 'BEGINNER', 1, 'MCQ', 1),
(1269, 38, 'Which keyword declares a local variable inside a stored procedure?', 'VAR', 'DECLARE', 'CREATE VARIABLE', 'SET VAR', 'B', 'DECLARE introduces local variables at the start of a BEGIN ... END block, optionally with a default value.', 'BEGINNER', 1, 'MCQ', 1),
(1270, 38, 'Which SQL command removes a stored function from the database?', 'DELETE FUNCTION', 'REMOVE FUNCTION', 'DROP FUNCTION', 'KILL FUNCTION', 'C', 'DROP FUNCTION permanently deletes a stored function from the database, using its name and signature.', 'BEGINNER', 1, 'MCQ', 1),
(1271, 38, 'In a stored procedure, what is the purpose of an OUT parameter?', 'It accepts input only', 'It returns a value to the caller through the parameter rather than through a result set', 'It holds the loop counter', 'It names the procedure''s schema', 'B', 'An OUT parameter lets a procedure pass a result back to the caller in the variable supplied at CALL time.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1272, 38, 'Which of these correctly calls a stored function named fn_tax in a SELECT?', 'CALL fn_tax(100);', 'SELECT fn_tax(100);', 'RUN fn_tax(100);', 'EXEC fn_tax(100);', 'B', 'Stored functions are invoked like built-in functions inside expressions, so SELECT fn_tax(100) returns the computed value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1273, 38, 'How is a local variable assigned a value inside a procedure?', 'With the SET statement', 'With the DEFAULT clause', 'With the LET keyword', 'By typing it in the body', 'A', 'SET assigns a value to a local or user variable, for example SET total = total + 1;.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1274, 38, 'Which statement correctly shows a conditional action in a stored procedure?', 'IF price > 100 THEN SET flag = 1; END IF;', 'WHEN price > 100 DO flag = 1;', 'CASE price > 100 SET flag', 'LOOP price > 100 flag = 1', 'A', 'IF ... THEN ... END IF executes the statements inside only when the boolean condition is true.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1275, 38, 'What does a cursor do inside a stored procedure?', 'It locks the whole table', 'It lets the procedure iterate row by row over a result set', 'It encrypts the result', 'It prevents all queries', 'B', 'Cursors allow row-by-row processing of a SELECT result set, usually paired with a loop and FETCH statements.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1276, 38, 'A procedure declares PROCEDURE p(IN x INT, OUT y INT). Which is true?', 'x can be modified and seen by the caller, y cannot', 'y is set inside the procedure and the caller reads it afterward', 'Both parameters are read-only', 'Neither parameter may be used', 'B', 'IN x is read-only input, while OUT y is written inside the procedure and its value is returned to the caller.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1277, 38, 'What happens if you call a stored procedure that does not exist?', 'MySQL silently ignores it', 'MySQL creates it automatically', 'MySQL raises an error such as ''PROCEDURE does not exist''', 'The database is deleted', 'C', 'Invoking an undefined procedure name causes an error because MySQL cannot find a matching routine in the database.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1278, 38, 'Which pair of statements is used together to end a stored procedure definition cleanly in the client?', 'DROP and CREATE', 'DELIMITER $$ ... DELIMITER ;', 'BEGIN and END LOOP', 'START and COMMIT', 'B', 'The delimiter is changed before the CREATE so the body can contain semicolons, then restored to a semicolon afterward.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1279, 38, 'What distinguishes a stored function that is marked DETERMINISTIC?', 'It always returns the same result for the same arguments', 'It runs faster than other functions', 'It cannot take parameters', 'It is automatically dropped', 'A', 'DETERMINISTIC declares that the function produces identical output for identical inputs, which the optimizer may use for caching.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1280, 38, 'How does a stored procedure return a result set such as a filtered list of rows?', 'It cannot return rows', 'By running a SELECT inside its body, whose result is sent to the caller', 'By using a RETURN statement', 'By writing to a file', 'B', 'A SELECT executed inside a procedure emits its rows to the client, allowing the procedure to behave like a parameterized query.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1281, 38, 'Which of these is the correct skeleton for fetching every row of a cursor?', 'DECLARE c CURSOR FOR ...; OPEN c; LOOP FETCH c INTO ...; ... UNTIL done END LOOP; CLOSE c;', 'FETCH ALL FROM c;', 'SELECT c;', 'OPEN c; SELECT c; CLOSE c;', 'A', 'Cursor processing requires declaring it over a query, opening it, looping with FETCH until rows run out, then closing it.', 'ADVANCED', 3, 'MCQ', 1),
(1282, 38, 'Why do cursor loops in MySQL typically declare a handler such as DECLARE CONTINUE HANDLER FOR NOT FOUND?', 'To catch syntax errors', 'To set a flag when FETCH exhausts the result set so the loop can terminate', 'To raise exceptions on purpose', 'To close the database connection', 'B', 'When FETCH finds no more rows it triggers the NOT FOUND condition, and the handler sets a flag that the loop condition checks.', 'ADVANCED', 3, 'MCQ', 1),
(1283, 38, 'Which routine attribute is appropriate for a function that computes a date difference and depends on session variables?', 'DETERMINISTIC', 'NOT DETERMINISTIC', 'ATOMIC', 'STATIC', 'B', 'A function whose output varies with session state cannot be DETERMINISTIC, so it must be declared NOT DETERMINISTIC to avoid incorrect optimization.', 'ADVANCED', 3, 'MCQ', 1),
(1284, 38, 'What is a key reason to avoid deep recursion in MySQL stored procedures?', 'MySQL has a limited recursion depth and can raise error 1428 or consume excessive stack space', 'Recursion is always faster', 'Recursion requires extra disks', 'Recursion disables transactions', 'A', 'MySQL allows recursion only if binary logging is configured correctly and limits nesting, so uncontrolled recursion fails with errors.', 'ADVANCED', 3, 'MCQ', 1),
(1285, 38, 'Which statement allows a procedure to manage a multi-step operation as one unit that can be undone?', 'START TRANSACTION; ... COMMIT; or ROLLBACK;', 'LOCK TABLES ONLY;', 'BEGIN WORK WITH LOG;', 'SAVEPOINT THE WHOLE JOB;', 'A', 'START TRANSACTION begins a transaction, and COMMIT makes it permanent while ROLLBACK undoes all changes since it began.', 'ADVANCED', 3, 'MCQ', 1),
(1286, 38, 'Which system source can you query to see which stored procedures exist and their characteristics?', 'information_schema.ROUTINES', 'mysql.users', 'performance_schema.events', 'sys.disk_usage', 'A', 'information_schema.ROUTINES stores metadata about stored procedures and functions, including type, creator and definition.', 'ADVANCED', 3, 'MCQ', 1),
(1287, 38, 'How should dynamic SQL in a stored procedure be built to avoid SQL injection?', 'Concatenate user input directly into the query string', 'Use prepared statements with placeholders and bind parameter values', 'Disable all queries', 'Store the query in a file', 'B', 'Using PREPARE with ? placeholders and EXECUTE with bound values separates code from data, preventing injection through user-supplied text.', 'ADVANCED', 3, 'MCQ', 1),
(1288, 38, 'Why might a cursor be slower than a single set-based UPDATE for transforming 100,000 rows?', 'Cursors are always faster', 'Row-by-row processing incurs per-row overhead in the client-server protocol and inside the server', 'Set-based updates are not supported', 'Cursors compress data', 'B', 'Cursors process one row at a time, generating more round trips and more internal work, whereas a single UPDATE works on the whole set in one pass.', 'ADVANCED', 3, 'MCQ', 1),
(1289, 38, 'What is the best way to validate parameters inside a procedure and abort execution on bad input?', 'Use SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''Invalid parameter'';', 'Return NULL from the procedure', 'Log to a file and continue', 'Ignore the parameter', 'A', 'SIGNAL raises a user-defined exception with a SQLSTATE and message, immediately stopping the procedure when validation fails.', 'ADVANCED', 3, 'MCQ', 1),
(1290, 38, 'A function returns a value for each employee. Where can this function legally be used?', 'Only inside other procedures', 'Anywhere an expression is allowed, such as SELECT fn(salary)', 'Only in triggers', 'Only in the mysql client', 'B', 'Stored functions can be used in expressions wherever built-in functions are allowed, including SELECT lists, WHERE and computed columns.', 'ADVANCED', 3, 'MCQ', 1),
(1291, 39, 'What is a database trigger?', 'A query that runs manually', 'A stored program that executes automatically in response to table events such as INSERT, UPDATE or DELETE', 'A type of index', 'A backup copy of a table', 'B', 'A trigger is a stored routine MySQL runs automatically when a specified DML event occurs on a table.', 'BEGINNER', 1, 'MCQ', 1),
(1292, 39, 'Which three events can fire a MySQL trigger?', 'SELECT, SHOW, DESCRIBE', 'INSERT, UPDATE, DELETE', 'CREATE, DROP, ALTER', 'LOCK, UNLOCK, COMMIT', 'B', 'MySQL triggers fire only on data-changing statements: INSERT, UPDATE and DELETE.', 'BEGINNER', 1, 'MCQ', 1),
(1293, 39, 'What does the BEFORE keyword in a trigger definition mean?', 'The trigger runs after the row is committed', 'The trigger runs before the triggering statement modifies the row', 'The trigger runs once per day', 'The trigger blocks the table', 'B', 'BEFORE triggers execute before the row is changed, allowing the trigger to modify the NEW values before they are stored.', 'BEGINNER', 1, 'MCQ', 1),
(1294, 39, 'What is a view in MySQL?', 'A stored query that appears as a virtual table', 'A copy of the data in another table', 'An index on a table', 'A backup file', 'A', 'A view is a virtual table defined by a SELECT statement; it shows the query result each time it is used.', 'BEGINNER', 1, 'MCQ', 1),
(1295, 39, 'Which statement creates a new view named emp_view?', 'CREATE VIEW emp_view AS SELECT * FROM emp;', 'MAKE VIEW emp_view;', 'NEW TABLE emp_view;', 'ADD VIEW emp_view;', 'A', 'CREATE VIEW name AS select_statement defines the view by storing the query, not the data itself.', 'BEGINNER', 1, 'MCQ', 1),
(1296, 39, 'Can a trigger be created directly on a view in MySQL?', 'Yes, always', 'No, MySQL does not support triggers on views', 'Only on materialized views', 'Only with a special flag', 'B', 'MySQL does not support triggers on views; triggers are only allowed on base tables.', 'BEGINNER', 1, 'MCQ', 1),
(1297, 39, 'Which information_schema table stores trigger metadata?', 'information_schema.TRIGGERS', 'information_schema.VIEWS', 'information_schema.TABLES', 'information_schema.INDEXES', 'A', 'information_schema.TRIGGERS contains details of every trigger, including its event, timing and definition.', 'BEGINNER', 1, 'MCQ', 1),
(1298, 39, 'In a BEFORE INSERT trigger, which keyword gives access to the values being inserted?', 'OLD', 'NEW', 'CUR', 'ROOT', 'B', 'NEW refers to the row that will be inserted, so NEW.column can be read or modified in a BEFORE INSERT trigger.', 'BEGINNER', 1, 'MCQ', 1),
(1299, 39, 'In an AFTER DELETE trigger, which keyword gives access to the row that was just removed?', 'NEW', 'OLD', 'LAST', 'REMOVED', 'B', 'OLD holds the original values of the deleted row, which are no longer available in the table itself.', 'BEGINNER', 1, 'MCQ', 1),
(1300, 39, 'Which statement removes a trigger named trg_audit from the database?', 'DELETE TRIGGER trg_audit', 'DROP TRIGGER trg_audit', 'KILL TRIGGER trg_audit', 'REMOVE TRIGGER trg_audit', 'B', 'DROP TRIGGER trg_audit permanently removes the trigger; the schema must be included if it is not the default database.', 'BEGINNER', 1, 'MCQ', 1),
(1301, 39, 'Which use case is a classic example of a BEFORE INSERT trigger?', 'Automatically setting or validating column values before the row is written', 'Speeding up SELECT queries', 'Encrypting the whole database', 'Sharding tables', 'A', 'BEFORE INSERT triggers run before storage, so they can normalize or validate data and adjust NEW values in place.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1302, 39, 'What is a typical purpose of an AFTER DELETE trigger?', 'To archive or audit the deleted row into a history table', 'To prevent the delete', 'To renumber the table', 'To create a backup index', 'A', 'AFTER DELETE fires once the row is gone, and OLD lets the trigger copy that row into an audit or archive table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1303, 39, 'Which CREATE VIEW statement is syntactically correct?', 'CREATE VIEW high_sal AS SELECT name, salary FROM emp WHERE salary > 50000;', 'CREATE VIEW high_sal OF emp;', 'VIEW high_sal = SELECT * FROM emp;', 'MAKE VIEW high_sal FROM emp;', 'A', 'The view definition must follow CREATE VIEW name AS with a valid SELECT statement.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1304, 39, 'When you UPDATE a row in a table and the UPDATE trigger fires, what does OLD represent?', 'The new values after the update', 'The values of the row before the update was applied', 'The row from another table', 'Nothing at all', 'B', 'In an UPDATE trigger, OLD contains the row as it existed before the change, while NEW contains the updated values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1305, 39, 'Which type of trigger body can contain multiple statements?', 'A single-statement body only', 'A compound BEGIN ... END block with several statements', 'Only stored functions', 'Only SELECT statements', 'B', 'Writing the trigger body as a BEGIN ... END compound block lets you include several statements, so DELIMITER changes are often needed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1306, 39, 'What is one limitation of MySQL triggers regarding tables?', 'They can run on any table including views', 'Triggers cannot be defined on temporary tables', 'They run on every event type', 'They ignore the NEW row', 'B', 'MySQL forbids triggers on temporary tables, and views are likewise not allowed, so only persistent base tables can carry triggers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1307, 39, 'How do you name a trigger that fires before a delete on table orders?', 'CREATE TRIGGER trg_orders_bd BEFORE DELETE ON orders', 'CREATE TRIGGER orders DELETE BEFORE', 'TRIGGER ON orders BEFORE DELETE', 'MAKE TRIGGER orders_bd', 'A', 'The syntax CREATE TRIGGER name BEFORE DELETE ON orders requires the timing, the event and the target table in that order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1308, 39, 'Which of these correctly retrieves the list of views in a database?', 'SELECT * FROM information_schema.VIEWS WHERE TABLE_SCHEMA = ''mydb'';', 'SHOW TABLES WHERE TYPE = ''view'';', 'SELECT * FROM mysql.views;', 'DESCRIBE VIEW mydb;', 'A', 'information_schema.VIEWS lists every view along with its defining query, filtered by schema name.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1309, 39, 'What does the trigger definition UPDATE OF column_name do in a BEFORE UPDATE trigger?', 'It updates the column automatically', 'It restricts the trigger to fire only when that specific column changes', 'It drops the column', 'It renames the column', 'B', 'The UPDATE OF clause limits the trigger to fire only when the named column is included in the UPDATE statement, avoiding wasted work.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1310, 39, 'Which statement logs every change to an audit table from within an AFTER UPDATE trigger?', 'INSERT INTO audit_log (old_val, new_val) VALUES (OLD.x, NEW.x);', 'SELECT old, new FROM audit;', 'UPDATE audit SET x = NEW.x;', 'COPY OLD INTO audit;', 'A', 'An INSERT statement inside the trigger copies OLD and NEW values into the audit table, recording exactly what changed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1311, 39, 'What does WITH CHECK OPTION do on a view?', 'It makes the view read-only', 'It prevents INSERT and UPDATE statements that would make rows disappear from the view''s result set', 'It encrypts the view', 'It caches the view''s data', 'B', 'WITH CHECK OPTION enforces the view''s WHERE condition on inserts and updates, rejecting changes that would place a row outside the view.', 'ADVANCED', 3, 'MCQ', 1),
(1312, 39, 'What happens if a BEFORE UPDATE trigger sets a value and then another part of the statement changes the same column?', 'The later change wins because the trigger runs first and its NEW values are used for the final write', 'The trigger is skipped', 'Both values are concatenated', 'MySQL raises a deadlock error', 'A', 'BEFORE triggers run before the write, and any adjustments to NEW are what actually get stored when the row is finally written.', 'ADVANCED', 3, 'MCQ', 1),
(1313, 39, 'Why is it risky to create triggers that perform large amounts of work?', 'Triggers run on the original event thread, so heavy work increases the statement''s latency and can slow writes', 'Triggers never run', 'Large triggers are rejected', 'Triggers compress the data', 'A', 'Trigger bodies execute synchronously inside the triggering statement, so expensive operations inside them add directly to every affected write''s cost.', 'ADVANCED', 3, 'MCQ', 1),
(1314, 39, 'Which recursive or cascading behavior does MySQL prevent in triggers?', 'A trigger on table A that inserts into table B, which has its own triggers', 'A trigger that references OLD in an INSERT trigger', 'A trigger modifying the same table it is defined on, which could cause infinite recursion', 'A trigger using stored functions', 'C', 'A trigger that performs DML on its own table can fire itself again, so MySQL rejects such self-modifying triggers to avoid infinite recursion.', 'ADVANCED', 3, 'MCQ', 1),
(1315, 39, 'In a BEFORE INSERT trigger, how do you reject a bad row before it is stored?', 'By returning NULL', 'Use SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''Invalid row'';', 'By deleting the row', 'By closing the connection', 'B', 'SIGNAL raises a user error that aborts the entire insert, so the offending row is never stored.', 'ADVANCED', 3, 'MCQ', 1),
(1316, 39, 'Which view characteristic makes it updatable through the view itself?', 'The view joins several tables', 'The view maps each view row to a single base-table row with no aggregates or DISTINCT', 'The view uses GROUP BY', 'The view uses UNION', 'B', 'A view is updatable when it is derived from one base table without aggregation, DISTINCT, GROUP BY or other constructs that hide the underlying row.', 'ADVANCED', 3, 'MCQ', 1),
(1317, 39, 'How do you obtain the exact SQL text that defined an existing trigger?', 'SELECT TRIGGER_BODY FROM information_schema.TRIGGERS;', 'SHOW CREATE TRIGGER trigger_name;', 'DESCRIBE TRIGGER trigger_name;', 'EXPLAIN TRIGGER trigger_name;', 'B', 'SHOW CREATE TRIGGER prints the complete CREATE TRIGGER statement for a given trigger, mirroring its stored definition.', 'ADVANCED', 3, 'MCQ', 1),
(1318, 39, 'Why are triggers considered a poor place to enforce complex business rules compared to application code?', 'Trigger behavior is implicit and can surprise developers, and debugging relies on inspecting hidden server-side code', 'Triggers cannot run at all', 'Triggers are always slower than apps', 'Applications cannot see trigger results', 'A', 'Because triggers fire invisibly inside the server, their logic is easy to overlook and hard to test, so complex rules are often clearer in application code.', 'ADVANCED', 3, 'MCQ', 1),
(1319, 39, 'Which statement correctly creates a view with WITH CHECK OPTION and a filter on sales?', 'CREATE VIEW big_sales AS SELECT * FROM sales WHERE amount > 1000 WITH CHECK OPTION;', 'CREATE VIEW big_sales WITH CHECK FROM sales;', 'CREATE VIEW big_sales AS SELECT * FROM sales CHECK OPTION;', 'MAKE VIEW big_sales WITH CHECK;', 'A', 'WITH CHECK OPTION must follow the view''s SELECT clause, and it then rejects inserts or updates that would violate the amount > 1000 filter.', 'ADVANCED', 3, 'MCQ', 1),
(1320, 39, 'What is the main drawback of using a view to simplify every complex query in an application?', 'Views are always faster', 'A view that joins many large tables can run slowly each time it is queried, since it is not materialized by default', 'Views cannot be dropped', 'Views consume extra disk space for data', 'B', 'MySQL views are not materialized; the underlying query executes on every reference, so heavy views can become a performance bottleneck.', 'ADVANCED', 3, 'MCQ', 1),
(1321, 40, 'What does the EXPLAIN statement do in MySQL?', 'It executes the query', 'It shows how the optimizer plans to execute a query, including table access order and indexes used', 'It deletes the query', 'It counts rows in a table', 'B', 'EXPLAIN reports the execution plan the optimizer chose, such as which tables, joins and indexes will be used.', 'BEGINNER', 1, 'MCQ', 1),
(1322, 40, 'What is a database index?', 'A copy of the whole database', 'A data structure that speeds up lookups on certain columns', 'A type of trigger', 'A user account', 'B', 'An index is an auxiliary structure such as a B-tree that lets MySQL find and sort rows much faster than scanning everything.', 'BEGINNER', 1, 'MCQ', 1),
(1323, 40, 'Which statement creates an index named idx_email on the email column of the users table?', 'CREATE INDEX idx_email ON users(email);', 'ADD INDEX email TO users;', 'INDEX users ON email;', 'CREATE KEY email FROM users;', 'A', 'CREATE INDEX idx_name ON table(column) is the standard syntax for adding an index to an existing table.', 'BEGINNER', 1, 'MCQ', 1),
(1324, 40, 'Which component of a table is itself the clustered index in InnoDB?', 'The primary key', 'A secondary index', 'The foreign key', 'The AUTO_INCREMENT value', 'A', 'In InnoDB, data rows are physically organized around the primary key, so the primary key is the clustered index.', 'BEGINNER', 1, 'MCQ', 1),
(1325, 40, 'What does the slow query log capture?', 'All queries', 'Queries that take longer than a configured time threshold', 'Queries that fail', 'Only INSERT statements', 'B', 'The slow query log records statements whose execution time exceeds the long_query_time setting, helping to find bottlenecks.', 'BEGINNER', 1, 'MCQ', 1),
(1326, 40, 'Which command shows the list of currently running connections and queries?', 'SHOW PROCESSLIST', 'LIST QUERIES', 'SHOW INDEXES', 'STATUS RUN', 'A', 'SHOW PROCESSLIST displays active connections and their current statements, useful for spotting long-running queries.', 'BEGINNER', 1, 'MCQ', 1),
(1327, 40, 'What is the purpose of the MySQL query cache (before it was removed in MySQL 8)?', 'To cache SELECT result sets so identical queries could be served without re-execution', 'To store passwords', 'To cache database backups', 'To store table definitions', 'A', 'The query cache stored the result of a SELECT keyed by its text, letting identical later queries return instantly until the underlying data changed.', 'BEGINNER', 1, 'MCQ', 1),
(1328, 40, 'Which type of index does MySQL use by default for the InnoDB storage engine?', 'Hash index', 'B-tree index', 'BitMap index', 'R-tree index', 'B', 'InnoDB indexes are B-tree based, which supports both equality and range searches efficiently.', 'BEGINNER', 1, 'MCQ', 1),
(1329, 40, 'Which operation does an index primarily speed up?', 'INSERT statements only', 'Lookups and sorting in SELECT queries', 'DELETE statements only', 'User management', 'B', 'Indexes accelerate search, filtering and ordering in queries, at the cost of extra write overhead on the indexed columns.', 'BEGINNER', 1, 'MCQ', 1),
(1330, 40, 'Which EXPLAIN column tells you the index actually selected by the optimizer?', 'possible_keys', 'key', 'rows', 'filtered', 'B', 'The key column names the index the optimizer chose, while possible_keys lists all candidate indexes considered.', 'BEGINNER', 1, 'MCQ', 1),
(1331, 40, 'In EXPLAIN output, what does type = ALL indicate about a table access?', 'A full table scan, which usually means no useful index was used', 'A primary key lookup', 'An empty table', 'An error', 'A', 'type = ALL means MySQL will read every row of the table; it is often a performance warning unless the table is tiny.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1332, 40, 'What is the difference between possible_keys and key in an EXPLAIN result?', 'They are always identical', 'possible_keys lists indexes the optimizer could use, while key shows the one it actually chose', 'key lists all indexes in the table', 'possible_keys is always empty', 'B', 'possible_keys enumerates candidates, and key reports the winner; when key is NULL but possible_keys is not, the optimizer decided against using an index.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1333, 40, 'Why does column order matter in a composite index like (last_name, first_name)?', 'The index is most effective when the leftmost columns match the query conditions first', 'Column order has no effect', 'The rightmost column must be the primary key', 'Only the second column is indexed', 'A', 'A B-tree index on (a,b) supports searches on a, then on a and b; queries that skip the leading column cannot use the leftmost prefix.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1334, 40, 'Why should you avoid adding an index to every column of a table?', 'Indexes never help queries', 'Every extra index slows down INSERT, UPDATE and DELETE and consumes disk space', 'MySQL only allows two indexes', 'Indexes prevent NULLs', 'B', 'Each index must be maintained on every write and occupy storage, so too many indexes degrade write performance without adding query value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1335, 40, 'What does ''Using filesort'' mean in the Extra column of EXPLAIN?', 'MySQL must sort the result using an external sort operation because no index order matches the ORDER BY', 'The query writes to a file on disk permanently', 'The table is corrupted', 'The query is deleted', 'A', 'Using filesort indicates extra sorting work beyond the normal query, which may be avoidable by ordering through an index.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1336, 40, 'What is a covering index?', 'An index that contains every column the query needs, so the table itself never has to be read', 'An index covering all tables', 'An index on text columns', 'An index that hides data', 'A', 'When all selected and filtered columns exist in one index, MySQL can answer the query entirely from the index pages, a big speed-up.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1337, 40, 'Why is SELECT * often worse for performance than listing needed columns?', 'It returns extra unneeded data and can force reading full rows instead of a covering index', 'The asterisk is invalid SQL', 'It doubles the query cost', 'It disables indexes completely', 'A', 'Returning only the required columns reduces network and I/O and may let the optimizer use a covering index instead of the table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1338, 40, 'A query filters WHERE name LIKE ''%smith%''. Why can MySQL not use a normal index for this?', 'A leading wildcard prevents the index from finding a starting prefix to scan', 'LIKE never uses indexes', 'The name column is too short', 'Indexes only work on numbers', 'A', 'With a leading % the search string has no fixed prefix, so a B-tree index cannot help; only LIKE ''smith%'' can use an index.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1339, 40, 'Why should a foreign key column usually have an index?', 'Indexes are mandatory', 'It speeds up join lookups and the referential checks performed on the child column', 'It stores the data', 'It prevents the column from being NULL', 'B', 'Indexing the foreign key column accelerates the lookups used to match parent rows during joins and constraint validation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1340, 40, 'What does a low cardinality value on an indexed column indicate?', 'The column has very few distinct values, so the index may not help much', 'The column is empty', 'The index is corrupted', 'The column is very long', 'A', 'Cardinality is the count of distinct values; low cardinality (like a gender column with two values) means an index rarely narrows the search.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1341, 40, 'What does the rows column in EXPLAIN represent?', 'The exact number of rows the query will return', 'The optimizer''s estimate of rows examined per table access', 'The physical size of the table', 'The number of indexes', 'B', 'The rows estimate is a heuristic based on statistics and index cardinality, not an exact count, and helps spot scan sizes before running.', 'ADVANCED', 3, 'MCQ', 1),
(1342, 40, 'Why does wrapping an indexed column in a function, such as WHERE YEAR(birth_date) = 2000, prevent index usage?', 'The function must be computed for every row because the index stores raw values, not the transformed result', 'MySQL bans all functions', 'The optimizer ignores WHERE', 'Indexes cannot store dates', 'A', 'Because the index holds the original column values, a function on the column forces MySQL to evaluate it per row, defeating the index.', 'ADVANCED', 3, 'MCQ', 1),
(1343, 40, 'Why was the query cache removed entirely in MySQL 8?', 'It was too fast', 'It caused global mutex contention and was rarely a net win on multi-core systems', 'It could not store numbers', 'It was proprietary', 'B', 'The query cache serialized access with a global lock, hurt scalability, and its hit rates were low, so MySQL 8 dropped it in favor of other caching.', 'ADVANCED', 3, 'MCQ', 1),
(1344, 40, 'Which tool shows the optimizer''s actual cost calculations for a query?', 'EXPLAIN ANALYZE in MySQL 8', 'SHOW ENGINE INNODB STATUS', 'SHOW PROCESSLIST', 'DESCRIBE TABLE', 'A', 'EXPLAIN ANALYZE executes the query and reports actual timing and row counts per step, showing exactly where time is spent.', 'ADVANCED', 3, 'MCQ', 1),
(1345, 40, 'What is the purpose of running ANALYZE TABLE on a large InnoDB table after heavy changes?', 'It deletes old rows', 'It updates optimizer statistics such as index cardinality so the optimizer picks better plans', 'It rebuilds the entire database', 'It encrypts the table', 'B', 'ANALYZE TABLE refreshes the distribution statistics used by the optimizer, which prevents stale stats from producing poor query plans.', 'ADVANCED', 3, 'MCQ', 1),
(1346, 40, 'Why might a query with a range condition (WHERE id BETWEEN 1 AND 5000) switch to a full scan even with an index?', 'Because indexes are disabled for BETWEEN', 'If the range covers most of the table, the optimizer estimates a scan is cheaper than random index reads', 'Because BETWEEN is invalid SQL', 'Because the table has no primary key', 'B', 'When a large fraction of rows is selected, sequential reads outperform many random index lookups, so the optimizer chooses a scan.', 'ADVANCED', 3, 'MCQ', 1),
(1347, 40, 'How do you index a long TEXT column that cannot fit in an ordinary index?', 'Use a prefix index, e.g. INDEX (content(100)), indexing only the first 100 characters', 'TEXT columns cannot be indexed', 'Convert it to an ENUM', 'Index the whole column with a hash', 'A', 'Prefix indexes index only the leading characters of a string column, making them small enough to fit index page limits.', 'ADVANCED', 3, 'MCQ', 1),
(1348, 40, 'What is a common reason for locking waits and deadlocks in InnoDB under high concurrency?', 'Rows being accessed in inconsistent order across transactions while holding locks on them', 'Too many indexes', 'Slow SELECT queries', 'The binary log being disabled', 'A', 'When transactions lock rows in different orders, each can wait on the other''s locks, producing deadlocks that InnoDB resolves by rolling one back.', 'ADVANCED', 3, 'MCQ', 1),
(1349, 40, 'Why does ORDER BY an indexed column with a small LIMIT often avoid a filesort?', 'MySQL can walk the index in sorted order and stop after LIMIT rows without sorting the whole result', 'ORDER BY never sorts', 'The limit disables ordering', 'Indexes sort automatically at insert time', 'A', 'If the index already yields rows in the requested order, the optimizer reads them directly from the index and stops at the limit.', 'ADVANCED', 3, 'MCQ', 1),
(1350, 40, 'A slow query report shows a SELECT that only reads 3 columns filtering 2 others. Which single change most likely fixes it?', 'Adding a composite covering index on the filtered and selected columns', 'Dropping all indexes', 'Switching to MyISAM', 'Increasing the sort buffer', 'A', 'A covering index on exactly the columns used lets the query run entirely from the index, avoiding table reads and often filesorts.', 'ADVANCED', 3, 'MCQ', 1),
(1351, 41, 'Which interactive command-line tool is the standard terminal front-end for PostgreSQL?', 'psql', 'pgAdmin', 'pg_dump', 'postmaster', 'A', 'psql is the official interactive client that lets you run SQL against PostgreSQL from a terminal.', 'BEGINNER', 1, 'MCQ', 1),
(1352, 41, 'From inside psql, which meta-command shows all databases (typed as a backslash followed by a letter)?', 'backslash d', 'backslash l', 'backslash q', 'backslash s', 'B', 'The backslash-l meta-command is short for list and displays every database with its owner and encoding.', 'BEGINNER', 1, 'MCQ', 1),
(1353, 41, 'Which statement creates a new empty database called inventory?', 'ADD DATABASE inventory;', 'NEW DATABASE inventory;', 'CREATE DATABASE inventory;', 'MAKE DB inventory;', 'C', 'CREATE DATABASE inventory; is the standard SQL statement for creating a new database.', 'BEGINNER', 1, 'MCQ', 1),
(1354, 41, 'What is the default superuser role name created by a standard PostgreSQL installation?', 'admin', 'root', 'super', 'postgres', 'D', 'postgres is the default superuser role created during installation, owning the server''s administrative privileges.', 'BEGINNER', 1, 'MCQ', 1),
(1355, 41, 'Which SQL command permanently removes a database named olddb?', 'DROP DATABASE olddb;', 'DELETE DATABASE olddb;', 'REMOVE DATABASE olddb;', 'TRUNCATE DATABASE olddb;', 'A', 'DROP DATABASE removes the database and all of its objects, whereas DELETE and TRUNCATE only act on table rows.', 'BEGINNER', 1, 'MCQ', 1),
(1356, 41, 'Which statement begins a transaction that can later be committed or rolled back?', 'COMMIT;', 'BEGIN;', 'SAVEPOINT;', 'ROLLBACK;', 'B', 'BEGIN; starts a new transaction block whose changes are made permanent only when a COMMIT is issued.', 'BEGINNER', 1, 'MCQ', 1),
(1357, 41, 'A schema in PostgreSQL is used primarily for what purpose?', 'storing passwords', 'backing up data', 'grouping objects such as tables and functions into a namespace', 'storing connection settings', 'C', 'A schema is a namespace that organizes database objects and lets multiple applications share one database with isolated name spaces.', 'BEGINNER', 1, 'MCQ', 1),
(1358, 41, 'Which psql meta-command lists the tables in the current database (typed as a backslash followed by letters)?', 'backslash l', 'backslash q', 'backslash d', 'backslash dt', 'D', 'backslash dt is the meta-command that lists the tables of the current schema, standing for describe table.', 'BEGINNER', 1, 'MCQ', 1),
(1359, 41, 'Which of the following is a valid way to connect psql to a database named app on port 5432?', 'psql -d app -p 5432', 'psql app --port', 'psql -p app -d 5432', 'connect app', 'A', 'psql -d app -p 5432 selects database app with the -d flag and the listening port 5432 with the -p flag.', 'BEGINNER', 1, 'MCQ', 1),
(1360, 41, 'What does the command GRANT SELECT ON books TO reader; do?', 'denies the reader role all access', 'gives the reader role permission to run SELECT queries on books', 'deletes the books table', 'creates a new role named reader', 'B', 'GRANT SELECT ON books TO reader; adds the SELECT privilege on books for the reader role, letting it query the table.', 'BEGINNER', 1, 'MCQ', 1),
(1361, 41, 'After running CREATE ROLE clerk; a user named clerk tries to log in. Why might the login fail?', 'the password is too short', 'the database is full', 'the role does not have the LOGIN attribute', 'the role has no schema', 'C', 'A role created with plain CREATE ROLE gets no LOGIN attribute, so it cannot authenticate to a server session.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1362, 41, 'You run ALTER ROLE alice CREATEDB; What does alice gain?', 'the ability to drop any database', 'a new password', 'superuser rights', 'the ability to create new databases', 'D', 'CREATEDB is a role attribute that lets the role create databases, though it cannot grant that attribute to others.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1363, 41, 'Which psql meta-command lists all schemas in the current database (typed as a backslash followed by letters)?', 'backslash dn', 'backslash dt', 'backslash dv', 'backslash di', 'A', 'backslash dn lists the schemas of the current database, which are the top-level namespaces that hold database objects.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1364, 41, 'Why might CREATE DATABASE fail with the message role does not have permission?', 'the server is offline', 'the current role lacks the CREATEDB attribute', 'the database name has uppercase letters', 'the default tablespace is missing', 'B', 'Creating a database requires the CREATEDB privilege, so a role without that attribute cannot run CREATE DATABASE.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1365, 41, 'Which of these is NOT true about the public schema?', 'it exists by default in every database', 'its objects are visible to everyone by default', 'it can be dropped', 'it can hold only tables', 'C', 'The public schema can hold tables, views, functions and many other object kinds, so claiming it holds only tables is false.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1366, 41, 'What happens when you run DROP DATABASE while another session is connected to that database?', 'the database is dropped immediately', 'only the active session is dropped', 'the command waits until the session ends', 'the command fails with an error about active connections', 'D', 'PostgreSQL refuses to drop a database with open connections and raises an error saying the database is being accessed by other users.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1367, 41, 'Which statement gives role auditor the right to INSERT rows into table log?', 'GRANT INSERT ON log TO auditor;', 'ALLOW INSERT TO auditor ON log;', 'CREATE INSERT log auditor;', 'PRIVILEGE INSERT ON log auditor;', 'A', 'GRANT INSERT ON log TO auditor; adds the INSERT privilege on log for role auditor.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1368, 41, 'What does REVOKE SELECT ON books FROM clerk; accomplish?', 'removes the clerk role', 'removes clerk ability to read books', 'removes the books table', 'makes clerk a superuser', 'B', 'REVOKE SELECT removes the previously granted SELECT privilege, so clerk can no longer query the books table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1369, 41, 'Which database attribute can you change with ALTER DATABASE app OWNER TO dba;?', 'character encoding', 'connection limit', 'ownership', 'tablespace', 'C', 'ALTER DATABASE ... OWNER TO changes the role that owns the database, which controls who may drop or rename it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1370, 41, 'The search_path setting influences what when you write an unqualified table name in a query?', 'query performance', 'transaction isolation', 'the table owner', 'which schema PostgreSQL looks in for the table', 'D', 'search_path lists the schemas searched in order for unqualified object names, defaulting to the current user schema and then public.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1371, 41, 'A backup made with pg_dump mydb > mydb.sql is being restored with psql mydb < mydb.sql. What is missing from this procedure?', 'nothing', 'the psql restore cannot create roles that do not already exist on the target server', 'the target database must be dropped first', 'pg_dump output is binary only', 'B', 'A plain-text dump recreates tables and data, but role creation needs superuser privileges, so restoring fails when the referenced roles do not exist on the target.', 'ADVANCED', 3, 'MCQ', 1),
(1372, 41, 'You restore a custom-format dump with pg_restore. Which flag tells it to drop existing objects before recreating them?', '--create', '--verbose', '--clean', '--single-transaction', 'C', 'The --clean (or -c) flag makes pg_restore issue DROP statements for objects before recreating them.', 'ADVANCED', 3, 'MCQ', 1),
(1373, 41, 'Why might you use pg_restore with a custom-format dump instead of psql with a plain text dump?', 'custom format is smaller only', 'plain dumps cannot restore data', 'psql cannot read SQL files', 'you can selectively restore objects and run restores in parallel', 'D', 'Custom-format dumps support selective object restoration, parallel jobs and interactive listing, which plain SQL dumps do not.', 'ADVANCED', 3, 'MCQ', 1),
(1374, 41, 'A role named app is a member of role readonly, which has SELECT on books. What must be true for app to query books?', 'app inherits readonly privileges by default', 'app must be superuser', 'readonly must be dropped', 'app needs a password', 'A', 'By default roles inherit the privileges of the roles they belong to (INHERIT), so app can SELECT books through readonly.', 'ADVANCED', 3, 'MCQ', 1),
(1375, 41, 'You create schema analytics owned by role etl. Why can a superuser-backed application still read it without an explicit GRANT?', 'schemas are public by default', 'superusers bypass all privilege checks', 'GRANT is only used for tables', 'the application has a password', 'B', 'Superusers are exempt from normal privilege checks and can access any object in any schema without a GRANT.', 'ADVANCED', 3, 'MCQ', 1),
(1376, 41, 'Which is the correct element order for a local connection rule in a pg_hba.conf authentication file?', 'host, database, user, address, method', 'method, user, database, address', 'local, database, user, auth-method', 'user, database, host, method', 'C', 'pg_hba.conf lines begin with the connection type, then database, then user, and end with the authentication method for local lines.', 'ADVANCED', 3, 'MCQ', 1),
(1377, 41, 'What is a template database used for in PostgreSQL?', 'storing backups', 'indexing', 'encryption', 'serving as the model that new databases are copied from', 'D', 'template1 (and the pristine template0) is copied when a new database is created, so objects added to template1 appear in every new database.', 'ADVANCED', 3, 'MCQ', 1),
(1378, 41, 'You set ALTER ROLE app CONNECTION LIMIT 5; what does it limit?', 'how many simultaneous connections app may open', 'the number of databases app owns', 'the queries app may run per second', 'the size of result sets', 'A', 'CONNECTION LIMIT caps the number of concurrent server connections a role may use, with a value of -1 meaning unlimited.', 'ADVANCED', 3, 'MCQ', 1),
(1379, 41, 'What is the effect of CREATE DATABASE fresh TEMPLATE template0;?', 'template0 is dropped', 'fresh starts from a pristine base free of local template1 customizations', 'fresh has no owner', 'fresh is read-only', 'B', 'Using TEMPLATE template0 builds a clean database that excludes any custom objects that were added to template1.', 'ADVANCED', 3, 'MCQ', 1),
(1380, 41, 'Which approach cleanly renames a database that currently has active connections?', 'drop the database and recreate it', 'ALTER DATABASE ... RENAME inside a transaction', 'terminate the connections first, then ALTER DATABASE ... RENAME', 'restore from a backup', 'C', 'RENAME fails while connections are open, so you must terminate the sessions first, for example with pg_terminate_backend, before renaming.', 'ADVANCED', 3, 'MCQ', 1),
(1381, 42, 'Which PostgreSQL data type generates an auto-incrementing integer column when used as a column type?', 'SERIAL', 'FLOAT', 'TEXT', 'BOOLEAN', 'A', 'SERIAL is a pseudo-type that creates an integer column backed by a sequence, auto-filling each new row.', 'BEGINNER', 1, 'MCQ', 1),
(1382, 42, 'In NUMERIC(8,2), what do the numbers 8 and 2 mean?', '8 bytes total with 2 bytes of fraction', '8 total digits with exactly 2 digits after the decimal point', '8 digits before the decimal point', '8 percent precision', 'B', 'NUMERIC(8,2) stores up to 8 significant digits with exactly 2 digits after the decimal point.', 'BEGINNER', 1, 'MCQ', 1),
(1383, 42, 'Which type should you choose for an exact currency amount to avoid floating-point rounding?', 'REAL', 'DOUBLE PRECISION', 'NUMERIC', 'INTEGER', 'C', 'NUMERIC is an exact arbitrary-precision type, so it avoids the rounding errors of floating-point REAL and DOUBLE PRECISION.', 'BEGINNER', 1, 'MCQ', 1),
(1384, 42, 'What is the main purpose of the UUID data type in PostgreSQL?', 'increasing performance', 'saving disk space', 'storing globally unique identifiers', 'sorting text faster', 'D', 'The UUID type stores 128-bit universally unique identifiers, which is useful when ids must be unique across separate systems.', 'BEGINNER', 1, 'MCQ', 1),
(1385, 42, 'Which constraint guarantees that a column must have a value in every row?', 'NOT NULL', 'DEFAULT', 'CHECK', 'INDEX', 'A', 'NOT NULL rejects NULL values, requiring every row to hold a value in that column.', 'BEGINNER', 1, 'MCQ', 1),
(1386, 42, 'What does a PRIMARY KEY constraint guarantee about a column?', 'values are random', 'each value is unique and not null', 'values are alphabetical', 'only one table can reference it', 'B', 'A PRIMARY KEY combines UNIQUE and NOT NULL, and each table can have at most one primary key.', 'BEGINNER', 1, 'MCQ', 1),
(1387, 42, 'Which data type stores a string padded to exactly n characters?', 'TEXT', 'VARCHAR(n)', 'CHAR(n)', 'TEXT(n)', 'C', 'CHAR(n) is a fixed-length character type that pads stored values with blanks to the declared length n.', 'BEGINNER', 1, 'MCQ', 1),
(1388, 42, 'What does the UNIQUE constraint do to a column?', 'prevents reads', 'removes duplicate rows', 'adds an index only', 'rejects duplicate values in that column', 'D', 'UNIQUE forbids two rows from sharing the same value in the constrained column, and it builds a supporting index automatically.', 'BEGINNER', 1, 'MCQ', 1),
(1389, 42, 'Which constraint verifies that a column value satisfies an expression such as price > 0?', 'CHECK', 'FOREIGN KEY', 'DEFAULT', 'IDENTITY', 'A', 'CHECK enforces that column values satisfy a boolean expression and rejects any row that violates it.', 'BEGINNER', 1, 'MCQ', 1),
(1390, 42, 'What value is used when you insert a row without specifying a column that has a DEFAULT clause?', 'NULL', 'the value from the DEFAULT expression', 'the sequence value', 'an error', 'B', 'The DEFAULT clause supplies the value that is used when the column is omitted from an INSERT statement.', 'BEGINNER', 1, 'MCQ', 1),
(1391, 42, 'What is the key difference between SERIAL and the SQL-standard IDENTITY column?', 'they are identical', 'SERIAL is always faster', 'IDENTITY follows the SQL standard and offers separate GENERATED clauses', 'IDENTITY cannot be a primary key', 'C', 'GENERATED ... AS IDENTITY is the standard-compliant approach, while SERIAL is a legacy PostgreSQL pseudo-type with different sequence ownership semantics.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1392, 42, 'You declare id INTEGER GENERATED ALWAYS AS IDENTITY. What happens if you try to insert an explicit value into id?', 'it is stored as is', 'it is doubled', 'it is ignored silently', 'an error is raised unless OVERRIDING SYSTEM VALUE is used', 'D', 'For GENERATED ALWAYS columns, inserting an explicit value raises an error unless you add OVERRIDING SYSTEM VALUE to the INSERT.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1393, 42, 'Which of these is the correct range for the INTEGER type in PostgreSQL?', '-2147483648 to 2147483647', '-32768 to 32767', '0 to 4294967295', '-9223372036854775808 to 9223372036854775807', 'A', 'INTEGER is a 32-bit signed type ranging from -2^31 to 2^31-1, while the last range belongs to BIGINT.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1394, 42, 'Why might 0.1 + 0.2 not equal 0.3 when stored in a REAL column?', 'REAL truncates to integers', 'floating-point binary arithmetic cannot represent all decimals exactly', 'REAL only stores text', 'PostgreSQL rounds only even numbers', 'B', 'Floating-point types store binary approximations, so decimal fractions like 0.1 are not exact and sums can drift from the decimal result.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1395, 42, 'Which statement defines a new enum type with three values?', 'CREATE TYPE mood AS ENUM (''sad'',''ok'',''happy'');', 'CREATE ENUM mood (''sad'',''ok'',''happy'');', 'CREATE TABLE mood ENUM (...);', 'ENUM mood sad ok happy;', 'C', 'CREATE TYPE ... AS ENUM defines a user-defined enumerated type with a fixed, ordered list of allowed values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1396, 42, 'Which of these is NOT accepted as a boolean true value by PostgreSQL?', 'true', 't', 'yes', '2', 'D', 'PostgreSQL accepts true, t, yes, on and 1 as true, but a bare 2 is not a valid boolean literal.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1397, 42, 'A column declared product_id INT REFERENCES products(id) creates what kind of constraint?', 'FOREIGN KEY', 'CHECK', 'UNIQUE', 'SERIAL', 'A', 'The REFERENCES clause declares a foreign key that links product_id to the primary key of the products table.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1398, 42, 'How many NULL values may a UNIQUE column contain?', 'none', 'an unlimited number', 'at most one', 'depends on the table size', 'B', 'PostgreSQL treats NULLs as distinct for UNIQUE purposes, so a column with a UNIQUE constraint may hold many NULL rows.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1399, 42, 'What happens if you try to insert a string longer than VARCHAR(5)?', 'it is truncated silently', 'it is stored in overflow pages', 'an error is raised', 'it wraps to the next row', 'C', 'VARCHAR(n) enforces the length limit and rejects oversized values with an error, unlike TEXT which has no length cap.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1400, 42, 'Which of these correctly describes the SMALLINT range in PostgreSQL?', '-2^31 to 2^31-1', '0 to 65535', '-2^63 to 2^63-1', '-32768 to 32767', 'D', 'SMALLINT is a 16-bit signed integer ranging from -32768 to 32767.', 'INTERMEDIATE', 2, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(1401, 42, 'You already have an enum type mood and now need to add a new value. Which is the correct way?', 'CREATE TYPE mood AS ENUM ... again', 'ALTER TYPE mood ADD VALUE ''ecstatic'';', 'UPDATE mood SET ...', 'INSERT INTO mood ...', 'B', 'Adding a value to an existing enum requires ALTER TYPE ... ADD VALUE, which appends it to the end of the enum''s ordering.', 'ADVANCED', 3, 'MCQ', 1),
(1402, 42, 'What is the effect of adding a CHECK constraint as NOT VALID to a very large table?', 'it disables the constraint forever', 'it drops the column', 'existing rows are not scanned, but new rows are still enforced', 'it forces a full table scan', 'C', 'Adding a constraint as NOT VALID skips the expensive scan of existing rows while still enforcing it on new data; a later VALIDATE CONSTRAINT can verify old rows.', 'ADVANCED', 3, 'MCQ', 1),
(1403, 42, 'Why does ALTER TABLE t ALTER COLUMN c TYPE bigint; usually rewrite the table?', 'nothing happens', 'the column is renamed', 'only the index is rebuilt', 'the table is rewritten because the new type needs a different on-disk representation', 'D', 'Most ALTER COLUMN TYPE operations rewrite the whole table because the storage format of the column changes.', 'ADVANCED', 3, 'MCQ', 1),
(1404, 42, 'Which constraint prevents two bookings from covering overlapping time intervals in the same table?', 'EXCLUDE USING gist (room WITH =, during WITH &&)', 'CHECK (room <> during)', 'UNIQUE (room, during)', 'FOREIGN KEY (room)', 'A', 'EXCLUDE USING gist with the && overlap operator forbids rows whose ranges overlap, which a plain UNIQUE or CHECK constraint cannot express.', 'ADVANCED', 3, 'MCQ', 1),
(1405, 42, 'You define a FOREIGN KEY with ON DELETE CASCADE. What happens when the referenced parent row is deleted?', 'the foreign key is removed', 'child rows referencing it are deleted automatically', 'nothing happens', 'the parent row is kept', 'B', 'ON DELETE CASCADE propagates the deletion, automatically removing all child rows that reference the deleted parent row.', 'ADVANCED', 3, 'MCQ', 1),
(1406, 42, 'Why might joining on a UUID column be slower than joining on an INTEGER primary key?', 'UUID is deprecated', 'UUIDs cannot be indexed', 'UUIDs are 128-bit random values, making indexes larger and less clustered than small integers', 'UUID columns are always NULL', 'C', 'Random 128-bit UUID keys produce scattered inserts and larger indexes, so lookups and joins are typically slower than with compact sequential integers.', 'ADVANCED', 3, 'MCQ', 1),
(1407, 42, 'How do you make a foreign key check run only at COMMIT time rather than after every statement?', 'SET FOREIGN_KEY_CHECKS', 'use SERIAL', 'drop the constraint', 'declare it DEFERRABLE INITIALLY DEFERRED', 'D', 'A DEFERRABLE INITIALLY DEFERRED constraint defers its check until transaction commit, allowing temporarily inconsistent states mid-transaction.', 'ADVANCED', 3, 'MCQ', 1),
(1408, 42, 'Which statement converts an INTEGER column to BIGINT while automatically converting existing values?', 'ALTER TABLE t ALTER COLUMN c TYPE bigint;', 'UPDATE t SET c = bigint;', 'CAST c AS bigint ON t;', 'CHANGE c TO bigint IN t;', 'A', 'ALTER TABLE ... ALTER COLUMN ... TYPE bigint uses an implicit cast to convert existing values and rebuild the column.', 'ADVANCED', 3, 'MCQ', 1),
(1409, 42, 'What happens when a SERIAL column''s backing sequence reaches its maximum value?', 'it resets to zero', 'inserts fail with a sequence exhausted error until the sequence is rebuilt or altered', 'it auto-expands to BIGINT', 'it starts returning NULL', 'B', 'SERIAL uses a plain INTEGER-backed sequence, so once it exceeds the 32-bit maximum, new inserts fail until the sequence is recreated as BIGINT.', 'ADVANCED', 3, 'MCQ', 1),
(1410, 42, 'Which statement is true about NUMERIC type storage in PostgreSQL?', 'NUMERIC is stored as fixed 8-byte floats', 'NUMERIC maxes out at 18 digits', 'NUMERIC stores up to 1000 digits of precision with variable storage', 'NUMERIC is an alias for REAL', 'C', 'NUMERIC is arbitrary precision up to 1000 digits and uses a variable amount of storage depending on the declared scale.', 'ADVANCED', 3, 'MCQ', 1),
(1411, 43, 'What is the main difference between the json and jsonb data types?', 'jsonb stores a decomposed binary form that supports indexing, while json keeps the raw input text', 'jsonb is a string alias', 'json is faster for all queries', 'there is no difference', 'A', 'jsonb stores the document in a decomposed binary format that can be indexed with GIN, while json keeps the exact input text.', 'BEGINNER', 1, 'MCQ', 1),
(1412, 43, 'Which operator checks whether one jsonb value contains another jsonb value?', '=', '@>', '<@', '?&', 'B', 'The @> operator (contains) returns true when the left jsonb contains the structure and values of the right one.', 'BEGINNER', 1, 'MCQ', 1),
(1413, 43, 'Which declaration creates a table column that holds an array of integers?', 'price INT ARRAY', 'price INT[]', 'price ARRAY OF INT', 'price INT LIST', 'C', 'price INT[] declares a one-dimensional array column whose elements are integers.', 'BEGINNER', 1, 'MCQ', 1),
(1414, 43, 'Which function appends an element to the end of an array?', 'array_prepend', 'array_extend', 'array_add', 'array_append', 'D', 'array_append(array, element) returns the input array with the element added at the end.', 'BEGINNER', 1, 'MCQ', 1),
(1415, 43, 'Which operator extracts a jsonb field and returns it as jsonb?', '->', '->>', '#>', '#>>', 'A', 'The -> operator pulls a key and returns the value as jsonb, preserving its type.', 'BEGINNER', 1, 'MCQ', 1),
(1416, 43, 'Which index type is designed for efficient containment and existence queries on jsonb documents?', 'btree', 'GIN', 'hash only', 'no index works on jsonb', 'B', 'A GIN index is the standard choice for jsonb containment and existence queries using operators such as @> and ?.', 'BEGINNER', 1, 'MCQ', 1),
(1417, 43, 'Which operator extracts a jsonb field value as plain text?', '->', '#>', '->>', '@>', 'C', 'The ->> operator extracts a field and casts it to text, which is convenient for comparisons and display.', 'BEGINNER', 1, 'MCQ', 1),
(1418, 43, 'Which function returns the number of elements in an array?', 'length()', 'count()', 'array_size()', 'cardinality()', 'D', 'cardinality(array) returns the total number of elements in the array.', 'BEGINNER', 1, 'MCQ', 1),
(1419, 43, 'How do you build an array literal with the array constructor in PostgreSQL?', 'ARRAY[1,2,3]', '[1,2,3]', 'ARRAY(1,2,3)', '(1,2,3)', 'A', 'ARRAY[1,2,3] is the array constructor syntax; the string form ''{1,2,3}'' is an alternative way to write an array constant.', 'BEGINNER', 1, 'MCQ', 1),
(1420, 43, 'Which function builds a jsonb object from alternating keys and values?', 'jsonb_make', 'jsonb_build_object', 'jsonb_object_text', 'jsonb_construct', 'B', 'jsonb_build_object(''a'',1,''b'',2) constructs a jsonb object from the supplied alternating key and value arguments.', 'BEGINNER', 1, 'MCQ', 1),
(1421, 43, 'Which operator tests whether a jsonb object contains a given top-level key?', '@>', '->', '?', '||', 'C', 'The ? operator returns true when the jsonb object has the named key at its top level.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1422, 43, 'You store data in a jsonb column. How do you update a specific key inside the document?', 'INSERT INTO ... ON CONFLICT', 'jsonb_merge', 'array_append', 'jsonb_set(doc, path, value)', 'D', 'jsonb_set(doc, ''{key}'', value, true) replaces the value at the given path, creating the key when the fourth argument is true.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1423, 43, 'Which pair of operators checks whether a jsonb object has ANY or ALL of a list of keys?', '?| and ?&', '@> and <@', '-> and ->>', '#- and #>', 'A', 'The ?| operator checks whether any listed key exists, while ?& requires all listed keys to exist.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1424, 43, 'Given a jsonb column data holding an object with a name key, which expression returns the name value as plain text?', 'data -> ''name''', 'data ->> ''name''', 'data #> ''name''', 'data @> ''name''', 'B', 'The ->> operator extracts the name field as text, giving the readable string value.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1425, 43, 'Which function expands an array into one row per element?', 'array_to_string', 'array_agg', 'unnest', 'array_prepend', 'C', 'unnest(array) turns each array element into a separate row, which is useful for pivoting arrays into a normal relation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1426, 43, 'Which function evaluates a JSONPath expression against a jsonb value?', 'jsonb_apply', 'jsonb_query', 'jsonb_extract', 'jsonb_path_query', 'D', 'jsonb_path_query(doc, ''$.items[*].price'') evaluates a JSONPath expression and returns the matching values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1427, 43, 'Which operator removes a key from a jsonb object?', '-', '--', '~', '!', 'A', 'jsonb - ''key'' returns the object with that key removed, and the same minus operator can remove array elements by index.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1428, 43, 'Which function converts an array into a single delimiter-separated string?', 'string_to_array', 'array_to_string', 'unnest', 'array_position', 'B', 'array_to_string(array, '','') joins the elements with the given delimiter and is the inverse of string_to_array.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1429, 43, 'Which aggregate function collects the values of a group into an array?', 'array_collect', 'unnest', 'array_agg', 'json_agg', 'C', 'array_agg(value) builds an array from all values in the group, such as array_agg(name ORDER BY age).', 'INTERMEDIATE', 2, 'MCQ', 1),
(1430, 43, 'Which operator merges two jsonb objects into one?', '+', '&', '->', '||', 'D', 'The || operator merges jsonb objects, with values from the right operand overwriting duplicate keys from the left.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1431, 43, 'When should you prefer the jsonb_path_ops GIN operator class over the default jsonb_ops class?', 'always, it is faster everywhere', 'for pure containment queries with @>, where it can be several times faster', 'never, it is deprecated', 'only for numeric keys', 'B', 'jsonb_path_ops builds a smaller index that is very efficient for @> containment checks, though it lacks the key-existence operators.', 'ADVANCED', 3, 'MCQ', 1),
(1432, 43, 'Why is a regular btree index on a jsonb column impossible in PostgreSQL?', 'jsonb has no = operator', 'btree needs unique keys', 'the jsonb type has no total linear ordering for btree to rely on', 'jsonb cannot be indexed at all', 'C', 'jsonb supports equality but not a total linear ordering, so PostgreSQL provides GIN and SP-GIST indexes for it rather than btree.', 'ADVANCED', 3, 'MCQ', 1),
(1433, 43, 'You query WHERE (data ->> ''age'')::int > 30 on a large jsonb table. What is the most efficient way to speed it up?', 'add a GIN index on data', 'add a btree index on data', 'use a hash index on data', 'create a functional btree index on ((data ->> ''age'')::int)', 'D', 'Because the query casts the extracted text, a functional index on the exact expression ((data ->> ''age'')::int) matches the query and accelerates it.', 'ADVANCED', 3, 'MCQ', 1),
(1434, 43, 'What does jsonb do with duplicate keys when a document is parsed?', 'the last duplicate key wins and key order is not preserved', 'it keeps all duplicates in an array', 'it raises an error', 'it keeps only the first key', 'A', 'jsonb stores keys in a sorted internal form where only the last occurrence of a duplicate key is kept, so textual order is lost but lookups are fast.', 'ADVANCED', 3, 'MCQ', 1),
(1435, 43, 'Given arr = ARRAY[10,20,30,40], what does arr[2:3] evaluate to?', '[10,20]', '[20,30]', '[30,40]', '[40,10]', 'B', 'Array slicing arr[2:3] selects the elements from index 2 through index 3 inclusive, so the array [10,20,30,40] yields [20,30].', 'ADVANCED', 3, 'MCQ', 1),
(1436, 43, 'A json column stores an object that differs from another one only by whitespace. Why does an equality comparison return false?', 'jsonb ignores spaces too', 'equality never works on json', 'the json type compares raw bytes, so whitespace makes the values unequal', 'the server normalizes text automatically', 'C', 'The json type preserves the exact input text, so byte-for-byte comparisons fail when formatting differs; jsonb would normalize and match.', 'ADVANCED', 3, 'MCQ', 1),
(1437, 43, 'Given a jsonb value whose items key holds the array [5,7,9], what does data -> ''items'' ->> 0 return?', '7', '9', 'null', '5', 'D', 'data -> ''items'' gives the jsonb array [5,7,9], and applying ->> 0 extracts element index 0 as text, which is 5.', 'ADVANCED', 3, 'MCQ', 1),
(1438, 43, 'Which statement is true about the key ordering of a jsonb object?', 'keys are stored in sorted order, not insertion order', 'keys keep insertion order', 'keys are stored in a hash', 'order always matches the input exactly', 'A', 'jsonb reorders keys into a sorted internal form for fast lookup, so the visible order does not match the insertion order of the input.', 'ADVANCED', 3, 'MCQ', 1),
(1439, 43, 'Which construct converts a whole table row into a jsonb value?', 'jsonb_from_row', 'to_jsonb(row)', 'jsonb(row)', 'CAST row AS json', 'B', 'to_jsonb(value) converts any SQL value, including an entire row, into a jsonb representation.', 'ADVANCED', 3, 'MCQ', 1),
(1440, 43, 'Why does the ? key-existence operator on a GIN index behave differently from using ->> on a plain text column?', 'it is always slower', 'the ? operator only works on arrays', 'the ? check can use the GIN index for key membership, while ->> is a plain extraction that needs an expression index', '? ignores the index', 'C', 'The ? existence operator is directly supported by the GIN jsonb index, whereas ->> is just an extraction that requires a functional index to be accelerated.', 'ADVANCED', 3, 'MCQ', 1),
(1441, 44, 'Which clause defines the window of rows that a window function operates over?', 'OVER', 'PARTITION BY', 'GROUP BY', 'ROWS', 'A', 'The OVER clause defines the partitioning and ordering of rows for a window function.', 'BEGINNER', 1, 'MCQ', 1),
(1442, 44, 'Which window function assigns a unique number to each row in the result set?', 'RANK', 'ROW_NUMBER', 'DENSE_RANK', 'NTILE', 'B', 'ROW_NUMBER() assigns a distinct sequential number to each row following the window order.', 'BEGINNER', 1, 'MCQ', 1),
(1443, 44, 'What is the main difference between RANK and ROW_NUMBER?', 'they are identical', 'RANK cannot use ORDER BY', 'RANK gives tied rows the same rank and skips positions, while ROW_NUMBER always increments by one', 'ROW_NUMBER does not need ORDER BY', 'C', 'RANK gives equal values the same rank and leaves gaps, whereas ROW_NUMBER always returns consecutive numbers even for ties.', 'BEGINNER', 1, 'MCQ', 1),
(1444, 44, 'What does PARTITION BY do inside an OVER clause?', 'sorts the rows', 'limits the rows returned', 'creates a new table', 'divides rows into groups that the window function resets within', 'D', 'PARTITION BY splits the result into groups, and the window function restarts its computation for each partition.', 'BEGINNER', 1, 'MCQ', 1),
(1445, 44, 'Which function ranks rows with equal values having the same rank but WITHOUT leaving gaps?', 'DENSE_RANK', 'RANK', 'ROW_NUMBER', 'LAG', 'A', 'DENSE_RANK assigns identical ranks to ties and does not skip numbers, so the ranks are always consecutive.', 'BEGINNER', 1, 'MCQ', 1),
(1446, 44, 'How does a window function differ from a plain aggregate?', 'there is no difference', 'a window function returns one result per row while an aggregate collapses a group into one row', 'aggregates always run faster', 'windows cannot use SUM', 'B', 'Aggregates reduce a group to a single row, while window functions keep all rows and attach the computed value to each of them.', 'BEGINNER', 1, 'MCQ', 1),
(1447, 44, 'What does ORDER BY inside an OVER clause control?', 'the order rows are inserted', 'the primary key', 'the order in which the window function processes rows', 'permissions', 'C', 'ORDER BY in OVER determines the row order used for ranking and running aggregates within each window.', 'BEGINNER', 1, 'MCQ', 1),
(1448, 44, 'Which function lets you access the value of a previous row in the same window?', 'LEAD', 'ROW_NUMBER', 'FIRST_VALUE', 'LAG', 'D', 'LAG(column) returns the value from the row that comes before the current row in the window order.', 'BEGINNER', 1, 'MCQ', 1),
(1449, 44, 'Which expression computes a running total over all rows up to and including the current row?', 'SUM(amount) OVER (ORDER BY day)', 'SUM(amount)', 'SELECT running', 'COUNT(*) GROUP BY day', 'A', 'SUM(amount) OVER (ORDER BY day) is a cumulative sum, so each row shows the running total as the frame grows with the current row.', 'BEGINNER', 1, 'MCQ', 1),
(1450, 44, 'Why can a window function not be used directly in a WHERE clause?', 'it is too slow', 'WHERE is evaluated before the window function, which runs after the row filter', 'the syntax is not allowed', 'window functions can run in WHERE', 'B', 'Window functions are evaluated after WHERE filtering, so they cannot appear in WHERE; use a subquery or CTE to filter on their results.', 'BEGINNER', 1, 'MCQ', 1),
(1451, 44, 'Given sales(dept, amount) with rows (''A'',100), (''A'',200), (''B'',150), what does SELECT dept, SUM(amount) OVER (PARTITION BY dept) FROM sales return for the three rows?', '100, 200, 150', '300, 150, 150', '300, 300, 150', '100, 300, 150', 'C', 'SUM OVER (PARTITION BY dept) repeats the per-department total on every row of that partition, so both A rows show 300 and the B row shows 150.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1452, 44, 'Given score(name, value) with rows (''x'',10), (''y'',20), (''z'',10), what does DENSE_RANK() OVER (ORDER BY value) yield for x, y and z?', '1, 2, 3', '2, 1, 2', '3, 2, 3', '1, 2, 1', 'D', 'DENSE_RANK gives both 10s the rank 1 and the next distinct value 20 the rank 2, producing 1, 2, 1 across x, y and z.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1453, 44, 'Given the same score table, what does RANK() OVER (ORDER BY value) yield for x(10), y(20) and z(10)?', '1, 3, 1', '1, 2, 2', '2, 3, 2', '1, 2, 1', 'A', 'RANK ranks both 10s as 1 and then skips to 3 for the next value, so y receives 3, giving the sequence 1, 3, 1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1454, 44, 'What does LAG(salary) OVER (ORDER BY salary) return for the FIRST row of the window?', '0', 'NULL', 'the same value', 'an error', 'B', 'LAG returns NULL for rows that have no previous row in the window order, such as the very first row.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1455, 44, 'Which function returns the value from a row that follows the current row in the window?', 'LAG', 'ROW_NUMBER', 'LEAD', 'LAST_VALUE', 'C', 'LEAD(column) fetches the value from the row that comes after the current row in the window order.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1456, 44, 'Given emp(name, dept, sal) with rows (''a'',''IT'',10), (''b'',''IT'',20), (''c'',''HR'',30), what does COUNT(*) OVER (PARTITION BY dept) return per row?', '1, 1, 1', '2, 1, 1', '3, 2, 1', '2, 2, 1', 'D', 'The IT partition has two rows so its count is 2 on both IT rows, and the HR partition has one row so its count is 1, giving 2, 2, 1.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1457, 44, 'Which function divides the ordered result set into a given number of roughly equal buckets?', 'NTILE(n)', 'RANK()', 'PERCENT_RANK()', 'CUME_DIST()', 'A', 'NTILE(n) assigns each row a bucket number from 1 to n, splitting the ordered set into n groups of near-equal size.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1458, 44, 'What does the frame clause ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW define?', 'a partition', 'a frame that starts at the first row of the partition and ends at the current row', 'a new table', 'an ordering', 'B', 'That frame clause makes the window cover every row from the start of the partition through the current row, which is the basis of running totals.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1459, 44, 'Given a running-total query SUM(x) OVER (ORDER BY pos), which frame is used implicitly when none is specified?', 'RANGE BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING', 'no frame at all', 'RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW', 'ROWS BETWEEN CURRENT ROW AND CURRENT ROW', 'C', 'When ORDER BY is present but no frame is written, the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1460, 44, 'Which pair of functions returns the first and last values of a window frame?', 'LAG and LEAD', 'ROW_NUMBER and RANK', 'SUM and AVG', 'FIRST_VALUE and LAST_VALUE', 'D', 'FIRST_VALUE returns the value from the first row of the frame and LAST_VALUE returns the value from the last row of the frame.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1461, 44, 'Given daily prices (day, price) with rows (1,10), (2,12), (3,15), what does AVG(price) OVER (ORDER BY day ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) return?', '10, 10, 11', '10, 11, 13.5', '10, 12, 15', '11, 13.5, 15', 'B', 'The frame includes only the current and previous row, so the averages are 10, (10+12)/2 = 11 and (12+15)/2 = 13.5.', 'ADVANCED', 3, 'MCQ', 1),
(1462, 44, 'Given scores of 90, 90 and 70, what does CUME_DIST() OVER (ORDER BY score DESC) return for the row with score 70?', '0', '0.5', '1', '0.75', 'C', 'CUME_DIST is the count of rows up to and including the current one divided by the partition size; the lowest score is the last row, giving 3/3 = 1.', 'ADVANCED', 3, 'MCQ', 1),
(1463, 44, 'Which statement correctly contrasts RANGE frames with ROWS frames?', 'they are always identical', 'RANGE counts physical rows', 'ROWS cannot be used with ORDER BY', 'RANGE treats rows with equal ORDER BY keys as one peer group, while ROWS counts individual rows', 'D', 'RANGE frames group rows with equal ORDER BY keys into peers and move as a unit, whereas ROWS frames advance strictly by individual row count.', 'ADVANCED', 3, 'MCQ', 1),
(1464, 44, 'Given emp(name, sal) with rows (''a'',50), (''b'',50), (''c'',60), what is the exact output of SELECT name, DENSE_RANK() OVER (ORDER BY sal) FROM emp ORDER BY name?', 'a 1, b 1, c 2', 'a 1, b 2, c 3', 'a 2, b 1, c 1', 'a 1, b 1, c 3', 'A', 'Both 50s tie for rank 1 and DENSE_RANK does not skip, so the 60 gets rank 2; ordered by name the rows are a 1, b 1, c 2.', 'ADVANCED', 3, 'MCQ', 1),
(1465, 44, 'Why can you not filter on a window function result with WHERE on the same query level?', 'window functions are not allowed in SQL', 'WHERE runs before the window function has computed its values, so the predicate cannot see them', 'the optimizer removes such filters', 'it returns NULL', 'B', 'WHERE filters rows before window functions evaluate, so a window result cannot be referenced there; wrap the query in a subquery or CTE to filter on it.', 'ADVANCED', 3, 'MCQ', 1),
(1466, 44, 'How do you avoid repeating long OVER clauses when a query needs several identical window definitions?', 'use a macro', 'use GROUP BY', 'use the WINDOW clause to name a window and reference it with OVER w', 'there is no way', 'C', 'The WINDOW clause names a window definition that later OVER references can reuse, cutting down on duplication in the query.', 'ADVANCED', 3, 'MCQ', 1),
(1467, 44, 'Given sales(region, amount) with rows (''N'',10), (''N'',5), (''S'',8), what does LAG(amount, 1, 0) OVER (PARTITION BY region ORDER BY amount) return per row when rows are listed by increasing amount?', '10, 5, 8', '0, 10, 0', '0, 10, 8', '0, 5, 0', 'D', 'LAG with a default of 0 fills the first row of each partition with 0 and returns the previous amount for later rows, giving 0, 5, 0.', 'ADVANCED', 3, 'MCQ', 1),
(1468, 44, 'Why might SUM(amount) OVER (ORDER BY id) not give the expected running total when id values repeat?', 'with RANGE as the default frame, duplicate ids are treated as peers and grouped into one frame step', 'SUM is not a window function', 'ORDER BY cannot be used here', 'duplicates are removed', 'A', 'Because the default frame is RANGE, rows sharing the same id are included or excluded together, so the cumulative sum can jump; adding a unique tiebreaker fixes it.', 'ADVANCED', 3, 'MCQ', 1),
(1469, 44, 'Which approach keeps only the top 3 rows of each group after ranking?', 'GROUP BY with LIMIT 3', 'a subquery that computes ROW_NUMBER() OVER (PARTITION BY grp ORDER BY score DESC) and an outer WHERE rn <= 3', 'ORDER BY score LIMIT 3', 'a single WHERE rn <= 3 directly', 'B', 'Row numbering inside each partition followed by an outer filter rn <= 3 keeps exactly the top three rows of every group.', 'ADVANCED', 3, 'MCQ', 1),
(1470, 44, 'What is the relationship between ROW_NUMBER() and NTILE() results when ORDER BY values tie?', 'none, they are identical', 'NTILE assigns unique numbers', 'ROW_NUMBER breaks ties arbitrarily while NTILE groups tied rows possibly into different buckets without reordering them', 'NTILE is deterministic while ROW_NUMBER is not', 'C', 'ROW_NUMBER hands out arbitrary but unique numbers across ties, whereas NTILE assigns bucket numbers based on position, which can place equal values in different buckets.', 'ADVANCED', 3, 'MCQ', 1),
(1471, 45, 'Which procedural language ships with PostgreSQL by default for writing stored functions?', 'PL/pgSQL', 'PL/SQL', 'Transact-SQL', 'SQL/PSM', 'A', 'PL/pgSQL is PostgreSQL''s built-in procedural language used for functions, triggers and DO blocks.', 'BEGINNER', 1, 'MCQ', 1),
(1472, 45, 'In PL/pgSQL, what is the purpose of the dollar-quoted string $$ ... $$ around a function body?', 'to mark comments', 'to delimit the function body so internal quotes need no escaping', 'to concatenate strings', 'to name parameters', 'B', 'Dollar quoting wraps the function body in a delimiter, so single quotes inside it do not need escaping.', 'BEGINNER', 1, 'MCQ', 1),
(1473, 45, 'Which command writes a message to the server log from inside a PL/pgSQL function?', 'PRINT', 'LOG', 'RAISE', 'ECHO', 'C', 'RAISE NOTICE ''...'' writes a message and RAISE EXCEPTION aborts the function after reporting the error.', 'BEGINNER', 1, 'MCQ', 1),
(1474, 45, 'Which keyword starts the variable declaration section of a PL/pgSQL block?', 'VAR', 'LET', 'LOCAL', 'DECLARE', 'D', 'Variables are declared in a DECLARE section that precedes the BEGIN...END body of a PL/pgSQL block.', 'BEGINNER', 1, 'MCQ', 1),
(1475, 45, 'What is a common table expression (CTE) in PostgreSQL?', 'a named temporary result set defined with WITH', 'a stored procedure', 'an index type', 'a transaction', 'A', 'A common table expression, introduced by WITH name AS (...), names a subquery that the main query can reference.', 'BEGINNER', 1, 'MCQ', 1),
(1476, 45, 'Which clause must be present so that a CTE may reference itself recursively?', 'NO CYCLE', 'RECURSIVE', 'LOOP', 'ROWS', 'B', 'A self-referencing CTE must be declared WITH RECURSIVE for PostgreSQL to permit recursion.', 'BEGINNER', 1, 'MCQ', 1),
(1477, 45, 'Which statement creates a trigger on a table?', 'TRIGGER name', 'NEW TRIGGER', 'CREATE TRIGGER name BEFORE INSERT ON t ...', 'ADD TRIGGER', 'C', 'CREATE TRIGGER associates a trigger function with a table and specifies the timing (BEFORE/AFTER) and event (INSERT/UPDATE/DELETE).', 'BEGINNER', 1, 'MCQ', 1),
(1478, 45, 'Which command installs an extension such as pg_trgm into the current database?', 'INSTALL EXTENSION', 'USE EXTENSION', 'ADD EXTENSION', 'CREATE EXTENSION', 'D', 'CREATE EXTENSION pg_trgm; loads the extension''s SQL objects into the current database.', 'BEGINNER', 1, 'MCQ', 1),
(1479, 45, 'What does the PostGIS extension add to PostgreSQL?', 'geographic objects and spatial functions', 'full-text search', 'JSON parsing', 'encryption', 'A', 'PostGIS provides geometry types and spatial operations for geographic information systems.', 'BEGINNER', 1, 'MCQ', 1),
(1480, 45, 'What does the pg_trgm extension specialize in?', 'time-series data', 'trigram-based text similarity and fuzzy matching', 'encryption', 'array handling', 'B', 'pg_trgm builds trigram indexes on text and supports similarity operators such as % and <-> for fuzzy searches.', 'BEGINNER', 1, 'MCQ', 1),
(1481, 45, 'Given a PL/pgSQL function declared RETURNS integer whose body is RETURN 2 + 3;, what does calling it return?', '2', '3', '5', 'null', 'C', 'RETURN 2 + 3; evaluates the expression and returns the value 5, matching the RETURNS integer declaration.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1482, 45, 'What must a row-level trigger function return to let the row change proceed?', 'an integer', 'a boolean', 'NULL only', 'the special value NEW or OLD', 'D', 'A row-level trigger function must return the NEW (or OLD) record to indicate which row to use, and returning NULL cancels the operation.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1483, 45, 'When is a BEFORE trigger fired relative to the data-modifying command?', 'before the row is inserted, updated or deleted', 'after commit', 'before the transaction starts', 'only on SELECT', 'A', 'BEFORE triggers run before the row change is applied, allowing the trigger to modify NEW before it is stored.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1484, 45, 'In a row-level trigger, what do NEW and OLD refer to?', 'the trigger function name', 'NEW is the new row and OLD is the previous row', 'two tables', 'nothing', 'B', 'NEW holds the incoming row for INSERT/UPDATE and OLD holds the prior row for UPDATE/DELETE, with the unused one being NULL.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1485, 45, 'Why does a non-recursive CTE that references itself fail to parse?', 'it is a syntax error always', 'CTEs are materialized', 'a plain CTE cannot reference itself, and only WITH RECURSIVE permits self-reference', 'you need a view', 'C', 'A non-recursive CTE cannot reference itself in its definition; only WITH RECURSIVE enables self-reference.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1486, 45, 'Which keyword must separate the base case and the recursive step of a recursive CTE?', 'UNION', 'INTERSECT', 'MINUS', 'UNION ALL', 'D', 'WITH RECURSIVE combines the anchor term with the recursive term using UNION ALL (or UNION).', 'INTERMEDIATE', 2, 'MCQ', 1),
(1487, 45, 'With pg_trgm installed, which operator tests whether two strings are similar based on trigram similarity?', '%', '~', 'LIKE', '=', 'A', 'The % operator returns true when the trigram similarity between two strings exceeds the pg_trgm similarity threshold.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1488, 45, 'What does CREATE EXTENSION IF NOT EXISTS pg_trgm; do when the extension is already installed?', 'raises an error', 'does nothing and continues', 'drops the extension', 'creates a duplicate', 'B', 'The IF NOT EXISTS clause makes the command a no-op when the extension is already present instead of raising an error.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1489, 45, 'Which PL/pgSQL construct conditionally runs one block of code or another?', 'SWITCH', 'CASE WHEN THEN', 'IF ... THEN ... ELSE ... END IF;', 'LOOP', 'C', 'PL/pgSQL branches with IF ... THEN ... ELSE ... END IF (and CASE) to run different code depending on a condition.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1490, 45, 'Which volatility setting tells the planner that a function returns the same result for identical arguments and can be optimized away?', 'VOLATILE', 'STABLE', 'EXTERNAL', 'IMMUTABLE', 'D', 'IMMUTABLE means the function cannot change its result for fixed inputs, enabling constant folding and index usage, while STABLE is only safe within one statement.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1491, 45, 'WITH RECURSIVE nums(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM nums WHERE n < 5) SELECT max(n) FROM nums; What does this return?', '4', '5', '6', 'infinite loop', 'B', 'The recursion adds 1 at each step until n reaches 5, at which point n < 5 is false, so the rows are 1..5 and max(n) is 5.', 'ADVANCED', 3, 'MCQ', 1),
(1492, 45, 'Which PL/pgSQL trigger function correctly blocks a row when the quantity is negative?', 'CREATE FUNCTION chk() RETURNS TRIGGER AS $$ BEGIN IF NEW.qty < 0 THEN RAISE EXCEPTION ''negative qty''; END IF; RETURN NEW; END $$ LANGUAGE plpgsql;', 'CREATE FUNCTION chk() RETURNS integer AS $$ RETURN 0; $$ LANGUAGE plpgsql;', 'CREATE FUNCTION chk() RETURNS TRIGGER AS $$ SELECT 1; $$ LANGUAGE sql;', 'CREATE FUNCTION chk() RETURNS trigger AS $$ BEGIN RETURN NULL; END $$ LANGUAGE plpgsql;', 'A', 'The function checks NEW.qty and raises an exception for negative values; otherwise it returns NEW, and because it returns NEW the row change is allowed to proceed.', 'ADVANCED', 3, 'MCQ', 1),
(1493, 45, 'Which PostGIS function constructs a geometry from a well-known text (WKT) string?', 'ST_Buffer', 'ST_Intersects', 'ST_Transform', 'ST_GeomFromText', 'D', 'ST_GeomFromText(''POINT(1 2)'') parses a well-known text string into a PostGIS geometry value.', 'ADVANCED', 3, 'MCQ', 1),
(1494, 45, 'How do you remove a trigger named trg from table t?', 'DROP TRIGGER trg ON t;', 'DELETE TRIGGER trg;', 'REMOVE trg;', 'DROP TRIGGER t ON trg;', 'A', 'DROP TRIGGER trg ON t; removes the trigger from the table, and you may add IF EXISTS or CASCADE.', 'ADVANCED', 3, 'MCQ', 1),
(1495, 45, 'Inside a PL/pgSQL function, what is the difference between PERFORM and a bare SELECT?', 'there is no difference', 'a bare SELECT must assign its result to INTO, while PERFORM runs a query and discards the result', 'PERFORM is only for INSERT', 'SELECT is not allowed', 'B', 'Inside PL/pgSQL a bare SELECT must send its output into variables with INTO, whereas PERFORM executes a query purely for its side effects and discards any output.', 'ADVANCED', 3, 'MCQ', 1),
(1496, 45, 'Which index helps a query like WHERE name % ''jhon'' that uses pg_trgm similarity?', 'btree on name', 'hash on name', 'a GIN or GiST trigram index on name', 'no index helps', 'C', 'pg_trgm provides GIN and GiST operator classes that accelerate % similarity and ILIKE-style matching on text columns.', 'ADVANCED', 3, 'MCQ', 1),
(1497, 45, 'A recursive CTE has an anchor that selects employees whose manager_id IS NULL and a recursive step that joins employee to the CTE on manager_id. What does the whole CTE compute?', 'only employees without managers', 'a single employee', 'nothing', 'the full employee reporting hierarchy from the top down', 'D', 'The anchor selects the root employees and the recursive step walks down the manager_id links, producing the entire reporting tree.', 'ADVANCED', 3, 'MCQ', 1),
(1498, 45, 'Which SECURITY setting makes a function execute with the privileges of its creator rather than the caller?', 'SECURITY DEFINER', 'SECURITY INVOKER', 'SECURITY OWNER', 'SECURITY CALLER', 'A', 'SECURITY DEFINER runs the function as the function owner, which can deliberately escalate privileges for controlled access.', 'ADVANCED', 3, 'MCQ', 1),
(1499, 45, 'Why can a STABLE function not be used in a btree index expression?', 'it never runs', 'it cannot; only IMMUTABLE functions may appear in index expressions', 'STABLE always returns constants', 'there is no restriction', 'B', 'Indexes require functions that always produce the same value for the same input, a guarantee that only IMMUTABLE functions provide; STABLE is not sufficient.', 'ADVANCED', 3, 'MCQ', 1),
(1500, 45, 'WITH RECURSIVE t(n) AS (VALUES (1) UNION ALL SELECT n + 2 FROM t WHERE n < 6) — how many rows does t contain?', '3', '6', '4', '5', 'C', 'Starting from 1 and adding 2 while n < 6 produces the values 1, 3, 5 and then 7, so the CTE contains exactly 4 rows.', 'ADVANCED', 3, 'MCQ', 1),
(1501, 46, 'Which data model does MongoDB use to store records?', 'Relational model', 'Document model', 'Key-value model only', 'Graph model', 'B', 'MongoDB is a document database that stores each record as a document with named fields.', 'BEGINNER', 1, 'MCQ', 1),
(1502, 46, 'What does the acronym BSON stand for?', 'Binary JSON', 'Basic Simple Object Notation', 'Binary Structured Object Network', 'Big Serialized Object Node', 'A', 'BSON is short for Binary JSON, a binary-encoded serialization of JSON-like documents.', 'BEGINNER', 1, 'MCQ', 1),
(1503, 46, 'In MongoDB, where are documents stored?', 'In tables and rows', 'In key-value buckets', 'In collections', 'In object graphs', 'C', 'Documents are grouped and stored inside collections, which are analogous to tables in SQL.', 'BEGINNER', 1, 'MCQ', 1),
(1504, 46, 'What is the name of the required primary key field that every MongoDB document has?', 'id', '_id', 'key', 'pk', 'B', 'Every document contains an _id field which serves as its primary key.', 'BEGINNER', 1, 'MCQ', 1),
(1505, 46, 'What is the default BSON type generated for the _id field when it is not supplied?', 'String', 'Integer', 'UUID', 'ObjectId', 'D', 'MongoDB generates an ObjectId as the default _id value when none is provided.', 'BEGINNER', 1, 'MCQ', 1),
(1506, 46, 'Which of the following is true about MongoDB collections?', 'They do not enforce a fixed schema', 'Every document must have identical fields', 'Fields cannot be added later', 'Schemas must be declared before insert', 'A', 'Collections are schema-less, so documents in the same collection can have different fields.', 'BEGINNER', 1, 'MCQ', 1),
(1507, 46, 'Which category of NoSQL database does MongoDB belong to?', 'Wide-column store', 'Graph database', 'Document store', 'Pure key-value store', 'C', 'MongoDB is a document store that organizes data as BSON documents.', 'BEGINNER', 1, 'MCQ', 1),
(1508, 46, 'What is a single MongoDB server instance able to hold?', 'Multiple databases', 'Only one database', 'Only collections, no databases', 'One database and one collection', 'A', 'A MongoDB deployment can host multiple independent databases, each containing collections.', 'BEGINNER', 1, 'MCQ', 1),
(1509, 46, 'Compared to JSON, what advantage does BSON provide for MongoDB?', 'It is human readable text', 'It supports fewer data types', 'It cannot store binary data', 'It stores more data types and is binary-encoded', 'D', 'BSON adds extra types such as ObjectId, Date and binary data, and is compact and fast to scan.', 'BEGINNER', 1, 'MCQ', 1),
(1510, 46, 'Which MongoDB shell command switches to or selects a database?', 'use', 'select', 'open', 'cd', 'B', 'In the mongo shell, the ''use'' command selects a database, creating it lazily if needed.', 'BEGINNER', 1, 'MCQ', 1),
(1511, 46, 'What does an ObjectId consist of?', 'Only a random number', 'A UUID and a checksum', 'A 12-byte value with timestamp, machine ID, process ID and counter', 'A 16-byte MD5 hash', 'C', 'An ObjectId is 12 bytes combining a 4-byte timestamp, 5-byte random/machine value, 2-byte process ID and a 3-byte counter.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1512, 46, 'A document has a date field. Which BSON type should store it so that date-range queries work correctly?', 'Date', 'String', 'Integer', 'Boolean', 'A', 'The BSON Date type stores millisecond timestamps since the Unix epoch, enabling correct range comparisons.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1513, 46, 'If you insert a document without an _id field, what does MongoDB do?', 'Rejects the document', 'Stores it with a null _id', 'Throws a duplicate key error', 'Automatically generates an ObjectId', 'D', 'MongoDB automatically generates and inserts an ObjectId for the _id field when it is missing.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1514, 46, 'Two documents in the same collection have completely different fields. Is this valid?', 'No, all documents must match the collection schema', 'Yes, collections are schema-less', 'Only if both have an _id of the same type', 'Only during the development phase', 'B', 'Because collections are schema-less, documents with differing field sets are perfectly valid.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1515, 46, 'What is an embedded (nested) document?', 'A reference to a document in another collection', 'A document stored in a separate file', 'A document stored as a value of a field inside another document', 'A copy of the _id field', 'C', 'An embedded document is a sub-document stored as a field value, which suits one-to-one and one-to-many data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1516, 46, 'What is the maximum size of a single BSON document in MongoDB?', '16 megabytes', '1 megabyte', '64 megabytes', '4 gigabytes', 'A', 'The MongoDB document size limit is 16 MB, with larger data stored via GridFS.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1517, 46, 'What is a ''database'' in MongoDB from a filesystem perspective?', 'A single .db file', 'A directory of JSON files', 'A single collection file', 'A set of collection data files managed by the server', 'D', 'Each database maps to data files managed by the MongoDB server, typically in the dbpath directory.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1518, 46, 'When is a new collection actually created?', 'When the server starts', 'Lazily, on the first insert into it', 'When a database is created', 'Only when explicitly created with a schema', 'B', 'Collections are created lazily on first write, so no explicit creation command is required.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1519, 46, 'Which shell command shows the name of the current database?', 'db', 'show dbs', 'list db', 'current', 'A', 'Typing ''db'' in the shell prints the name of the current database being used.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1520, 46, 'Which BSON data type represents a true/false value?', 'Integer', 'NumberLong', 'Boolean', 'ObjectId', 'C', 'BSON includes a Boolean type for true and false values.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1521, 46, 'A user stores ISO strings for dates instead of the BSON Date type. What is the most likely consequence?', 'Queries become faster', 'Range and sort queries may behave incorrectly and waste storage', 'The _id can no longer be indexed', 'Documents exceed the 16 MB limit', 'B', 'Storing dates as strings prevents correct chronological ordering, making range and sort queries inaccurate.', 'ADVANCED', 3, 'MCQ', 1),
(1522, 46, 'Why does MongoDB prefer BSON over plain JSON for storage?', 'JSON is binary and faster', 'JSON supports ObjectId natively', 'JSON documents cannot be nested', 'BSON is binary-encoded and supports extra types for efficient traversal', 'D', 'BSON''s binary encoding and extra types (ObjectId, Date, Decimal128) make reads and writes faster and storage more compact.', 'ADVANCED', 3, 'MCQ', 1),
(1523, 46, 'When would an embedded (denormalized) document be a better choice than a reference?', 'When the child data is always fetched with the parent and changes rarely', 'When child documents grow without bound', 'When data must never be duplicated', 'When children are shared by many parents', 'A', 'Embedding is best for data that is accessed together with the parent and has bounded size, avoiding joins.', 'ADVANCED', 3, 'MCQ', 1),
(1524, 46, 'A legacy feature is accessed only during a migration. Why should the application still use the BSON type that matches the data?', 'It has no impact on the database', 'It only matters for _id values', 'Wrong types break indexing and query matching', 'Strings are never comparable', 'C', 'Query operators and indexes match values by BSON type, so inconsistent types can hide documents from queries.', 'ADVANCED', 3, 'MCQ', 1),
(1525, 46, 'What is the main reason ObjectId values are roughly sortable by creation time?', 'They include a UUID', 'The leading 4 bytes are a Unix timestamp', 'They are sequential integers', 'They contain a machine hash', 'B', 'Because the first 4 bytes of an ObjectId are the creation timestamp, ObjectIds are generally increasing over time.', 'ADVANCED', 3, 'MCQ', 1),
(1526, 46, 'Which approach would you choose to model a many-to-many relationship like ''student enrolled in many courses''?', 'Embed all course details inside each student', 'Store all students inside every course', 'Use a single field with the whole course', 'Store references in an array on either side', 'D', 'For many-to-many relationships, storing an array of references (course _ids) on the student avoids unbounded duplication.', 'ADVANCED', 3, 'MCQ', 1),
(1527, 46, 'Which field should hold a globally unique identifier for an entity that spans multiple collections?', '_id', 'name', 'createdAt', 'type', 'A', 'The _id field is the primary key and is guaranteed unique within a collection, so it should store the stable identifier.', 'ADVANCED', 3, 'MCQ', 1),
(1528, 46, 'Why would you store an audit log document with a large growing array?', 'It improves read performance', 'It avoids write amplification', 'It is usually a poor design because arrays can outgrow the 16 MB limit', 'It simplifies sharding', 'C', 'Unbounded arrays embedded in one document risk exceeding the 16 MB size cap, so logs are better stored as separate documents.', 'ADVANCED', 3, 'MCQ', 1),
(1529, 46, 'A business rule requires atomic updates across two collections. What should be considered?', 'It is always supported by a single update', 'Only read operations can be atomic', 'Embedding removes the need for transactions', 'Multi-document transactions may be needed', 'D', 'Updates spanning multiple documents require multi-document transactions rather than single-document atomicity.', 'ADVANCED', 3, 'MCQ', 1),
(1530, 46, 'What role does the 3-byte counter play inside an ObjectId?', 'It stores the server location', 'It ensures uniqueness for ObjectIds generated in the same second and machine', 'It stores the collection number', 'It is the checksum of the document', 'B', 'The counter distinguishes multiple ObjectIds generated within the same second by the same machine and process.', 'ADVANCED', 3, 'MCQ', 1),
(1531, 47, 'Which MongoDB method inserts a single document into a collection?', 'insertOne', 'insertMany', 'addOne', 'pushDoc', 'A', 'insertOne inserts exactly one document into the collection.', 'BEGINNER', 1, 'MCQ', 1),
(1532, 47, 'Which method inserts multiple documents in a single call?', 'insertOne', 'insertMany', 'insertAll', 'batchAdd', 'B', 'insertMany accepts an array of documents and inserts them in one operation.', 'BEGINNER', 1, 'MCQ', 1),
(1533, 47, 'Which update operator sets the value of a field?', '$inc', '$push', '$set', '$unset', 'C', '$set sets or overwrites the value of a specified field.', 'BEGINNER', 1, 'MCQ', 1),
(1534, 47, 'Which update operator removes a field from a document?', '$delete', '$drop', '$remove', '$unset', 'D', '$unset removes the specified field entirely from matching documents.', 'BEGINNER', 1, 'MCQ', 1),
(1535, 47, 'Which update operator increments a numeric field by a given amount?', '$add', '$inc', '$plus', '$increase', 'B', '$inc increases (or decreases with a negative value) a numeric field by the given amount.', 'BEGINNER', 1, 'MCQ', 1),
(1536, 47, 'Which update operator appends a value to an array field?', '$add', '$append', '$concat', '$push', 'D', '$push adds an element to the end of an array field.', 'BEGINNER', 1, 'MCQ', 1),
(1537, 47, 'Which method removes all documents that match a filter?', 'deleteMany', 'deleteOne', 'removeAll', 'dropMany', 'A', 'deleteMany deletes every document matching the filter, and with an empty filter deletes all documents.', 'BEGINNER', 1, 'MCQ', 1),
(1538, 47, 'Which comparison operator selects documents where a field is greater than a value?', '$gte', '$lt', '$gt', '$max', 'C', '$gt matches documents where the field value is strictly greater than the given value.', 'BEGINNER', 1, 'MCQ', 1),
(1539, 47, 'Which operator matches documents where a field value is in a given list?', '$like', '$any', '$within', '$in', 'D', '$in selects documents where the field equals any value in the supplied array.', 'BEGINNER', 1, 'MCQ', 1),
(1540, 47, 'Which operator selects documents where a field is not equal to a value?', '$notEqual', '$ne', '$neq', '$diff', 'B', '$ne matches documents where the field value is not equal to the given value.', 'BEGINNER', 1, 'MCQ', 1),
(1541, 47, 'Given db.orders.insertOne({item: ''pen'', qty: 5}), what is the value of qty in the stored document?', '0', 'null', '5', 'an array', 'C', 'The insert stores the document exactly as given, so qty remains 5 and an ObjectId is added to _id.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1542, 47, 'After running db.books.updateMany({price: 10}, {$inc: {price: 2}}), what is the new price of every matched book?', '12', '8', '10', '20', 'A', '$inc adds 2 to each matched price, turning 10 into 12.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1543, 47, 'What does db.products.updateOne({name: ''milk''}, {$set: {stock: 0}}) do to the matching document?', 'Deletes the name field', 'Adds 0 to the stock field', 'Replaces the whole document', 'Sets the stock field to 0', 'D', '$set writes the stock field to 0 without touching the rest of the document.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1544, 47, 'What does db.users.deleteMany({status: ''inactive''}) do?', 'Deletes the first inactive user only', 'Deletes every inactive user', 'Deactivates all users', 'Returns an error', 'B', 'deleteMany removes all documents whose status field equals ''inactive''.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1545, 47, 'Which find query returns documents whose age is between 18 and 30 inclusive of endpoints?', '{age: {$between: [18, 30]}}', '{age: {$eq: [18, 30]}}', '{age: {$gte: 18, $lte: 30}}', '{age: {$range: 18, 30}}', 'C', 'Combining $gte: 18 and $lte: 30 matches ages from 18 through 30 inclusive.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1546, 47, 'Which query finds documents where the name field starts with ''Al''?', '{name: /^Al/}', '{name: {$starts: ''Al''}}', '{name: $prefix(''Al'')}', '{name: {$begin: ''Al''}}', 'A', 'The regular expression /^Al/ matches strings beginning with ''Al''.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1547, 47, 'What does the projection db.users.find({}, {name: 1, _id: 0}) return?', 'Only the _id field', 'All fields', 'name and all other fields except _id', 'Only the name field', 'D', 'Setting name:1 includes name while _id:0 excludes _id, so only the name field is returned.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1548, 47, 'What does {$or: [{price: {$lt: 5}}, {stock: 0}]} as a filter return?', 'Documents that satisfy both conditions', 'Documents satisfying at least one condition', 'Documents that fail both conditions', 'Only documents with price less than 5', 'B', '$or returns documents matching any one of the listed conditions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1549, 47, 'When you call db.coll.find({}, {qty: 1, _id: 0}).sort({qty: -1}), how are results ordered?', 'Alphabetically', 'Randomly', 'By qty descending', 'By insertion order', 'C', 'sort({qty: -1}) orders the projected results by qty from highest to lowest.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1550, 47, 'Which operator checks whether a field exists and is not null?', '$exists', '$present', '$defined', '$has', 'A', '$exists: true matches documents where the field is present, and it also matches null values unless combined with $ne: null.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1551, 47, 'Given db.items.find({qty: {$in: [1, 5, 9]}}), which documents are returned?', 'Only documents with qty equal to 1', 'Documents whose qty is 1, 5 or 9', 'Documents with qty greater than 1', 'Documents with qty in an array', 'B', '$in matches any document whose qty value equals any element in the array [1, 5, 9].', 'ADVANCED', 3, 'MCQ', 1),
(1552, 47, 'What is the effect of an upsert when no document matches the filter?', 'Nothing happens', 'An error is returned', 'The filter is ignored', 'A new document is inserted combining the filter and update', 'D', 'With upsert: true, MongoDB inserts a new document built from the query filter and the update operators when no match exists.', 'ADVANCED', 3, 'MCQ', 1),
(1553, 47, 'What happens if you use $push on a field that holds a scalar number?', 'The update fails with an error', 'The number is converted to an array', 'The number is ignored', 'A new document is created', 'A', '$push requires an array field; applying it to a scalar produces an update error.', 'ADVANCED', 3, 'MCQ', 1),
(1554, 47, 'Given db.logs.deleteMany({}), what does this operation accomplish?', 'Deletes only the first log', 'Returns an error', 'Deletes every document in the collection', 'Deletes the database', 'C', 'An empty filter matches all documents, so deleteMany({}) removes every document from the collection.', 'ADVANCED', 3, 'MCQ', 1),
(1555, 47, 'db.students.updateOne({id: 7}, {$setOnInsert: {enrolled: true}}, {upsert: true}) - when is enrolled set?', 'Only when a match already exists', 'Only when the document is newly inserted', 'Always, on every call', 'Never', 'B', '$setOnInsert applies its fields only during an insert triggered by upsert, never on updates of existing documents.', 'ADVANCED', 3, 'MCQ', 1),
(1556, 47, 'Which filter finds documents where the embedded field ''address.city'' equals ''Lagos''?', '{address: ''Lagos''}', '{city: ''Lagos''}', '{$embed: {city: ''Lagos''}}', '{''address.city'': ''Lagos''}', 'D', 'Dot notation ''address.city'' targets the city field inside the embedded address document.', 'ADVANCED', 3, 'MCQ', 1),
(1557, 47, 'How would you match documents where the ''total'' field is greater than the ''tax'' field using $expr?', '{$expr: {$gt: [''$total'', ''$tax'']}}', '{$gt: {total: ''$tax''}}', '{$where: ''total > tax''}', '{$expr: total > tax}', 'A', '$expr with $gt: [''$total'', ''$tax''] compares the values of the two fields inside each document.', 'ADVANCED', 3, 'MCQ', 1),
(1558, 47, 'Why might insertMany with ordered: false be preferred for bulk loading?', 'It is the only valid option', 'It always fails fast', 'It continues inserting other documents when one fails', 'It bypasses the 16 MB limit', 'C', 'With ordered: false, MongoDB continues processing remaining documents even if some inserts fail.', 'ADVANCED', 3, 'MCQ', 1),
(1559, 47, 'db.c.updateOne({_id: 1}, {$set: {tags: [''red'', ''blue'']}}); what is the type of tags?', 'A string', 'An array', 'A nested document', 'A set', 'B', 'The $set operator stores the array literal [''red'', ''blue''] as an array field.', 'ADVANCED', 3, 'MCQ', 1),
(1560, 47, 'Given db.parts.find({sku: {$exists: true, $ne: null}}), which documents match?', 'Only documents where sku equals null', 'Only documents where sku is missing', 'Documents with any sku value including null', 'Documents where sku exists and is not null', 'D', 'Combining $exists: true with $ne: null selects documents that have the sku field with a non-null value.', 'ADVANCED', 3, 'MCQ', 1),
(1561, 48, 'Which aggregation stage filters documents before they are passed to the next stage?', '$match', '$group', '$filter', '$where', 'A', '$match filters the stream of documents using a query condition, similar to find filters.', 'BEGINNER', 1, 'MCQ', 1),
(1562, 48, 'Which stage groups documents together to compute aggregate values?', '$sort', '$group', '$collect', '$bucket', 'B', '$group accumulates documents sharing the same _id key and computes values with accumulators.', 'BEGINNER', 1, 'MCQ', 1),
(1563, 48, 'Which stage controls which fields appear in the output documents?', '$select', '$pick', '$project', '$fields', 'C', '$project includes, excludes or computes fields in each output document.', 'BEGINNER', 1, 'MCQ', 1),
(1564, 48, 'Which stage orders the documents in the pipeline?', '$order', '$arrange', '$rank', '$sort', 'D', '$sort orders documents by the specified field and direction.', 'BEGINNER', 1, 'MCQ', 1),
(1565, 48, 'Which stage limits the number of documents passed through the pipeline?', '$limit', '$cap', '$max', '$cut', 'A', '$limit passes only the first N documents to the next stage.', 'BEGINNER', 1, 'MCQ', 1),
(1566, 48, 'Which stage performs a left outer join between two collections?', '$join', '$union', '$lookup', '$merge', 'C', '$lookup adds fields from another collection based on a matching local and foreign field.', 'BEGINNER', 1, 'MCQ', 1),
(1567, 48, 'Which stage deconstructs an array field into multiple documents?', '$split', '$array', '$flatten', '$unwind', 'D', '$unwind outputs one document per element of the array field.', 'BEGINNER', 1, 'MCQ', 1),
(1568, 48, 'Which accumulator computes the sum of numeric field values in $group?', '$sum', '$total', '$add', '$count', 'A', '$sum adds together the numeric values of a field (or the value 1 for each document).', 'BEGINNER', 1, 'MCQ', 1),
(1569, 48, 'Which accumulator computes the average of numeric values in $group?', '$mean', '$avg', '$average', '$mid', 'B', '$avg returns the arithmetic mean of the numeric values for the group.', 'BEGINNER', 1, 'MCQ', 1),
(1570, 48, 'Which accumulator collects field values into an array within a $group stage?', '$toArray', '$collect', '$push', '$array', 'C', '$push appends the value of the specified field for each document into an array.', 'BEGINNER', 1, 'MCQ', 1),
(1571, 48, 'Why should $match be placed as early as possible in a pipeline?', 'It removes duplicate documents', 'It reduces the number of documents the later stages must process', 'It is required to be first', 'It creates indexes', 'B', 'Early $match minimizes the document count flowing through later stages, improving efficiency.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1572, 48, 'What does db.coll.aggregate([{$group: {_id: null, total: {$sum: 1}}}]) return?', 'One document per input document', 'An error', 'A single document with a count of all documents', 'A list of unique ids', 'C', 'Grouping by _id: null puts all documents in one group and $sum: 1 counts them.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1573, 48, 'What does {$group: {_id: ''$category'', n: {$sum: 1}}} produce for each category?', 'One document per distinct category with a count', 'A count of all categories in one document', 'A sorted list of categories', 'An array of documents', 'A', 'Grouping on $category creates one output document per distinct category, with n equal to the number of documents in it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1574, 48, 'How do you include the _id field as well as other fields in a $project?', 'Write all fields with 0', 'Only use $addFields', 'Use {$include: all}', 'List fields with 1 and exclude _id with 0 if not wanted', 'D', '$project includes fields set to 1; _id is included by default and must be set to 0 to exclude it.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1575, 48, 'Which pipeline would return the 3 most expensive products?', '[{$sort: {price: 1}}, {$limit: 3}]', '[{$sort: {price: -1}}, {$limit: 3}]', '[{$limit: 3}, {$sort: {price: 1}}]', '[{$match: {price: -1}}, {$limit: 3}]', 'B', 'Sorting price descending with $sort: -1 then limiting to 3 keeps the three highest-priced products.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1576, 48, 'In {$lookup: {from: ''orders'', localField: ''_id'', foreignField: ''custId'', as: ''orders''}}, what is ''orders''?', 'The foreign collection name', 'The join key', 'The output array field added to each input document', 'A database name', 'C', 'The ''as'' field names the array added to each input document, containing the matched foreign documents.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1577, 48, 'db.arr.aggregate([{$unwind: ''$items''}]) - how many output documents are produced from a document with a 4-element items array?', '4', '1', '0', '8', 'A', '$unwind creates one output document per array element, so a 4-element array yields 4 documents.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1578, 48, 'What is the output of {$group: {_id: ''$dept'', avgSal: {$avg: ''$salary''}}}?', 'The total salary per department', 'The number of employees per department', 'The maximum salary per department', 'The average salary per department', 'D', '$avg computes the mean of salary values for each dept group and labels it avgSal.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1579, 48, 'Which stage computes a new field without removing existing fields?', '$project', '$addFields', '$compute', '$setField', 'B', '$addFields adds or overwrites fields while preserving all existing fields in the output.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1580, 48, 'What does placing $sort after $group do to the group output?', 'Nothing', 'Sorts the input before grouping', 'Orders the grouped result documents', 'Limits the groups', 'C', '$sort after $group reorders the documents produced by the grouping stage.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1581, 48, 'Predict the result of db.orders.aggregate([{$match: {status: ''shipped''}}, {$group: {_id: ''$customer'', total: {$sum: ''$amount''}}}]).', 'One document per shipped customer with the sum of their shipped amounts', 'One document per order with its amount', 'A single total for all shipped orders', 'Only orders that are not shipped', 'A', 'The pipeline first keeps only shipped orders, then groups by customer summing the amount of each.', 'ADVANCED', 3, 'MCQ', 1),
(1582, 48, 'In a $lookup, what does the foreignField reference?', 'A field in the local collection', 'An output field name', 'A field in the foreign collection', 'A database name', 'C', 'foreignField names the field in the ''from'' collection that is matched against localField.', 'ADVANCED', 3, 'MCQ', 1),
(1583, 48, 'What does {$group: {_id: {year: {$year: ''$date''}, month: {$month: ''$date''}}, sales: {$sum: ''$amount''}}} group by?', 'Only the year', 'Only the month', 'The exact date', 'The combined year and month pair', 'D', 'A compound _id with year and month groups documents by the distinct (year, month) combination.', 'ADVANCED', 3, 'MCQ', 1),
(1584, 48, 'Given db.scores.aggregate([{$project: {name: 1, doubled: {$multiply: [''$score'', 2]}}}]), what is ''doubled''?', 'The original score', 'The score multiplied by 2', 'An array of scores', 'The sum of all scores', 'B', '$multiply computes score times 2, producing a new computed field named doubled.', 'ADVANCED', 3, 'MCQ', 1),
(1585, 48, 'What does $unwind: {path: ''$tags'', preserveNullAndEmptyArrays: true} do for documents with no tags field?', 'Keeps them as-is with tags absent', 'Drops them', 'Creates tags: null for them', 'Returns an error', 'A', 'preserveNullAndEmptyArrays: true keeps documents whose array is missing or empty instead of dropping them.', 'ADVANCED', 3, 'MCQ', 1),
(1586, 48, 'Which pipeline computes a global rank of customers by total spend then adds it to each order?', 'A single $group stage', 'A $sort followed by $group', 'A $group, then $sort, then $setWindowFields (rank)', 'Only a $match', 'C', '$setWindowFields with rank computes the ranking across groups after aggregation.', 'ADVANCED', 3, 'MCQ', 1),
(1587, 48, 'Predict db.sales.aggregate([{$match: {region: ''EU''}}, {$sort: {amount: -1}}, {$limit: 2}]).', 'All EU sales sorted ascending', 'Only the largest EU sale', 'Two random EU sales', 'The two highest-amount EU sales', 'D', '$match keeps EU sales, $sort orders by amount descending, and $limit keeps the top 2.', 'ADVANCED', 3, 'MCQ', 1),
(1588, 48, 'db.events.aggregate([{$unwind: ''$hits''}]) followed by {$group: {_id: ''$hits'', count: {$sum: 1}}} - what is the output?', 'Total hits across all events', 'A count per distinct hit value', 'The average hits per event', 'One document per event', 'B', 'After unwinding, grouping on $hits counts how often each hit value occurs across all events.', 'ADVANCED', 3, 'MCQ', 1),
(1589, 48, 'Which output does {$project: {total: {$add: [''$base'', ''$tax'']}, _id: 0}} produce?', 'Documents with only a computed total field', 'All fields plus total', 'Only base and tax', 'An empty document', 'A', '$add sums base and tax into the new field total and _id: 0 removes the default _id.', 'ADVANCED', 3, 'MCQ', 1),
(1590, 48, 'In a pipeline joining orders to customers, which stage pairing effectively flattens the joined arrays?', '$group then $match', '$lookup then $limit', '$lookup then $unwind', '$sort then $lookup', 'C', '$lookup produces an array field, and $unwind on that field flattens each joined document into its own output document.', 'ADVANCED', 3, 'MCQ', 1),
(1591, 49, 'What is the main purpose of an index in MongoDB?', 'To speed up query and sort operations', 'To encrypt documents', 'To compress data', 'To validate schemas', 'A', 'Indexes let MongoDB avoid full collection scans by providing efficient paths to matching documents.', 'BEGINNER', 1, 'MCQ', 1),
(1592, 49, 'Which method creates an index on a collection?', 'addIndex', 'createIndex', 'makeIndex', 'newIndex', 'B', 'createIndex defines an index on the specified field(s) with the given options.', 'BEGINNER', 1, 'MCQ', 1),
(1593, 49, 'What does a single-field index {price: 1} mean?', 'Price is indexed in descending order', 'Only one document can have a price', 'Price is indexed in ascending order', 'Price cannot be changed', 'C', 'The value 1 indicates an ascending index on the price field.', 'BEGINNER', 1, 'MCQ', 1),
(1594, 49, 'What is a compound index?', 'An index on two or more fields', 'An index that combines two collections', 'An index on an array', 'Two separate indexes on one field', 'A', 'A compound index is a single index covering multiple fields, such as {lastName: 1, firstName: 1}.', 'BEGINNER', 1, 'MCQ', 1),
(1595, 49, 'What type of index is created with createIndex({content: ''text''})?', 'A unique index', 'A TTL index', 'A sparse index', 'A text index', 'D', 'The ''text'' type builds a text index that enables $text search on the content field.', 'BEGINNER', 1, 'MCQ', 1),
(1596, 49, 'What does a unique index enforce?', 'Only one index per collection', 'That values are sorted', 'That indexed field values are unique across the collection', 'That the index never changes', 'C', 'A unique index rejects any insert or update that would create a duplicate indexed value.', 'BEGINNER', 1, 'MCQ', 1),
(1597, 49, 'Which index exists by default on every collection?', 'A text index', 'The _id index', 'A compound index', 'A TTL index', 'B', 'MongoDB automatically creates a unique index on the _id field of every collection.', 'BEGINNER', 1, 'MCQ', 1),
(1598, 49, 'What does the explain() method provide?', 'A list of collections', 'A backup plan', 'A schema snapshot', 'The query plan chosen for a query', 'D', 'explain() reports how MongoDB executed a query, including the index used and documents examined.', 'BEGINNER', 1, 'MCQ', 1),
(1599, 49, 'What is a TTL index used for?', 'Automatically deleting documents after a set time', 'Speeding up text search', 'Storing time series data', 'Encrypting date fields', 'A', 'A TTL index lets MongoDB expire and remove documents whose date field is older than a specified interval.', 'BEGINNER', 1, 'MCQ', 1),
(1600, 49, 'What is a downside of adding many indexes?', 'Queries become slower', 'Indexes take no space', 'Writes become slower and storage grows', 'Indexes cannot be removed', 'C', 'Each index must be maintained on every write and consumes disk space, slowing inserts and updates.', 'BEGINNER', 1, 'MCQ', 1),
(1601, 49, 'Given the index {a: 1, b: 1}, which of these queries can use the index for equality on both fields?', 'Only queries on b', 'Queries filtering on a, and on both a and b', 'Queries sorting only on b', 'Queries using $or on a', 'B', 'A compound index supports queries that match on its leftmost prefix, i.e., a alone or a followed by b.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1602, 49, 'What happens when you insert a document that violates a unique index?', 'The document is stored and the index drops it', 'The whole collection is dropped', 'The document replaces an existing one', 'The insert fails with a duplicate key error', 'D', 'A unique index violation causes the insert or update to fail with a duplicate key error.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1603, 49, 'Without a suitable index, what must MongoDB do to answer a large find()?', 'Scan every document in the collection', 'Skip half the documents', 'Return no results', 'Use a text index', 'A', 'Without an index MongoDB performs a collection scan, reading each document to check the filter.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1604, 49, 'What does a covered query mean?', 'The query matches no documents', 'The query uses a text index', 'All needed fields come from the index alone, without reading documents', 'The query is hidden from the profiler', 'C', 'A covered query can be satisfied entirely from index entries, so MongoDB never reads the documents themselves.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1605, 49, 'Which field type is required for a TTL index to work?', 'A string date', 'A BSON Date or array of dates', 'A timestamp stored as text', 'An integer', 'B', 'TTL indexes require a BSON Date field (or an array of dates) whose earliest value determines expiration.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1606, 49, 'How do you create a unique index on the email field?', 'db.coll.unique(''email'')', 'db.coll.index(''email'', {unique: true})', 'db.coll.addUnique(''email'')', 'db.coll.createIndex({email: 1}, {unique: true})', 'D', 'createIndex with the unique option set to true enforces uniqueness on the indexed field.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1607, 49, 'Which query operator can prevent an index from being used efficiently?', '$regex with a leading wildcard', '$gte on an indexed field', '$in on an indexed field', '$eq on an indexed field', 'A', 'A $regex that begins with a wildcard cannot use the index and forces a scan, unlike anchored patterns.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1608, 49, 'What is index selectivity?', 'The order of index creation', 'The storage size of an index', 'How many distinct values an indexed field has relative to documents', 'The speed of index creation', 'C', 'High selectivity means the index values narrow results to few documents, making the index more effective.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1609, 49, 'Which command shows the statistics and keys of an existing index?', 'db.coll.indexesInfo()', 'db.coll.getIndexes()', 'db.coll.listIndexNames()', 'db.coll.showIndex()', 'B', 'getIndexes returns details of every index on a collection, including key patterns and options.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1610, 49, 'An index on an array field is called what?', 'A compound index', 'A text index', 'A sparse index', 'A multikey index', 'D', 'Indexing an array field creates a multikey index with one entry per array element.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1611, 49, 'Why does field order matter in a compound index like {a: 1, b: 1}?', 'Order affects only the index name', 'Equality on a then range on b is supported, but a range on a prevents efficient use of b', 'It only matters for unique indexes', 'Order never matters', 'B', 'Compound index order determines which prefix queries can use; a range on the leading field limits the rest.', 'ADVANCED', 3, 'MCQ', 1),
(1612, 49, 'What does the winningPlan vs rejectedPlans in explain() output show?', 'The number of indexes', 'The database size', 'The query time', 'Which index plan was chosen and which were considered but rejected', 'D', 'explain() compares candidate plans, showing the winning plan and the rejected ones for the query.', 'ADVANCED', 3, 'MCQ', 1),
(1613, 49, 'What is a partial index?', 'An index that only includes documents matching a filter', 'An index on part of a field', 'An index that is partially built', 'An index with missing keys', 'A', 'A partial index indexes only documents satisfying a filter expression, saving space and speeding writes.', 'ADVANCED', 3, 'MCQ', 1),
(1614, 49, 'When might MongoDB intentionally choose a collection scan even with an index available?', 'Never', 'When the index is unique', 'When the collection is very small or the index has low selectivity', 'When using only $eq', 'C', 'For tiny collections or low-selectivity indexes, scanning may be cheaper than using the index.', 'ADVANCED', 3, 'MCQ', 1),
(1615, 49, 'What is the difference between a sparse and a partial index?', 'They are identical', 'A sparse index includes only documents with the indexed field; a partial index uses a filter expression', 'Sparse indexes are faster', 'Partial indexes cannot be unique', 'B', 'Sparse indexes skip documents missing the indexed field, while partial indexes include documents matching an explicit filter.', 'ADVANCED', 3, 'MCQ', 1),
(1616, 49, 'Why should a sort field be indexed for large result sets?', 'It makes the sort random', 'It is never needed', 'It reduces memory only', 'It avoids an in-memory sort that may exceed the 100 MB limit', 'D', 'With an index matching the sort order, MongoDB streams results in order instead of sorting in memory, avoiding the 100 MB cap.', 'ADVANCED', 3, 'MCQ', 1),
(1617, 49, 'How would you create a text index on the ''title'' and ''description'' fields for $text search?', 'db.coll.createIndex({title: ''text'', description: ''text''})', 'db.coll.createIndex({title: 1, description: 1})', 'db.coll.createTextIndex(''title'')', 'db.coll.index({title: ''string''})', 'A', 'Creating a text index requires the ''text'' type on each field; then $text searches them together.', 'ADVANCED', 3, 'MCQ', 1),
(1618, 49, 'Which command removes an index from a collection?', 'deleteIndex', 'removeIndex', 'dropIndex', 'clearIndex', 'C', 'dropIndex removes a single index by name or key pattern.', 'ADVANCED', 3, 'MCQ', 1),
(1619, 49, 'What causes ''jumbo chunks'' to become a problem in sharded collections?', 'Too many collections', 'Low cardinality or unevenly distributed shard key values create chunks too large to split', 'Text indexes in sharded clusters', 'The number of mongos routers', 'B', 'Jumbo chunks are chunks that cannot be split or migrated because their shard key range has grown too large.', 'ADVANCED', 3, 'MCQ', 1),
(1620, 49, 'Why are indexes with high cardinality preferred as the leading field of a compound index?', 'They consume less memory', 'They are easier to create', 'They can be used for text search', 'They narrow the result set more effectively', 'D', 'A leading field with many distinct values lets the index eliminate most documents early, improving query performance.', 'ADVANCED', 3, 'MCQ', 1),
(1621, 50, 'What is a MongoDB replica set?', 'A group of mongod processes that maintain the same data set', 'A single server holding all data', 'A backup tape', 'A collection of indexes', 'A', 'A replica set is a cluster of mongod nodes that replicate the same data for high availability.', 'BEGINNER', 1, 'MCQ', 1),
(1622, 50, 'Which node in a replica set accepts all write operations?', 'Secondary', 'Primary', 'Arbiter', 'Config server', 'B', 'The primary is the only member that accepts writes; secondaries replicate from it.', 'BEGINNER', 1, 'MCQ', 1),
(1623, 50, 'What role do secondary nodes play in a replica set?', 'They reject all traffic', 'They only store config metadata', 'They replicate the primary''s data and can serve reads', 'They compress the database', 'C', 'Secondaries copy the primary''s oplog and can serve read operations depending on read preference.', 'BEGINNER', 1, 'MCQ', 1),
(1624, 50, 'What is an arbiter in a replica set?', 'A node that holds a full copy of data', 'A node that acts as primary', 'A mongos router', 'A node that votes in elections but stores no data', 'D', 'An arbiter participates in elections by voting but holds no data, so it cannot become primary.', 'BEGINNER', 1, 'MCQ', 1),
(1625, 50, 'What happens when the primary of a replica set fails?', 'An automatic election promotes a secondary to primary', 'The cluster stops forever', 'Writes are lost', 'An arbiter takes over data', 'A', 'When the primary becomes unreachable, the remaining nodes hold an election and promote one secondary to primary.', 'BEGINNER', 1, 'MCQ', 1),
(1626, 50, 'What is sharding in MongoDB?', 'Encrypting data at rest', 'Distributing data across multiple servers', 'Backing up the database', 'Compressing documents', 'B', 'Sharding partitions a collection''s data across many mongod servers so it can scale horizontally.', 'BEGINNER', 1, 'MCQ', 1),
(1627, 50, 'What is a mongos process responsible for?', 'Storing all data', 'Voting in elections', 'Routing queries and writes to the correct shard', 'Expiring documents', 'C', 'mongos is the router that presents a unified view and forwards operations to the appropriate shards.', 'BEGINNER', 1, 'MCQ', 1),
(1628, 50, 'What is a shard key?', 'The encryption key for data', 'The index of the _id field', 'A mongos password', 'A field MongoDB uses to distribute documents across shards', 'D', 'The shard key determines how documents are distributed among shards via its value ranges.', 'BEGINNER', 1, 'MCQ', 1),
(1629, 50, 'What is a chunk in a sharded cluster?', 'A replica set member', 'A contiguous range of shard key values stored on a shard', 'A group of databases', 'An index entry', 'B', 'Chunks are ranges of shard key values; MongoDB balances them across shards as data grows.', 'BEGINNER', 1, 'MCQ', 1),
(1630, 50, 'What does a write concern specify?', 'How many members must acknowledge a write before it succeeds', 'Which shard receives the write', 'The encryption of the write', 'The index used for the write', 'A', 'Write concern defines the level of acknowledgment required, such as majority or a number of nodes.', 'BEGINNER', 1, 'MCQ', 1),
(1631, 50, 'Which read preference directs all reads to secondary members of a replica set?', 'primary', 'secondary', 'nearest', 'primaryPreferred', 'C', 'readPreference ''secondary'' sends reads to secondary members only, reducing primary load but risking stale data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1632, 50, 'What is the minimum recommended number of data-bearing members for a replica set?', '1', '3', '5', '7', 'B', 'Three members (or two plus an arbiter) provide redundancy and can still elect a primary if one fails.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1633, 50, 'What does a write concern of w: ''majority'' require?', 'Acknowledgment from a majority of voting members', 'Acknowledgment from the primary only', 'Acknowledgment from every member', 'Acknowledgment from the arbiter', 'A', 'w: ''majority'' requires that more than half of the voting members acknowledge the write before it is confirmed.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1634, 50, 'When a primary fails and a secondary is elected, what is this process called?', 'Sharding', 'Compaction', 'Failback', 'Failover', 'D', 'Failover is the automatic transfer of primary status to another member following a primary outage.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1635, 50, 'Why is a high-cardinality shard key preferred?', 'It reduces index size', 'It spreads data evenly across shards', 'It speeds up mongos routing', 'It prevents the need for indexes', 'B', 'A shard key with many distinct values distributes documents evenly, preventing hotspots on one shard.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1636, 50, 'What is a hashed shard key useful for?', 'Evenly distributing data when natural ranges would create hotspots', 'Ordered range scans', 'Text search', 'TTL expiry', 'A', 'Hashing the shard key randomizes ranges so writes spread evenly, at the cost of efficient range scans.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1637, 50, 'What role do config servers play in a sharded cluster?', 'They store actual data', 'They route queries', 'They store cluster metadata such as chunk ranges', 'They vote for primary', 'C', 'Config servers store metadata describing shards, databases and chunk distributions.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1638, 50, 'Which components make up a minimal sharded cluster?', 'One mongod', 'A replica set only', 'A mongos only', 'Shards, a mongos router and config servers', 'D', 'A sharded cluster needs shards (replica sets), at least one mongos router and config servers.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1639, 50, 'What happens to a chunk when it exceeds the configured chunk size?', 'It is deleted', 'It is split into smaller chunks and balanced', 'It moves to the config server', 'It is compressed', 'B', 'Chunks that outgrow the size threshold are split, and the balancer migrates them across shards.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1640, 50, 'What is the maximum number of members in a replica set and the maximum voting members?', '50 members with up to 7 voting', '30 members with 10 voting', '100 members with 5 voting', '7 members with 50 voting', 'A', 'A replica set supports at most 50 members, of which no more than 7 may vote in elections.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1641, 50, 'A write is acknowledged with w: ''majority'' and j: true. What does j: true add?', 'Faster acknowledgment', 'That the write is flushed to the journal before acknowledgment', 'That every secondary must write to disk', 'That the write is sharded', 'B', 'j: true requires the write to be durably recorded in the journal before the write is acknowledged.', 'ADVANCED', 3, 'MCQ', 1),
(1642, 50, 'What is the difference between read concern and write concern?', 'They are identical', 'Read concern controls failover speed', 'Write concern controls which index is used', 'Read concern controls read consistency and visibility; write concern controls write acknowledgment', 'D', 'Read concern governs how current the data read must be, while write concern governs write acknowledgment and durability.', 'ADVANCED', 3, 'MCQ', 1),
(1643, 50, 'Which read preference prefers the primary but falls back to secondaries if it is unavailable?', 'primaryPreferred', 'secondary', 'secondaryPreferred', 'nearest', 'A', 'primaryPreferred reads from the primary when possible and otherwise from secondaries.', 'ADVANCED', 3, 'MCQ', 1),
(1644, 50, 'During a failover, roughly how long does it typically take for a new primary to be elected?', 'Instantly with no delay', 'About 60 seconds minimum', 'A few seconds, often up to the electionTimeoutMillis setting', 'Several hours', 'C', 'The default electionTimeoutMillis of 10 seconds bounds how long the cluster takes to detect a primary failure and elect a new one.', 'ADVANCED', 3, 'MCQ', 1),
(1645, 50, 'What problem arises when a shard key has very low cardinality (few distinct values)?', 'Queries become slower', 'Chunks become large and uneven, causing hotspots', 'Indexes stop working', 'mongos cannot route', 'B', 'With few distinct key values, only a few chunks exist, so data concentrates on one shard and creates hotspots.', 'ADVANCED', 3, 'MCQ', 1),
(1646, 50, 'Why is a monotonically increasing shard key (like a timestamp) a poor choice?', 'It is hard to index', 'It cannot be hashed', 'It uses too much memory', 'New writes always target the same high-end chunk, creating a hotspot', 'D', 'Monotonic keys concentrate inserts at the end of the key range, overloading the shard holding that chunk.', 'ADVANCED', 3, 'MCQ', 1),
(1647, 50, 'What are zone-based sharding (tags) used for?', 'Pinning ranges of shard key values to specific shards for locality', 'Encrypting shard data', 'Reducing replica set size', 'Replacing config servers', 'A', 'Tags and zones let you associate shard key ranges with specific shards, e.g., keeping a region''s data close to its users.', 'ADVANCED', 3, 'MCQ', 1),
(1648, 50, 'What does the balancer do in a sharded cluster?', 'It votes for primaries', 'It compresses data', 'It migrates chunks between shards to keep them balanced', 'It routes queries', 'C', 'The balancer continually moves chunks so that no shard holds a disproportionate share of data.', 'ADVANCED', 3, 'MCQ', 1),
(1649, 50, 'A company runs a 3-member replica set with two data nodes and one arbiter. What is a key trade-off?', 'Arbiters hold full data copies', 'If a data node fails, availability is lower and the surviving node is a single point of failure', 'Arbiters become primary', 'Writes are automatically durable', 'B', 'Two data nodes plus an arbiter gives only one copy of data after a failure, reducing redundancy compared with three data nodes.', 'ADVANCED', 3, 'MCQ', 1),
(1650, 50, 'Why does MongoDB write to the oplog on the primary?', 'To compress data', 'To vote in elections', 'To balance chunks', 'So secondaries can replicate the same operations', 'D', 'The primary records every operation in the oplog, which secondaries tail and replay to keep data in sync.', 'ADVANCED', 3, 'MCQ', 1);
INSERT INTO questions (question_id, topic_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, marks, question_type, is_active) VALUES
(1651, 241, 'What is a data warehouse?', 'A centralized repository optimized for analysis and reporting', 'A single operational transaction table', 'A backup tape', 'A web server', 'A', 'A data warehouse stores integrated historical data specifically for analysis.', 'BEGINNER', 1, 'MCQ', 1),
(1652, 241, 'What does OLTP stand for?', 'Online Transaction Processing', 'Online Time Processing', 'Offline Transaction Program', 'Object Linked Transfer Protocol', 'A', 'OLTP systems handle day-to-day transactional operations.', 'BEGINNER', 1, 'MCQ', 1),
(1653, 241, 'What does OLAP stand for?', 'Online Analytical Processing', 'Online Application Program', 'Offline Analysis Process', 'Object Linked Application Protocol', 'A', 'OLAP supports complex analysis and reporting on aggregated data.', 'BEGINNER', 1, 'MCQ', 1),
(1654, 241, 'Which of the following is a characteristic of a data warehouse?', 'Subject-oriented and time-variant', 'Only stores current transactions', 'Designed for high-frequency updates', 'Holds normalized operational data', 'A', 'Data warehouses are subject-oriented, integrated, non-volatile, and time-variant.', 'BEGINNER', 1, 'MCQ', 1),
(1655, 241, 'What is a star schema?', 'A dimensional model with a central fact table and surrounding dimension tables', 'A relational diagram of tables', 'A database backup', 'A report layout', 'A', 'The star schema connects fact tables to denormalized dimension tables.', 'BEGINNER', 1, 'MCQ', 1),
(1656, 241, 'In a star schema, a fact table typically stores:', 'Measures and foreign keys to dimensions', 'Only dimension attributes', 'Raw text logs', 'User passwords', 'A', 'Fact tables contain numeric measures and references to dimension tables.', 'BEGINNER', 1, 'MCQ', 1),
(1657, 241, 'What is a dimension table?', 'A table storing descriptive attributes for analysis', 'A table of numeric measures', 'A log file', 'A backup table', 'A', 'Dimensions hold descriptive context such as time, product, or customer.', 'BEGINNER', 1, 'MCQ', 1),
(1658, 241, 'Which architecture places a data warehouse between operational systems and analytics?', 'Three-tier architecture', 'Two-tier only', 'Peer-to-peer', 'Single tier', 'A', 'Three-tier architecture separates source, warehouse, and front-end layers.', 'BEGINNER', 1, 'MCQ', 1),
(1659, 241, 'What does ETL stand for?', 'Extract, Transform, Load', 'Execute, Test, Launch', 'Edit, Type, Link', 'Encode, Transfer, Log', 'A', 'ETL is the process of extracting, transforming, and loading data into a warehouse.', 'BEGINNER', 1, 'MCQ', 1),
(1660, 241, 'What is a data mart?', 'A focused subset of a data warehouse for one department', 'A data warehouse replacement', 'A type of OLTP database', 'A backup server', 'A', 'Data marts serve specific business areas with a subset of warehouse data.', 'BEGINNER', 1, 'MCQ', 1),
(1661, 241, 'Which schema has dimension tables organized in a hierarchy resembling a snowflake?', 'Snowflake schema', 'Star schema', 'Flat schema', 'Wide table', 'A', 'The snowflake schema normalizes dimensions into related sub-tables.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1662, 241, 'What is the main difference between a star and a snowflake schema?', 'Snowflake normalizes dimensions; star denormalizes them', 'Star has more levels', 'Snowflake has no facts', 'They are identical', 'A', 'Snowflake schemas reduce redundancy by normalizing dimensions at the cost of more joins.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1663, 241, 'Which of the following is an example of a measure in a fact table?', 'Total sales amount', 'Product name', 'Customer city', 'Order ID only', 'A', 'Measures are numeric facts such as sales amount that are aggregated.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1664, 241, 'What does ''non-volatile'' mean in a data warehouse context?', 'Data is not modified once loaded', 'Data changes every second', 'Data is deleted nightly', 'Data is volatile memory', 'A', 'Once loaded, warehouse data remains stable and is only refreshed periodically.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1665, 241, 'Which layer of a data warehouse architecture handles cleansing and integration?', 'The staging layer', 'The presentation layer', 'The reporting layer', 'The source layer', 'A', 'The staging area is where extraction, cleaning, and transformation occur.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1666, 241, 'What is a surrogate key?', 'An artificial key used to uniquely identify rows in a warehouse', 'The natural business key', 'A foreign key', 'A primary key of source systems', 'A', 'Surrogate keys are system-generated identifiers independent of source data.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1667, 241, 'Which of the following is a benefit of a data warehouse?', 'Consistent, integrated views for analysis', 'Faster transaction processing', 'Less storage used', 'Replacing all source systems', 'A', 'Warehouses integrate data for consistent reporting and analysis.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1668, 241, 'What is the role of a conformed dimension?', 'A shared dimension used consistently across data marts', 'A dimension unique to one report', 'A fact table', 'A backup table', 'A', 'Conformed dimensions enable consistent analysis across the enterprise.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1669, 241, 'Which of the following best describes a factless fact table?', 'A fact table with relationships but no numeric measures', 'A table with only numbers', 'A dimension table', 'An empty table', 'A', 'Factless facts record events or relationships without numeric measures.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1670, 241, 'What is the purpose of aggregate tables in a warehouse?', 'To speed up queries by pre-summarizing data', 'To store raw transactions only', 'To replace dimension tables', 'To hold backup data', 'A', 'Aggregates precompute summaries to accelerate analytical queries.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1671, 241, 'Which architecture is better for maintaining flexibility when dimensions change?', 'Kimball''s dimensional modeling approach', 'A single flat file', 'A normalized OLTP design only', 'A no-warehouse approach', 'A', 'Dimensional modeling by Kimball emphasizes conformed dimensions and flexible star schemas.', 'ADVANCED', 3, 'MCQ', 1),
(1672, 241, 'A slowly changing dimension (SCD) type 2 handles changes by:', 'Creating a new row with versioning for each change', 'Overwriting the old value', 'Deleting the row', 'Ignoring the change', 'A', 'SCD type 2 preserves history by adding new rows for changed values.', 'ADVANCED', 3, 'MCQ', 1),
(1673, 241, 'What is the main drawback of the snowflake schema compared to the star schema?', 'It requires more joins, slowing query performance', 'It uses too few tables', 'It stores no facts', 'It cannot support dimensions', 'A', 'Normalized dimensions in snowflake schemas increase join complexity.', 'ADVANCED', 3, 'MCQ', 1),
(1674, 241, 'Which of the following is a characteristic of a dependent data mart?', 'It is sourced from the enterprise data warehouse', 'It operates independently of the warehouse', 'It has no dimensions', 'It replaces the warehouse', 'A', 'Dependent data marts draw from a centralized warehouse for consistency.', 'ADVANCED', 3, 'MCQ', 1),
(1675, 241, 'What is the purpose of data lineage in a warehouse?', 'To track where data came from and how it was transformed', 'To hide data sources', 'To reduce storage', 'To speed up OLTP', 'A', 'Lineage documents data origin and transformation for trust and compliance.', 'ADVANCED', 3, 'MCQ', 1),
(1676, 241, 'Which process addresses inconsistent data formats during integration?', 'Data cleansing and standardization', 'Data deletion', 'Schema merging without checks', 'Index rebuilding', 'A', 'Cleansing normalizes formats so data from sources can be compared.', 'ADVANCED', 3, 'MCQ', 1),
(1677, 241, 'What is the role of metadata in a data warehouse?', 'To describe the structure, sources, and transformations of the data', 'To store transaction data', 'To replace dimension tables', 'To compress files', 'A', 'Metadata is data about data, guiding ETL and analysis.', 'ADVANCED', 3, 'MCQ', 1),
(1678, 241, 'A hub-and-spoke architecture in data warehousing refers to:', 'A central warehouse serving multiple dependent data marts', 'A network of equal peers', 'A single table', 'A point-to-point link', 'A', 'The hub warehouse feeds spokes, or dependent marts.', 'ADVANCED', 3, 'MCQ', 1),
(1679, 241, 'Which modeling technique organizes facts by multiple dimensions like a cube?', 'Multidimensional modeling', 'Flat-file modeling', 'Normalized modeling', 'ER modeling only', 'A', 'Multidimensional models present facts in a cube over dimensions.', 'ADVANCED', 3, 'MCQ', 1),
(1680, 241, 'What is the main reason warehouses refresh data in batches?', 'To integrate and transform large volumes predictably', 'To avoid transactions entirely', 'To reduce storage forever', 'To eliminate dimensions', 'A', 'Batched refreshes allow controlled ETL of large, integrated datasets.', 'ADVANCED', 3, 'MCQ', 1),
(1681, 242, 'What is the first step of ETL?', 'Extraction', 'Loading', 'Transformation', 'Reporting', 'A', 'ETL begins with extracting data from source systems.', 'BEGINNER', 1, 'MCQ', 1),
(1682, 242, 'What happens during the load phase of ETL?', 'Transformed data is written into the warehouse', 'Data is extracted', 'Reports are generated', 'Queries are written', 'A', 'Loading inserts the transformed data into target warehouse tables.', 'BEGINNER', 1, 'MCQ', 1),
(1683, 242, 'What is data cleansing?', 'Correcting or removing inaccurate data', 'Backing up data', 'Indexing data', 'Encrypting data', 'A', 'Cleansing fixes errors, duplicates, and inconsistencies in the data.', 'BEGINNER', 1, 'MCQ', 1),
(1684, 242, 'Which of the following is a data source for ETL?', 'Transactional databases', 'The warehouse itself', 'Final reports', 'Dashboards', 'A', 'ETL extracts from operational systems, files, and external sources.', 'BEGINNER', 1, 'MCQ', 1),
(1685, 242, 'What is a full load in ETL?', 'Loading the entire dataset from scratch', 'Loading only new records', 'Loading one row', 'Loading nothing', 'A', 'A full load replaces the target table with the complete dataset.', 'BEGINNER', 1, 'MCQ', 1),
(1686, 242, 'What is an incremental load?', 'Loading only data changed since the last load', 'Loading the whole dataset each time', 'Loading data once only', 'Loading indexes', 'A', 'Incremental loads move only new or updated records.', 'BEGINNER', 1, 'MCQ', 1),
(1687, 242, 'What is data profiling?', 'Examining source data to understand its quality and structure', 'Deleting data', 'Building indexes', 'Compressing files', 'A', 'Profiling analyzes sources before designing transformations.', 'BEGINNER', 1, 'MCQ', 1),
(1688, 242, 'Which of the following is a transformation operation?', 'Converting data formats', 'Reading source files', 'Backing up the database', 'Scheduling jobs', 'A', 'Transformations include format conversion, cleansing, and aggregation.', 'BEGINNER', 1, 'MCQ', 1),
(1689, 242, 'What is the target of the ETL process?', 'The data warehouse', 'The source system', 'The report printer', 'The web browser', 'A', 'ETL moves data into the warehouse for analysis.', 'BEGINNER', 1, 'MCQ', 1),
(1690, 242, 'What is a staging area in ETL?', 'A temporary storage area for data before loading', 'The final warehouse', 'A report folder', 'A backup tape', 'A', 'The staging area holds extracted data during processing.', 'BEGINNER', 1, 'MCQ', 1),
(1691, 242, 'Why is transformation necessary before loading?', 'To standardize, clean, and aggregate data for analysis', 'To reduce the number of tables', 'To delete history', 'To speed up extraction', 'A', 'Transformation integrates disparate sources into a consistent format.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1692, 242, 'What does a surrogate key mapping do in ETL?', 'It maps source values to warehouse surrogate keys', 'It deletes records', 'It generates reports', 'It encrypts data', 'A', 'Key mapping ensures correct referential integrity during loading.', 'INTERMEDIATE', 2, 'MCQ', 1),
