(1700, 242, 'Which tool category handles ETL jobs?', 'ETL tools such as Talend and Informatica', 'Web browsers', 'Text editors', 'Media players', 'A', 'Dedicated ETL tools orchestrate extraction, transformation, and loading.', 'INTERMEDIATE', 2, 'MCQ', 1),
(1701, 242, 'What is the main advantage of an ELT approach over ETL?', 'It transforms data inside the target warehouse, leveraging its power', 'It avoids transformations', 'It requires no storage', 'It cannot handle big data', 'A', 'ELT loads raw data first and transforms it in the warehouse, scaling better.', 'ADVANCED', 3, 'MCQ', 1),
