(1711, 243, 'What is an OLAP cube?', 'A multidimensional representation of data for analysis', 'A storage device', 'A web page', 'A report font', 'A', 'OLAP cubes organize measures across multiple dimensions.', 'BEGINNER', 1, 'MCQ', 1),
