(1736, 243, 'Why might ROLAP be preferred over MOLAP for very large cubes?', 'It scales using the existing relational database', 'It is always faster', 'It needs no dimensions', 'It stores no data', 'A', 'ROLAP leverages relational storage that scales with existing infrastructure.', 'ADVANCED', 3, 'MCQ', 1),
(1737, 243, 'What is the main trade-off when pre-aggregating many levels in a cube?', 'Faster queries but more storage and longer build time', 'Slower queries', 'Less data', 'No dimensions', 'A', 'Precomputation costs storage and build time in exchange for speed.', 'ADVANCED', 3, 'MCQ', 1),
