(1771, 245, 'What does the Apriori algorithm find?', 'Frequent itemsets in transactional data', 'Clusters in spatial data', 'Linear relationships', 'Anomalies', 'A', 'Apriori mines frequent itemsets for association rule discovery.', 'BEGINNER', 1, 'MCQ', 1),
