(1796, 245, 'What does a high lift value indicate in association analysis?', 'A strong positive association beyond random co-occurrence', 'No association', 'Equal probabilities', 'A low confidence', 'A', 'Lift greater than 1 signals a positive, meaningful association.', 'ADVANCED', 3, 'MCQ', 1),
(1797, 245, 'Which metric is used to evaluate the goodness of clusters without labels?', 'Silhouette coefficient', 'Accuracy', 'Confidence', 'Support', 'A', 'Silhouette measures how similar a point is to its own cluster versus others.', 'ADVANCED', 3, 'MCQ', 1),
(1798, 245, 'What does the FP-Growth tree encode?', 'Frequent itemsets compactly using linked item paths', 'Cluster centroids', 'Regression coefficients', 'Decision rules', 'A', 'The FP-tree represents the database compactly for mining.', 'ADVANCED', 3, 'MCQ', 1),
(1799, 245, 'Which problem arises when k-means is used on categorical data?', 'Euclidean distance is not meaningful for categories', 'It works perfectly', 'It requires labels', 'It cannot find centroids', 'A', 'Categorical values need encoding before distance-based clustering.', 'ADVANCED', 3, 'MCQ', 1),
(1800, 245, 'What is the outcome of a silhouette score near 1?', 'Points are well matched to their own cluster and far from others', 'Clusters overlap', 'Data is random', 'Centroids are invalid', 'A', 'High silhouette scores indicate compact, well-separated clusters.', 'ADVANCED', 3, 'MCQ', 1);
